var e=JSON.parse(`[{"wordId":19329,"answer":"on shift","form":"원형","example":"Only one nurse is on shift in the small clinic at night.","exampleTranslation":"그 작은 병원에는 밤에 간호사 한 명만 근무 중이다.","sense":"근무 중인"},{"wordId":19330,"answer":"lunch rush","form":"원형","example":"The sandwich shop runs out of bread almost every day during the lunch rush.","exampleTranslation":"그 샌드위치 가게는 점심 붐비는 시간에 거의 매일 빵이 떨어진다.","sense":"점심 붐비는 시간"},{"wordId":19331,"answer":"next in line","form":"원형","example":"My son was next in line for the slide when the bell rang.","exampleTranslation":"종이 울렸을 때 아들은 미끄럼틀 다음 차례였다.","sense":"다음 차례인"},{"wordId":19332,"answer":"loyalty program","form":"원형","example":"The coffee shop's loyalty program gives you a free drink after ten visits.","exampleTranslation":"그 커피숍의 적립 프로그램은 열 번 방문하면 음료 한 잔을 무료로 준다.","sense":"적립 프로그램"},{"wordId":19334,"answer":"my apologies","form":"원형","example":"My apologies for the late reply to your email yesterday.","exampleTranslation":"어제 보내신 이메일에 늦게 답장드려 죄송합니다.","sense":"죄송합니다"},{"wordId":19335,"answer":"I understand your frustration","form":"원형","example":"The airline agent said, \\"I understand your frustration,\\" and found me a new flight.","exampleTranslation":"항공사 직원은 \\"답답하신 마음 이해합니다.\\"라고 말하고 새 항공편을 찾아 주었다.","sense":"답답한 마음 이해합니다"},{"wordId":19336,"answer":"follow-up call","form":"원형","example":"The doctor's office made a follow-up call to check on my mother.","exampleTranslation":"병원에서 우리 어머니 상태를 확인하려고 후속 전화를 했다.","sense":"확인 전화"},{"wordId":19337,"answer":"hospitality","form":"원형","example":"The family on the farm showed us real hospitality during our trip.","exampleTranslation":"여행 중에 농장의 가족은 우리를 진심으로 환대해 주었다.","sense":"환대"},{"wordId":19338,"answer":"service with a smile","form":"원형","example":"The old man at the newsstand always offers service with a smile.","exampleTranslation":"신문 가판대 할아버지는 늘 웃으며 친절하게 응대하신다.","sense":"친절한 서비스"},{"wordId":19339,"answer":"friendly staff","form":"원형","example":"The hospital has friendly staff who explain everything clearly.","exampleTranslation":"그 병원에는 모든 걸 분명하게 설명해 주는 친절한 직원들이 있다.","sense":"친절한 직원들"},{"wordId":19340,"answer":"closing time","form":"원형","example":"The library lights blink ten minutes before closing time.","exampleTranslation":"도서관 조명은 마감 시간 십 분 전에 깜빡인다.","sense":"마감 시간"},{"wordId":19341,"answer":"price match","form":"원형","example":"Some electronics stores will price match any online deal you show them.","exampleTranslation":"일부 전자제품 매장은 보여 주는 어떤 온라인 할인가에도 가격을 맞춰 준다.","sense":"가격을 맞춰 주다"},{"wordId":19342,"answer":"manager on duty","form":"원형","example":"The cashier asked the manager on duty to open another register.","exampleTranslation":"계산원은 근무 중인 책임자에게 계산대를 하나 더 열어 달라고 했다.","sense":"근무 중인 책임자"},{"wordId":19343,"answer":"come again","form":"원형","example":"The owner of the noodle shop waved and said, \\"Please come again!\\"","exampleTranslation":"국숫집 주인은 손을 흔들며 \\"또 오세요!\\"라고 말했다.","sense":"또 오세요"},{"wordId":19344,"answer":"we value your feedback","form":"원형","example":"The survey email began with the line, \\"We value your feedback.\\"","exampleTranslation":"설문 이메일은 \\"고객님의 의견을 소중히 여깁니다.\\"라는 문장으로 시작했다.","sense":"의견을 소중히 여깁니다"},{"wordId":19345,"answer":"handle a complaint","form":"원형","example":"My manager showed me how to handle a complaint about a late delivery.","exampleTranslation":"매니저는 배송 지연 불만을 처리하는 방법을 나에게 보여 주었다.","sense":"불만을 처리하다"},{"wordId":19346,"answer":"employee discount","form":"원형","example":"My sister works at a bookstore and gets a nice employee discount.","exampleTranslation":"여동생은 서점에서 일해서 직원 할인을 꽤 받는다.","sense":"직원 할인"},{"wordId":19347,"answer":"first-time customer","form":"원형","example":"The gym gave every first-time customer a free towel and water bottle.","exampleTranslation":"헬스장은 첫 방문 고객 모두에게 무료 수건과 물병을 주었다.","sense":"첫 방문 고객"},{"wordId":19348,"answer":"hold it for you","form":"원형","example":"The bakery has one cake left, and they can hold it for you until noon.","exampleTranslation":"빵집에 케이크가 하나 남았는데 정오까지 따로 맡아 둘 수 있대.","sense":"따로 보관해 두다"},{"wordId":19349,"answer":"special request","form":"원형","example":"The restaurant was happy to help with our special request for a birthday candle.","exampleTranslation":"식당은 생일 초를 달라는 우리의 특별 요청을 기꺼이 들어주었다.","sense":"특별 요청"},{"wordId":19350,"answer":"staff only","form":"원형","example":"The sign on the kitchen door at the café says staff only.","exampleTranslation":"카페 주방 문의 표지판에는 직원 전용이라고 적혀 있다.","sense":"직원 전용"},{"wordId":19351,"answer":"grocery list","form":"원형","example":"My son added cookies to the grocery list when I was not looking.","exampleTranslation":"내가 안 보는 사이에 아들이 장보기 목록에 쿠키를 추가했다.","sense":"장보기 목록"},{"wordId":19352,"answer":"produce section","form":"원형","example":"My daughter loves to pick the apples in the produce section.","exampleTranslation":"딸은 청과 코너에서 사과를 고르는 걸 좋아한다.","sense":"청과 코너"},{"wordId":19353,"answer":"frozen food aisle","form":"원형","example":"My kids always ask for pizza when we walk down the frozen food aisle.","exampleTranslation":"냉동식품 코너를 지날 때마다 아이들은 피자를 사 달라고 한다.","sense":"냉동식품 코너"},{"wordId":19354,"answer":"dairy section","form":"원형","example":"The milk in the dairy section was on sale this morning.","exampleTranslation":"오늘 아침 유제품 코너의 우유가 할인 중이었다.","sense":"유제품 코너"},{"wordId":19355,"answer":"deli counter","form":"원형","example":"The worker at the deli counter gave my son a free slice of cheese.","exampleTranslation":"델리 코너 직원이 아들에게 치즈 한 조각을 무료로 주었다.","sense":"델리 코너"},{"wordId":19356,"answer":"bakery section","form":"원형","example":"My kids always want a donut from the bakery section on Saturdays.","exampleTranslation":"우리 아이들은 토요일마다 빵 코너에서 도넛을 먹고 싶어 한다.","sense":"빵 코너"},{"wordId":19357,"answer":"checkout line","form":"원형","example":"I met my old teacher while I was waiting in the checkout line.","exampleTranslation":"계산대 줄에서 기다리다가 옛 선생님을 만났다.","sense":"계산대 줄"},{"wordId":19358,"answer":"self-checkouts","form":"복수형","example":"Our local supermarket added six new self-checkouts near the exit.","exampleTranslation":"우리 동네 슈퍼마켓은 출구 근처에 새 셀프 계산대 여섯 대를 들였다.","sense":"셀프 계산대"},{"wordId":19359,"answer":"express lane","form":"원형","example":"The man in the express lane had a full cart of groceries.","exampleTranslation":"빠른 계산대에 선 남자는 장바구니가 가득 차 있었다.","sense":"빠른 계산대"},{"wordId":19360,"answer":"paper or plastic","form":"원형","example":"My grandson laughed when the cashier asked him, \\"Paper or plastic?\\"","exampleTranslation":"계산원이 \\"종이봉투요, 비닐봉투요?\\"라고 묻자 손자가 웃었다.","sense":"종이요, 비닐이요"},{"wordId":19361,"answer":"on special","form":"원형","example":"Strawberries are on special at the farmers market this weekend.","exampleTranslation":"이번 주말 농산물 시장에서 딸기가 특가 중이다.","sense":"특가 중인"},{"wordId":19362,"answer":"buy one get one free","form":"원형","example":"The bakery has a buy one get one free deal on bagels every Monday.","exampleTranslation":"그 빵집은 매주 월요일에 베이글 하나 사면 하나 더 주는 행사를 한다.","sense":"하나 사면 하나 더"},{"wordId":19363,"answer":"store brand","form":"원형","example":"My mom buys the store brand pasta because it is just as good.","exampleTranslation":"엄마는 품질이 똑같이 좋아서 마트 자체 브랜드 파스타를 사신다.","sense":"자체 브랜드"},{"wordId":19364,"answer":"name brand","form":"원형","example":"My dad says the name brand batteries last longer than the cheap ones.","exampleTranslation":"아빠는 유명 브랜드 건전지가 싼 것보다 오래간다고 하신다.","sense":"유명 브랜드"},{"wordId":19365,"answer":"unit price","form":"원형","example":"My grandmother always compares the unit price before she picks a coffee.","exampleTranslation":"할머니는 커피를 고르기 전에 항상 단위 가격을 비교하신다.","sense":"단위 가격"},{"wordId":19366,"answer":"shopping basket","form":"원형","example":"My son proudly carried the shopping basket around the store for me.","exampleTranslation":"아들은 나를 위해 매장 안에서 장바구니를 자랑스럽게 들고 다녔다.","sense":"장바구니"},{"wordId":19367,"answer":"membership card","form":"원형","example":"I left my gym membership card at home, so I could not get in.","exampleTranslation":"헬스장 회원 카드를 집에 두고 와서 들어갈 수 없었다.","sense":"회원 카드"},{"wordId":19368,"answer":"canned goods","form":"원형","example":"The school is collecting canned goods for families in need this month.","exampleTranslation":"학교는 이번 달에 어려운 가정을 위해 통조림 식품을 모으고 있다.","sense":"통조림 식품"},{"wordId":19369,"answer":"household items","form":"원형","example":"The new dollar store sells cheap household items like brooms and buckets.","exampleTranslation":"새로 생긴 균일가 매장은 빗자루와 양동이 같은 싼 생활용품을 판다.","sense":"생활용품"},{"wordId":19370,"answer":"toiletries","form":"원형","example":"The hotel gives free toiletries to every guest at check-in.","exampleTranslation":"그 호텔은 체크인할 때 모든 투숙객에게 무료 세면용품을 준다.","sense":"세면용품"},{"wordId":19371,"answer":"bag the groceries","form":"원형","example":"The cashier scanned our items while her coworker helped bag the groceries.","exampleTranslation":"계산원이 물건을 찍는 동안 동료가 장 본 물건을 봉투에 담는 걸 도왔다.","sense":"봉투에 담다"},{"wordId":19372,"answer":"snack aisle","form":"원형","example":"The new snack aisle has chips from all over the world.","exampleTranslation":"새 과자 코너에는 전 세계에서 온 감자칩이 있다.","sense":"과자 코너"},{"wordId":19373,"answer":"stock up on","form":"원형","example":"Before winter, my parents like to stock up on firewood and soup.","exampleTranslation":"겨울이 오기 전에 부모님은 장작과 수프를 사서 쟁여 두는 걸 좋아하신다.","sense":"쟁여 두다"},{"wordId":19374,"answer":"restocking","form":"-ing형","example":"The workers are restocking the shelves with fresh bread right now.","exampleTranslation":"직원들이 지금 선반에 신선한 빵을 다시 채우고 있다.","sense":"다시 채우다"},{"wordId":19375,"answer":"top shelf","form":"원형","example":"My mom hides the candy on the top shelf so the kids cannot reach it.","exampleTranslation":"엄마는 아이들이 손이 닿지 않도록 사탕을 맨 위 칸에 숨기신다.","sense":"맨 위 칸"},{"wordId":19376,"answer":"free sample","form":"원형","example":"The cheese shop gave every customer a free sample at the door.","exampleTranslation":"치즈 가게는 입구에서 모든 손님에게 무료 시식을 주었다.","sense":"무료 시식"},{"wordId":19377,"answer":"rotisserie chicken","form":"원형","example":"We took a rotisserie chicken and some salad to the park for dinner.","exampleTranslation":"우리는 저녁으로 통구이 치킨과 샐러드를 공원에 가져갔다.","sense":"통구이 치킨"},{"wordId":19378,"answer":"ground beef","form":"원형","example":"My grandmother uses ground beef in her famous meat sauce.","exampleTranslation":"할머니는 유명한 고기 소스에 다진 소고기를 쓰신다.","sense":"다진 소고기"},{"wordId":19379,"answer":"boneless","form":"원형","example":"My kids only eat boneless fish because they hate the small bones.","exampleTranslation":"아이들은 작은 가시를 싫어해서 가시를 발라낸 생선만 먹는다.","sense":"뼈를 발라낸"},{"wordId":19380,"answer":"organic","form":"원형","example":"The school garden grows organic tomatoes without any chemicals.","exampleTranslation":"학교 텃밭은 화학 약품 없이 유기농 토마토를 기른다.","sense":"유기농의"},{"wordId":19381,"answer":"fresh produce","form":"원형","example":"The hotel buffet serves fresh produce from the farm next door.","exampleTranslation":"호텔 뷔페는 옆 농장에서 온 신선 농산물을 낸다.","sense":"신선 농산물"},{"wordId":19382,"answer":"grocery run","form":"원형","example":"My roommate made a late-night grocery run for milk and cereal.","exampleTranslation":"룸메이트는 우유와 시리얼을 사러 늦은 밤 장을 보러 잠깐 다녀왔다.","sense":"장보러 다녀오기"},{"wordId":19383,"answer":"grocery delivery","form":"원형","example":"My grandparents started using grocery delivery after Grandpa hurt his knee.","exampleTranslation":"할아버지가 무릎을 다치신 뒤로 조부모님은 식료품 배달을 이용하기 시작하셨다.","sense":"식료품 배달"},{"wordId":19384,"answer":"price check","form":"원형","example":"The cashier called for a price check on my bag of oranges.","exampleTranslation":"계산원은 내 오렌지 봉지의 가격 확인을 요청했다.","sense":"가격 확인"},{"wordId":19385,"answer":"bag fee","form":"원형","example":"Many shoppers bring cloth bags because the bag fee keeps going up.","exampleTranslation":"봉투값이 계속 올라서 많은 손님이 천 가방을 가져온다.","sense":"봉투값"},{"wordId":19386,"answer":"pre-packaged","form":"원형","example":"The office kitchen is full of pre-packaged snacks and juice boxes.","exampleTranslation":"사무실 탕비실은 미리 포장된 간식과 주스 팩으로 가득하다.","sense":"미리 포장된"},{"wordId":19387,"answer":"family size","form":"원형","example":"My sister always buys the family size box of cereal for her three kids.","exampleTranslation":"여동생은 세 아이를 위해 항상 대용량 시리얼 상자를 산다.","sense":"대용량"},{"wordId":19388,"answer":"travel size","form":"원형","example":"The hotel gave us a travel size bottle of lotion for free.","exampleTranslation":"호텔은 여행용 크기의 로션 한 병을 무료로 주었다.","sense":"여행용 크기"},{"wordId":19389,"answer":"bottled water","form":"원형","example":"The hikers carried bottled water and sandwiches in their backpacks.","exampleTranslation":"등산객들은 배낭에 생수와 샌드위치를 넣어 다녔다.","sense":"생수"},{"wordId":19390,"answer":"carton of eggs","form":"원형","example":"My son dropped a carton of eggs on the kitchen floor this morning.","exampleTranslation":"아들이 오늘 아침 부엌 바닥에 달걀 한 판을 떨어뜨렸다.","sense":"달걀 한 판"},{"wordId":19391,"answer":"loaf of bread","form":"원형","example":"My grandmother bakes a fresh loaf of bread every Sunday morning.","exampleTranslation":"할머니는 매주 일요일 아침 갓 구운 빵 한 덩이를 만드신다.","sense":"빵 한 덩이"},{"wordId":19392,"answer":"six-packs","form":"복수형","example":"We bought three six-packs of lemonade for the school picnic.","exampleTranslation":"학교 소풍을 위해 레모네이드 여섯 개 묶음을 세 개 샀다.","sense":"여섯 개 묶음"},{"wordId":19393,"answer":"frozen meals","form":"원형","example":"My college roommate lived on frozen meals during exam week.","exampleTranslation":"대학 룸메이트는 시험 주간에 냉동 간편식으로 버텼다.","sense":"냉동 간편식"},{"wordId":19394,"answer":"instant noodles","form":"원형","example":"We packed instant noodles for our camping trip in the mountains.","exampleTranslation":"우리는 산으로 가는 캠핑 여행에 라면을 챙겼다.","sense":"라면"},{"wordId":19395,"answer":"condiments","form":"원형","example":"The food truck keeps all the condiments on a small table outside.","exampleTranslation":"그 푸드 트럭은 모든 소스류를 바깥 작은 탁자에 둔다.","sense":"소스류"},{"wordId":19396,"answer":"discount sticker","form":"원형","example":"My mom bought a cake with a discount sticker for our dessert tonight.","exampleTranslation":"엄마가 오늘 밤 디저트로 할인 스티커가 붙은 케이크를 사 오셨다.","sense":"할인 스티커"},{"wordId":19397,"answer":"marked down","form":"원형","example":"All the winter coats were marked down at the mall after New Year.","exampleTranslation":"새해가 지나자 쇼핑몰의 겨울 코트가 모두 가격이 인하되었다.","sense":"가격이 인하된"},{"wordId":19398,"answer":"half price","form":"원형","example":"Movie tickets are half price for students on Tuesday nights.","exampleTranslation":"화요일 밤에는 학생 영화표가 반값이다.","sense":"반값"},{"wordId":19399,"answer":"scan the barcode","form":"원형","example":"The librarian will scan the barcode on each book you borrow.","exampleTranslation":"사서가 빌리는 책마다 바코드를 찍어 줄 것이다.","sense":"바코드를 찍다"},{"wordId":19400,"answer":"ten items or less","form":"원형","example":"The sign above the fast lane says \\"ten items or less\\" in big letters.","exampleTranslation":"빠른 계산대 위 표지판에는 큰 글씨로 \\"열 개 이하 전용\\"이라고 적혀 있다.","sense":"열 개 이하 전용"},{"wordId":19401,"answer":"potted plant","form":"원형","example":"My coworkers gave me a potted plant for my new office.","exampleTranslation":"동료들이 내 새 사무실에 놓으라고 화분 식물을 선물했다.","sense":"화분 식물"},{"wordId":19402,"answer":"flower pot","form":"원형","example":"My daughter painted a flower pot for her grandmother's birthday.","exampleTranslation":"딸은 할머니 생신 선물로 화분에 그림을 그렸다.","sense":"화분"},{"wordId":19403,"answer":"potting soil","form":"원형","example":"The garden store sells potting soil in small and large bags.","exampleTranslation":"원예 용품점은 배양토를 작은 봉지와 큰 봉지로 판다.","sense":"배양토"},{"wordId":19404,"answer":"repotted","form":"과거형","example":"My grandmother repotted all her herbs on the balcony last weekend.","exampleTranslation":"할머니는 지난 주말 발코니에 있는 허브를 모두 분갈이하셨다.","sense":"분갈이하다"},{"wordId":19405,"answer":"root-bound","form":"원형","example":"The gardener said the old lemon tree was root-bound in its pot.","exampleTranslation":"정원사는 오래된 레몬나무가 화분에 뿌리가 꽉 찼다고 말했다.","sense":"뿌리가 꽉 찬"},{"wordId":19406,"answer":"drainage hole","form":"원형","example":"This cute ceramic pot looks nice, but it has no drainage hole at the bottom.","exampleTranslation":"이 귀여운 도자기 화분은 예쁘지만 바닥에 배수 구멍이 없다.","sense":"배수 구멍"},{"wordId":19407,"answer":"overwaters","form":"3인칭 단수형","example":"My roommate overwaters her ferns every day, so the soil never dries out.","exampleTranslation":"내 룸메이트는 매일 고사리에 물을 너무 많이 줘서 흙이 전혀 마르지 않는다.","sense":"물을 너무 주다"},{"wordId":19408,"answer":"watering can","form":"원형","example":"My daughter carried the small watering can around the yard to help her grandma.","exampleTranslation":"딸은 할머니를 도우려고 작은 물뿌리개를 들고 마당을 돌아다녔다.","sense":"물뿌리개"},{"wordId":19409,"answer":"wilted","form":"과거분사","example":"We threw away the wilted flowers from the kitchen table this morning.","exampleTranslation":"우리는 오늘 아침 식탁 위의 시든 꽃을 버렸다.","sense":"시들다"},{"wordId":19410,"answer":"fertilizers","form":"복수형","example":"The garden center sells many different fertilizers for roses and vegetables.","exampleTranslation":"원예 용품점은 장미와 채소용으로 여러 가지 비료를 판다.","sense":"비료"},{"wordId":19411,"answer":"compost","form":"원형","example":"My neighbor gave us a bag of rich compost for our new flower boxes.","exampleTranslation":"이웃이 새 꽃 상자에 쓰라고 영양 많은 퇴비 한 자루를 줬다.","sense":"퇴비"},{"wordId":19412,"answer":"seedlings","form":"복수형","example":"The school sold pepper seedlings at the spring fair to raise money.","exampleTranslation":"학교는 기금을 모으려고 봄 장터에서 고추 모종을 팔았다.","sense":"모종"},{"wordId":19413,"answer":"sprouting","form":"-ing형","example":"Look, the potatoes in the cupboard are sprouting little green shoots again.","exampleTranslation":"봐, 찬장에 있는 감자에서 또 작은 초록 싹이 트고 있어.","sense":"싹이 트다"},{"wordId":19414,"answer":"plant seeds","form":"원형","example":"The kids love to plant seeds in paper cups at the community center.","exampleTranslation":"아이들은 주민 센터에서 종이컵에 씨앗 심는 것을 아주 좋아한다.","sense":"씨앗을 심다"},{"wordId":19415,"answer":"prunes","form":"3인칭 단수형","example":"Our landlord prunes the apple tree in the backyard every winter.","exampleTranslation":"집주인은 매년 겨울 뒷마당 사과나무 가지를 친다.","sense":"가지치기하다"},{"wordId":19416,"answer":"trim the hedge","form":"원형","example":"Could you help me trim the hedge before the guests arrive on Sunday?","exampleTranslation":"일요일에 손님들이 오기 전에 산울타리 다듬는 것 좀 도와줄래?","sense":"산울타리를 다듬다"},{"wordId":19417,"answer":"mow the lawn","form":"원형","example":"My brother earns extra money when he helps our neighbors mow the lawn.","exampleTranslation":"내 남동생은 이웃들의 잔디 깎는 일을 도와 용돈을 번다.","sense":"잔디를 깎다"},{"wordId":19418,"answer":"pull weeds","form":"원형","example":"Grandpa pays us a dollar an hour to pull weeds in his garden.","exampleTranslation":"할아버지는 정원 잡초를 뽑으면 한 시간에 일 달러씩 주신다.","sense":"잡초를 뽑다"},{"wordId":19419,"answer":"aphids","form":"원형","example":"We sprayed soapy water on the plants to get rid of the aphids.","exampleTranslation":"진딧물을 없애려고 식물에 비눗물을 뿌렸다.","sense":"진딧물"},{"wordId":19420,"answer":"pesticides","form":"복수형","example":"Organic farms do not use strong chemical pesticides on their crops.","exampleTranslation":"유기농 농장은 작물에 독한 화학 살충제를 쓰지 않는다.","sense":"살충제"},{"wordId":19421,"answer":"fungus gnats","form":"원형","example":"I put a yellow sticky trap in the pot to catch the fungus gnats.","exampleTranslation":"뿌리파리를 잡으려고 화분에 노란 끈끈이 트랩을 꽂았다.","sense":"뿌리파리"},{"wordId":19422,"answer":"yellow leaves","form":"원형","example":"The clerk at the plant shop said the yellow leaves come from cold drafts.","exampleTranslation":"식물 가게 직원은 노랗게 변한 잎이 찬 바람 때문이라고 했다.","sense":"노랗게 변한 잎"},{"wordId":19423,"answer":"direct sunlight","form":"원형","example":"The doctor told me to keep the new baby out of direct sunlight.","exampleTranslation":"의사는 갓난아기를 직사광선에 두지 말라고 했다.","sense":"직사광선"},{"wordId":19424,"answer":"indirect light","form":"원형","example":"This snake plant does fine in a bathroom with only indirect light.","exampleTranslation":"이 산세베리아는 간접광만 드는 욕실에서도 잘 자란다.","sense":"간접광"},{"wordId":19425,"answer":"shade-loving","form":"원형","example":"Our backyard is under big trees, so we need shade-loving flowers there.","exampleTranslation":"우리 뒷마당은 큰 나무 아래라서 그늘을 좋아하는 꽃이 필요하다.","sense":"그늘을 좋아하는"},{"wordId":19426,"answer":"more low-maintenance","form":"비교급","example":"After the baby was born, we switched to a more low-maintenance garden.","exampleTranslation":"아기가 태어난 뒤 우리는 손이 덜 가는 정원으로 바꿨다.","sense":"손이 별로 안 가는"},{"wordId":19427,"answer":"garden shears","form":"원형","example":"Please put the garden shears back in the shed when you finish.","exampleTranslation":"다 쓰면 전지가위를 창고에 다시 넣어 줘.","sense":"전지가위"},{"wordId":19428,"answer":"spider plant","form":"원형","example":"My coworker gave me a baby spider plant in a small glass jar.","exampleTranslation":"동료가 작은 유리병에 담긴 어린 접란을 줬다.","sense":"접란"},{"wordId":19429,"answer":"cacti","form":"복수형","example":"The desert museum has hundreds of cacti from all over Mexico.","exampleTranslation":"그 사막 박물관에는 멕시코 전역에서 온 선인장이 수백 그루 있다.","sense":"선인장"},{"wordId":19430,"answer":"herb garden","form":"원형","example":"The school cafeteria uses parsley and chives from its own herb garden.","exampleTranslation":"학교 식당은 자체 허브 텃밭에서 기른 파슬리와 차이브를 쓴다.","sense":"허브 텃밭"},{"wordId":19431,"answer":"balcony garden","form":"원형","example":"My aunt spends every summer evening relaxing in her balcony garden.","exampleTranslation":"이모는 여름 저녁마다 베란다 정원에서 쉬며 시간을 보낸다.","sense":"베란다 정원"},{"wordId":19432,"answer":"raised bed","form":"원형","example":"A raised bed is easier on your back because you do not bend much.","exampleTranslation":"높임 화단은 많이 구부리지 않아도 돼서 허리에 덜 부담이 된다.","sense":"높임 화단"},{"wordId":19433,"answer":"vegetable patch","form":"원형","example":"The rabbits keep getting into our vegetable patch and eating the lettuce.","exampleTranslation":"토끼들이 계속 우리 채소밭에 들어와 상추를 먹는다.","sense":"작은 채소밭"},{"wordId":19434,"answer":"hanging basket","form":"원형","example":"The restaurant has a hanging basket of red flowers above the front door.","exampleTranslation":"그 식당은 정문 위에 빨간 꽃이 담긴 걸이 화분을 달아 두었다.","sense":"걸이 화분"},{"wordId":19435,"answer":"garden hose","form":"원형","example":"The kids ran through the spray from the garden hose on a hot afternoon.","exampleTranslation":"아이들은 더운 오후에 정원용 호스에서 나오는 물줄기 사이로 뛰어다녔다.","sense":"정원용 호스"},{"wordId":19436,"answer":"sprinklers","form":"복수형","example":"The sprinklers on the soccer field turned on in the middle of our game.","exampleTranslation":"경기 도중에 축구장 스프링클러가 켜졌다.","sense":"스프링클러"},{"wordId":19437,"answer":"shovels","form":"복수형","example":"After the big snowstorm, every family on our street was out with shovels.","exampleTranslation":"큰 눈보라가 지나간 뒤 우리 동네 모든 가족이 삽을 들고 나왔다.","sense":"삽"},{"wordId":19438,"answer":"gardening gloves","form":"원형","example":"I keep a pair of gardening gloves next to the back door.","exampleTranslation":"나는 뒷문 옆에 원예용 장갑 한 켤레를 둔다.","sense":"원예용 장갑"},{"wordId":19439,"answer":"thorns","form":"복수형","example":"Be careful with those blackberry bushes because they have sharp thorns.","exampleTranslation":"그 블랙베리 덤불은 가시가 날카로우니 조심해.","sense":"가시"},{"wordId":19440,"answer":"in bloom","form":"원형","example":"We timed our trip to the botanical garden for when the tulips were in bloom.","exampleTranslation":"우리는 튤립이 만개할 때에 맞춰 식물원 여행을 잡았다.","sense":"꽃이 핀"},{"wordId":19441,"answer":"flower bed","form":"원형","example":"My little sister planted sunflowers in the flower bed by the mailbox.","exampleTranslation":"여동생이 우편함 옆 화단에 해바라기를 심었다.","sense":"화단"},{"wordId":19442,"answer":"bulbs","form":"복수형","example":"The garden club handed out free daffodil bulbs at the library on Saturday.","exampleTranslation":"원예 동호회가 토요일에 도서관에서 수선화 구근을 무료로 나눠 줬다.","sense":"구근"},{"wordId":19443,"answer":"mulch","form":"원형","example":"The park workers put fresh mulch under the trees near the playground.","exampleTranslation":"공원 직원들이 놀이터 근처 나무 아래에 새 뿌리 덮개를 깔았다.","sense":"뿌리 덮개"},{"wordId":19444,"answer":"root rot","form":"원형","example":"My favorite houseplant died from root rot while I was on vacation.","exampleTranslation":"휴가 간 사이 가장 아끼던 화분이 뿌리가 썩어 죽었다.","sense":"뿌리 썩음"},{"wordId":19445,"answer":"grow from seed","form":"원형","example":"My grandmother says tomatoes are easy to grow from seed in egg cartons.","exampleTranslation":"할머니는 토마토는 달걀판에 씨앗부터 키우기 쉽다고 하신다.","sense":"씨앗부터 키우다"},{"wordId":19446,"answer":"propagating","form":"-ing형","example":"My sister is propagating her pothos in jars on the kitchen windowsill.","exampleTranslation":"언니는 부엌 창턱의 병에서 스킨답서스를 번식시키고 있다.","sense":"번식시키다","alts":["breeding"]},{"wordId":19447,"answer":"cuttings","form":"복수형","example":"I shared a few cuttings of my mint with everyone in the office.","exampleTranslation":"사무실 사람들에게 내 민트 꺾꽂이 가지를 몇 개씩 나눠 줬다.","sense":"꺾꽂이 가지"},{"wordId":19448,"answer":"self-watering pot","form":"원형","example":"My mom bought a self-watering pot for the plant in her office.","exampleTranslation":"엄마는 사무실 식물을 위해 자동 급수 화분을 샀다.","sense":"자동 급수 화분"},{"wordId":19449,"answer":"grow light","form":"원형","example":"The small grow light keeps my lettuce growing even in winter.","exampleTranslation":"작은 식물 생장등 덕분에 겨울에도 상추가 계속 자란다.","sense":"식물 생장등"},{"wordId":19450,"answer":"harvesting","form":"-ing형","example":"The whole village is harvesting rice in the fields this week.","exampleTranslation":"이번 주에 온 마을이 들판에서 벼를 수확하고 있다.","sense":"수확하다"},{"wordId":19451,"answer":"recyclable","form":"원형","example":"Before you throw out that box, check if the tape is recyclable.","exampleTranslation":"그 상자를 버리기 전에 테이프가 재활용 가능한지 확인해.","sense":"재활용 가능한"},{"wordId":19452,"answer":"single-use plastic","form":"원형","example":"Our school picnic this year will have no single-use plastic at all.","exampleTranslation":"올해 학교 소풍에는 일회용 플라스틱이 전혀 없을 것이다.","sense":"일회용 플라스틱"},{"wordId":19453,"answer":"plastic straw","form":"원형","example":"My niece asked the waiter for a paper straw instead of a plastic straw.","exampleTranslation":"조카는 종업원에게 플라스틱 빨대 대신 종이 빨대를 달라고 했다.","sense":"플라스틱 빨대"},{"wordId":19454,"answer":"plastic bag ban","form":"원형","example":"Some shoppers complained about the plastic bag ban at first, but now they accept it.","exampleTranslation":"처음엔 일부 손님들이 비닐봉지 금지에 불평했지만 지금은 받아들인다.","sense":"비닐봉지 금지"},{"wordId":19455,"answer":"bring your own cup","form":"원형","example":"The sign at the coffee shop said, \\"Bring your own cup and save fifty cents.\\"","exampleTranslation":"커피숍 안내문에는 \\"개인 컵을 가져오시면 오십 센트를 아낄 수 있어요.\\"라고 적혀 있었다.","sense":"개인 컵을 가져오다"},{"wordId":19456,"answer":"carbon footprint","form":"원형","example":"Eating less meat can help lower your family's carbon footprint.","exampleTranslation":"고기를 덜 먹으면 가족의 탄소 발자국을 줄이는 데 도움이 된다.","sense":"탄소 발자국"},{"wordId":19457,"answer":"go green","form":"원형","example":"Our apartment building wants to go green by adding a recycling room.","exampleTranslation":"우리 아파트는 분리수거실을 만들어 친환경으로 바꾸려 한다.","sense":"친환경적으로 바꾸다"},{"wordId":19458,"answer":"more eco-friendly","form":"비교급","example":"Trains are more eco-friendly than planes for short trips.","exampleTranslation":"짧은 여행에는 기차가 비행기보다 더 친환경적이다.","sense":"친환경적인"},{"wordId":19459,"answer":"biodegradable","form":"원형","example":"My sister only buys biodegradable trash bags for her kitchen.","exampleTranslation":"언니는 부엌에서 생분해성 쓰레기봉투만 산다.","sense":"생분해성의"},{"wordId":19460,"answer":"compostable","form":"원형","example":"Are these paper plates compostable, or should I put them in the trash?","exampleTranslation":"이 종이 접시는 퇴비로 만들 수 있어, 아니면 쓰레기통에 버려야 해?","sense":"퇴비화 가능한"},{"wordId":19461,"answer":"food waste","form":"원형","example":"The school cafeteria started weighing its food waste after every lunch.","exampleTranslation":"학교 식당은 점심마다 음식물 쓰레기 무게를 재기 시작했다.","sense":"음식물 쓰레기"},{"wordId":19462,"answer":"landfills","form":"복수형","example":"Old mattresses take up a lot of space in landfills across the country.","exampleTranslation":"낡은 매트리스가 전국 쓰레기 매립지에서 많은 공간을 차지한다.","sense":"쓰레기 매립지"},{"wordId":19463,"answer":"bottle deposit","form":"원형","example":"My kids collect cans from the party to get the bottle deposit money.","exampleTranslation":"아이들은 빈 병 보증금을 받으려고 파티에서 캔을 모은다.","sense":"빈 병 보증금"},{"wordId":19464,"answer":"e-waste","form":"원형","example":"The library collects e-waste like old laptops and cables once a month.","exampleTranslation":"도서관은 한 달에 한 번 낡은 노트북과 케이블 같은 전자 폐기물을 수거한다.","sense":"전자 폐기물"},{"wordId":19465,"answer":"air pollution","form":"원형","example":"The city closed some roads on Sunday to reduce air pollution downtown.","exampleTranslation":"시는 도심의 대기 오염을 줄이려고 일요일에 일부 도로를 막았다.","sense":"대기 오염"},{"wordId":19466,"answer":"air quality","form":"원형","example":"We bought an air purifier because the air quality in our apartment was poor.","exampleTranslation":"아파트 공기 질이 나빠서 공기청정기를 샀다.","sense":"공기 질"},{"wordId":19467,"answer":"smog","form":"원형","example":"Our flight was delayed because heavy smog covered the airport.","exampleTranslation":"짙은 스모그가 공항을 덮어 비행기가 지연됐다.","sense":"스모그"},{"wordId":19468,"answer":"exhaust fumes","form":"원형","example":"Please close the garage door so the exhaust fumes do not come inside.","exampleTranslation":"배기가스가 안으로 들어오지 않게 차고 문을 닫아 줘.","sense":"배기가스"},{"wordId":19469,"answer":"global warming","form":"원형","example":"My son wrote a school report about global warming and melting ice.","exampleTranslation":"아들은 지구 온난화와 녹는 얼음에 관한 학교 보고서를 썼다.","sense":"지구 온난화"},{"wordId":19470,"answer":"climate change","form":"원형","example":"The museum has a new exhibit that explains climate change to children.","exampleTranslation":"박물관에 아이들에게 기후 변화를 설명하는 새 전시가 생겼다.","sense":"기후 변화"},{"wordId":19471,"answer":"renewable energy","form":"원형","example":"Our university now runs most of its buildings on renewable energy.","exampleTranslation":"우리 대학은 이제 대부분의 건물을 재생 에너지로 운영한다.","sense":"재생 에너지"},{"wordId":19472,"answer":"solar panels","form":"원형","example":"The school installed solar panels on the gym roof over the summer.","exampleTranslation":"학교는 여름 동안 체육관 지붕에 태양광 패널을 설치했다.","sense":"태양광 패널"},{"wordId":19473,"answer":"most energy-efficient","form":"최상급","example":"The salesman showed us the most energy-efficient washing machine in the store.","exampleTranslation":"판매원은 매장에서 에너지 효율이 가장 높은 세탁기를 보여 줬다.","sense":"에너지 효율이 높은"},{"wordId":19474,"answer":"leave the lights on","form":"원형","example":"My dad gets upset when we leave the lights on in empty rooms.","exampleTranslation":"아빠는 우리가 빈방에 불을 켜 둔 채로 두면 화를 내신다.","sense":"불을 켜 두다"},{"wordId":19475,"answer":"unplugged","form":"과거형","example":"Before our trip last week, I unplugged the TV and the microwave.","exampleTranslation":"지난주 여행 전에 나는 텔레비전과 전자레인지 플러그를 뽑았다.","sense":"플러그를 뽑다"},{"wordId":19476,"answer":"conserve water","form":"원형","example":"The hotel asks guests to conserve water by reusing their towels.","exampleTranslation":"호텔은 수건을 다시 써서 물을 아껴 달라고 손님들에게 부탁한다.","sense":"물을 아끼다"},{"wordId":19477,"answer":"tap water","form":"원형","example":"I fill my water bottle with tap water before I leave the house.","exampleTranslation":"나는 집을 나서기 전에 물병에 수돗물을 채운다.","sense":"수돗물"},{"wordId":19478,"answer":"bike to work","form":"원형","example":"Many people in our office bike to work when the weather is nice.","exampleTranslation":"날씨가 좋으면 우리 회사 사람들 다수가 자전거로 출근한다.","sense":"자전거로 출근하다"},{"wordId":19479,"answer":"thrift store","form":"원형","example":"My sister donated three bags of old clothes to the thrift store downtown.","exampleTranslation":"언니는 시내 중고 가게에 헌 옷 세 봉지를 기부했다.","sense":"중고 가게"},{"wordId":19480,"answer":"upcycled","form":"과거형","example":"Last month my dad upcycled an old ladder into a bookshelf.","exampleTranslation":"지난달 아빠는 낡은 사다리를 책장으로 업사이클했다.","sense":"업사이클하다"},{"wordId":19481,"answer":"plastic-free","form":"원형","example":"The new grocery store downtown is completely plastic-free, even at the checkout.","exampleTranslation":"시내에 새로 생긴 식료품점은 계산대까지 완전히 플라스틱이 없다.","sense":"플라스틱 없는"},{"wordId":19482,"answer":"zero waste","form":"원형","example":"The cafe near my office follows zero waste rules and uses only real dishes.","exampleTranslation":"회사 근처 카페는 제로 웨이스트 원칙을 따라 진짜 그릇만 쓴다.","sense":"제로 웨이스트"},{"wordId":19483,"answer":"refill station","form":"원형","example":"I brought my old bottles to the refill station to get more dish soap.","exampleTranslation":"주방 세제를 더 받으려고 리필 스테이션에 헌 병들을 가져갔다.","sense":"리필 스테이션"},{"wordId":19484,"answer":"packaging","form":"원형","example":"The online store promised to use less packaging for every order next year.","exampleTranslation":"그 온라인 상점은 내년부터 주문마다 포장재를 줄이겠다고 약속했다.","sense":"포장재"},{"wordId":19485,"answer":"illegal dumping","form":"원형","example":"The neighbors put up a camera to stop illegal dumping behind the store.","exampleTranslation":"이웃들은 가게 뒤 불법 투기를 막으려고 카메라를 달았다.","sense":"불법 투기"},{"wordId":19486,"answer":"polluted","form":"과거형","example":"Last year an oil spill polluted the beach near our town.","exampleTranslation":"작년에 기름 유출이 우리 마을 근처 해변을 오염시켰다.","sense":"오염시키다"},{"wordId":19487,"answer":"most toxic","form":"최상급","example":"The guide said this was the most toxic mushroom in the whole forest.","exampleTranslation":"가이드는 이것이 숲 전체에서 가장 독성이 강한 버섯이라고 했다.","sense":"유독한"},{"wordId":19488,"answer":"endangered species","form":"원형","example":"Our class adopted an endangered species and sent money to protect it.","exampleTranslation":"우리 반은 멸종 위기종 하나를 후원하고 보호 기금을 보냈다.","sense":"멸종 위기종"},{"wordId":19489,"answer":"deforestation","form":"원형","example":"The documentary showed how deforestation changes the weather in the region.","exampleTranslation":"그 다큐멘터리는 숲 파괴가 그 지역 날씨를 어떻게 바꾸는지 보여 줬다.","sense":"삼림 벌채"},{"wordId":19490,"answer":"marine life","form":"원형","example":"We took a boat tour to see the colorful marine life around the island.","exampleTranslation":"섬 주변의 화려한 해양 생물을 보려고 보트 투어를 했다.","sense":"해양 생물"},{"wordId":19491,"answer":"greenhouse gases","form":"원형","example":"Cows produce greenhouse gases, so some farms are changing what they eat.","exampleTranslation":"소가 온실가스를 내뿜어서 일부 농장은 사료를 바꾸고 있다.","sense":"온실가스"},{"wordId":19492,"answer":"emissions","form":"원형","example":"The airline promised to lower its emissions by using newer planes.","exampleTranslation":"그 항공사는 새 비행기를 써서 배출량을 줄이겠다고 약속했다.","sense":"배출량"},{"wordId":19493,"answer":"electric car","form":"원형","example":"My uncle let me drive his new electric car around the parking lot.","exampleTranslation":"삼촌이 새 전기차를 주차장에서 몰아 보게 해 줬다.","sense":"전기차"},{"wordId":19494,"answer":"environmentally conscious","form":"원형","example":"Our new manager is very environmentally conscious and recycles everything.","exampleTranslation":"새 매니저는 환경 의식이 높아서 모든 것을 재활용한다.","sense":"환경 의식이 있는"},{"wordId":19495,"answer":"do your part","form":"원형","example":"If you want a clean beach, do your part and take your trash home.","exampleTranslation":"깨끗한 해변을 원하면 각자 할 일을 해서 쓰레기를 집에 가져가.","sense":"자기 몫을 하다"},{"wordId":19496,"answer":"more sustainable","form":"비교급","example":"Buying fewer, better clothes is more sustainable than fast fashion.","exampleTranslation":"옷을 적게 사되 좋은 것을 사는 게 패스트 패션보다 더 지속 가능하다.","sense":"지속 가능한"},{"wordId":19497,"answer":"most wasteful","form":"최상급","example":"Leaving the water running is the most wasteful habit in our house.","exampleTranslation":"물을 틀어 놓는 것이 우리 집에서 가장 낭비가 심한 습관이다.","sense":"낭비하는"},{"wordId":19498,"answer":"reduce, reuse, recycle","form":"원형","example":"The poster in the cafeteria says reduce, reuse, recycle in big green letters.","exampleTranslation":"식당 포스터에는 큰 초록 글씨로 줄이고 다시 쓰고 재활용하자고 쓰여 있다.","sense":"환경 실천 구호"},{"wordId":19499,"answer":"water shortage","form":"원형","example":"During the water shortage, we could only water the garden on Mondays.","exampleTranslation":"물 부족 기간에는 월요일에만 정원에 물을 줄 수 있었다.","sense":"물 부족"},{"wordId":19500,"answer":"microplastics","form":"원형","example":"Washing synthetic clothes can release microplastics into the water.","exampleTranslation":"합성 섬유 옷을 빨면 미세플라스틱이 물로 흘러갈 수 있다.","sense":"미세플라스틱"},{"wordId":19501,"answer":"meet a deadline","form":"원형","example":"I stayed late at the library to meet a deadline for my history paper.","exampleTranslation":"역사 과제 마감을 지키려고 도서관에 늦게까지 남았다.","sense":"마감을 지키다"},{"wordId":19502,"answer":"raise a question","form":"원형","example":"I do not want to raise a question that makes the speaker feel uncomfortable.","exampleTranslation":"발표자를 불편하게 할 질문은 던지고 싶지 않다.","sense":"질문을 던지다"},{"wordId":19503,"answer":"raise your voice","form":"원형","example":"You do not need to raise your voice because I can hear you just fine.","exampleTranslation":"내가 잘 들리니까 언성을 높일 필요 없어.","sense":"언성을 높이다"},{"wordId":19504,"answer":"set the table","form":"원형","example":"It is my son's job to set the table before dinner every night.","exampleTranslation":"매일 저녁 식사 전에 상을 차리는 건 아들 몫이다.","sense":"상을 차리다"},{"wordId":19505,"answer":"set an alarm","form":"원형","example":"Do not forget to set an alarm for your flight on Sunday.","exampleTranslation":"일요일 비행기 시간에 맞춰 알람 맞추는 거 잊지 마.","sense":"알람을 맞추다"},{"wordId":19506,"answer":"reach a compromise","form":"원형","example":"The two teams argued for an hour but could not reach a compromise on the schedule.","exampleTranslation":"두 팀은 한 시간 동안 논쟁했지만 일정에 대해 타협점을 찾지 못했다.","sense":"타협점을 찾다"},{"wordId":19507,"answer":"lose weight","form":"원형","example":"My doctor says walking every evening is the easiest way to lose weight.","exampleTranslation":"의사는 매일 저녁 걷는 것이 살을 빼는 가장 쉬운 방법이라고 한다.","sense":"살을 빼다"},{"wordId":19508,"answer":"gain weight","form":"원형","example":"Athletes who want to build muscle sometimes need to gain weight first.","exampleTranslation":"근육을 키우려는 운동선수들은 때로 먼저 살을 찌워야 한다.","sense":"살이 찌다"},{"wordId":19509,"answer":"lose your balance","form":"원형","example":"When you skate for the first time, it is very easy to lose your balance.","exampleTranslation":"처음 스케이트를 타면 균형을 잃기 아주 쉽다.","sense":"균형을 잃다"},{"wordId":19510,"answer":"win a prize","form":"원형","example":"Everyone who finishes the city fun run has a chance to win a prize.","exampleTranslation":"시내 마라톤 대회를 완주하는 사람은 누구나 경품에 당첨될 기회가 있다.","sense":"상을 타다"},{"wordId":19511,"answer":"pay your respects","form":"원형","example":"You can sign the guest book by the door to pay your respects to the family.","exampleTranslation":"문 옆 방명록에 서명해서 유가족께 조의를 표할 수 있어요.","sense":"조의를 표하다"},{"wordId":19512,"answer":"pay the bill","form":"원형","example":"My grandfather always insists on being the one to pay the bill at restaurants.","exampleTranslation":"할아버지는 식당에서 늘 당신이 계산하겠다고 고집하신다.","sense":"계산하다"},{"wordId":19513,"answer":"catch a train","form":"원형","example":"We woke up early to catch a train to the mountains for our hiking trip.","exampleTranslation":"우리는 등산 여행으로 산에 가는 기차를 타려고 일찍 일어났다.","sense":"기차를 타다"},{"wordId":19514,"answer":"break a habit","form":"원형","example":"It can take months to break a habit like biting your nails.","exampleTranslation":"손톱을 물어뜯는 것 같은 버릇을 끊으려면 몇 달이 걸릴 수 있다.","sense":"버릇을 끊다"},{"wordId":19515,"answer":"break the silence","form":"원형","example":"At dinner, my uncle told a joke to break the silence after the argument.","exampleTranslation":"저녁 식사 때 말다툼 후에 삼촌이 농담을 해서 침묵을 깼다.","sense":"침묵을 깨다"},{"wordId":19516,"answer":"tell a story","form":"원형","example":"Every night before bed, my daughter asks me to tell a story about dragons.","exampleTranslation":"매일 밤 자기 전에 딸은 용에 관한 이야기를 들려 달라고 한다.","sense":"이야기를 들려주다"},{"wordId":19517,"answer":"run a fever","form":"원형","example":"If you run a fever over the weekend, please call the clinic on Monday.","exampleTranslation":"주말 동안 열이 나면 월요일에 병원에 전화하세요.","sense":"열이 나다"},{"wordId":19518,"answer":"miss a call","form":"원형","example":"At work I keep my phone loud so I do not miss a call from school.","exampleTranslation":"학교에서 오는 전화를 놓치지 않으려고 회사에서 휴대폰 소리를 켜 둔다.","sense":"전화를 못 받다"},{"wordId":19519,"answer":"save a seat","form":"원형","example":"Please save a seat near the front for my mom at the school concert.","exampleTranslation":"학교 음악회에서 앞쪽에 우리 엄마 자리 좀 맡아 줘.","sense":"자리를 맡아 두다"},{"wordId":19520,"answer":"spend time","form":"원형","example":"My grandparents love to spend time in their garden every afternoon.","exampleTranslation":"조부모님은 매일 오후 정원에서 시간을 보내는 것을 좋아하신다.","sense":"시간을 보내다"},{"wordId":19521,"answer":"give a presentation","form":"원형","example":"Each student has to give a presentation about a country they want to visit.","exampleTranslation":"학생마다 가 보고 싶은 나라에 관해 발표해야 한다.","sense":"발표하다"},{"wordId":19522,"answer":"hold a meeting","form":"원형","example":"The neighbors plan to hold a meeting about parking problems on our street.","exampleTranslation":"이웃들이 우리 거리 주차 문제로 회의를 열 계획이다.","sense":"회의를 열다"},{"wordId":19523,"answer":"hold a grudge","form":"원형","example":"My sister does not hold a grudge, even when her friends forget her birthday.","exampleTranslation":"언니는 친구들이 생일을 잊어도 앙심을 품지 않는다.","sense":"앙심을 품다"},{"wordId":19524,"answer":"follow a recipe","form":"원형","example":"When you bake bread for the first time, it is smart to follow a recipe.","exampleTranslation":"처음 빵을 구울 때는 레시피대로 하는 게 현명하다.","sense":"레시피대로 하다"},{"wordId":19525,"answer":"follow the rules","form":"원형","example":"Visitors at the swimming pool must follow the rules posted by the door.","exampleTranslation":"수영장 방문객은 문 옆에 붙은 규칙을 따라야 한다.","sense":"규칙을 따르다"},{"wordId":19526,"answer":"play a trick","form":"원형","example":"The students wanted to play a trick on their teacher on the last day.","exampleTranslation":"학생들은 마지막 날 선생님께 장난을 치고 싶어 했다.","sense":"장난치다"},{"wordId":19527,"answer":"draw a line","form":"원형","example":"It is important to draw a line between work time and family time.","exampleTranslation":"일하는 시간과 가족과의 시간 사이에 선을 긋는 것이 중요하다.","sense":"선을 긋다"},{"wordId":19528,"answer":"change the subject","form":"원형","example":"When the kids started fighting over the remote, I tried to change the subject.","exampleTranslation":"아이들이 리모컨을 두고 다투기 시작하자 나는 화제를 바꾸려 했다.","sense":"화제를 바꾸다"},{"wordId":19529,"answer":"earn respect","form":"원형","example":"A new coach has to earn respect from the players before they listen.","exampleTranslation":"새 코치는 선수들이 말을 듣기 전에 먼저 인정을 얻어야 한다.","sense":"인정을 얻다"},{"wordId":19530,"answer":"lose sleep","form":"원형","example":"My mom tends to lose sleep when my brother drives home late at night.","exampleTranslation":"엄마는 오빠가 밤늦게 운전해서 집에 오면 잠을 설치곤 한다.","sense":"잠을 설치다"},{"wordId":19531,"answer":"lose count","form":"원형","example":"There are so many stars in the desert sky that it is easy to lose count.","exampleTranslation":"사막 하늘에는 별이 너무 많아서 세다가 잊어버리기 쉽다.","sense":"세다가 잊다"},{"wordId":19532,"answer":"gain confidence","form":"원형","example":"Joining the drama club helped my shy son gain confidence on stage.","exampleTranslation":"연극부에 들어간 덕분에 수줍은 아들이 무대에서 자신감을 얻었다.","sense":"자신감을 얻다"},{"wordId":19533,"answer":"build trust","form":"원형","example":"Small business owners build trust with customers by being honest about prices.","exampleTranslation":"작은 가게 주인들은 가격에 정직해서 손님과 신뢰를 쌓는다.","sense":"신뢰를 쌓다"},{"wordId":19534,"answer":"raise awareness","form":"원형","example":"The students made posters to raise awareness about saving energy at school.","exampleTranslation":"학생들은 학교에서 에너지 절약에 대한 인식을 높이려고 포스터를 만들었다.","sense":"인식을 높이다"},{"wordId":19535,"answer":"raise prices","form":"원형","example":"The movie theater plans to raise prices for popcorn and drinks next month.","exampleTranslation":"영화관이 다음 달 팝콘과 음료 가격을 올릴 계획이다.","sense":"가격을 올리다"},{"wordId":19536,"answer":"set a record","form":"원형","example":"The local bakery tried to set a record by making the longest sandwich.","exampleTranslation":"동네 빵집은 가장 긴 샌드위치를 만들어 기록을 세우려 했다.","sense":"기록을 세우다"},{"wordId":19537,"answer":"tell the time","form":"원형","example":"Many children today cannot tell the time on a clock with hands.","exampleTranslation":"요즘 많은 아이는 바늘 시계를 보고 시간을 알지 못한다.","sense":"시간을 알다"},{"wordId":19538,"answer":"accept an apology","form":"원형","example":"It takes a big heart to accept an apology from someone who hurt you.","exampleTranslation":"상처를 준 사람의 사과를 받아들이려면 넓은 마음이 필요하다.","sense":"사과를 받아들이다"},{"wordId":19539,"answer":"ask a favor","form":"원형","example":"I hate to ask a favor, but could you feed my cat this weekend?","exampleTranslation":"부탁하기 싫지만 이번 주말에 우리 고양이 밥 좀 줄 수 있어?","sense":"부탁하다"},{"wordId":19540,"answer":"cause trouble","form":"원형","example":"Those two boys always cause trouble when they sit together in class.","exampleTranslation":"그 두 남자아이는 수업 시간에 같이 앉으면 늘 말썽을 일으킨다.","sense":"말썽을 일으키다"},{"wordId":19541,"answer":"strike a balance","form":"원형","example":"Good cooks know how to strike a balance between sweet and salty flavors.","exampleTranslation":"훌륭한 요리사는 단맛과 짠맛의 균형을 맞추는 법을 안다.","sense":"균형을 맞추다"},{"wordId":19542,"answer":"strike a deal","form":"원형","example":"My dad spent an hour at the car lot trying to strike a deal.","exampleTranslation":"아빠는 중고차 매장에서 거래를 성사시키려고 한 시간을 보냈다.","sense":"합의를 보다"},{"wordId":19543,"answer":"face the facts","form":"원형","example":"Our old car breaks down every month, so we have to face the facts.","exampleTranslation":"우리 낡은 차가 매달 고장 나니 현실을 직시해야 한다.","sense":"현실을 직시하다"},{"wordId":19544,"answer":"break the law","form":"원형","example":"In some countries, you break the law if you chew gum on the subway.","exampleTranslation":"일부 나라에서는 지하철에서 껌을 씹으면 법을 어기는 것이다.","sense":"법을 어기다"},{"wordId":19545,"answer":"pass a test","form":"원형","example":"All new employees must pass a test on safety rules in their first week.","exampleTranslation":"모든 신입 직원은 첫 주에 안전 규칙 시험에 통과해야 한다.","sense":"시험에 합격하다"},{"wordId":19546,"answer":"seize the opportunity","form":"원형","example":"The band got a chance to play on TV and wanted to seize the opportunity.","exampleTranslation":"그 밴드는 방송에서 연주할 기회를 얻었고 그 기회를 잡고 싶었다.","sense":"기회를 잡다"},{"wordId":19547,"answer":"show interest","form":"원형","example":"If you show interest in your coworkers' hobbies, they will open up more.","exampleTranslation":"동료들의 취미에 관심을 보이면 그들이 더 마음을 열 것이다.","sense":"관심을 보이다"},{"wordId":19548,"answer":"voice concerns","form":"원형","example":"The meeting gives employees a safe place to voice concerns about their workload.","exampleTranslation":"그 회의는 직원들이 업무량에 대한 우려를 편하게 표할 수 있는 자리다.","sense":"우려를 표하다"},{"wordId":19549,"answer":"find a solution","form":"원형","example":"The engineers worked through the night to find a solution to the power problem.","exampleTranslation":"기술자들은 전력 문제의 해결책을 찾으려고 밤새 일했다.","sense":"해결책을 찾다"},{"wordId":19550,"answer":"find time","form":"원형","example":"Even with three kids, my sister tries to find time for reading every night.","exampleTranslation":"아이가 셋인데도 언니는 매일 밤 독서할 시간을 내려고 한다.","sense":"시간을 내다"},{"wordId":19551,"answer":"heavy smoker","form":"원형","example":"My grandfather was a heavy smoker for years, but now he enjoys hiking.","exampleTranslation":"할아버지는 오랫동안 골초였지만 지금은 등산을 즐기신다.","sense":"골초"},{"wordId":19552,"answer":"heavy workload","form":"원형","example":"Teachers often have a heavy workload at the end of each semester.","exampleTranslation":"선생님들은 학기 말마다 업무량이 과중한 경우가 많다.","sense":"과중한 업무량"},{"wordId":19553,"answer":"strong wind","form":"원형","example":"A strong wind knocked over our neighbor's fence last night.","exampleTranslation":"어젯밤 강풍에 이웃집 울타리가 쓰러졌다.","sense":"강풍"},{"wordId":19554,"answer":"strong smell","form":"원형","example":"The new paint in the hallway left a strong smell for two days.","exampleTranslation":"복도에 새로 칠한 페인트 때문에 이틀 동안 냄새가 진하게 났다.","sense":"강한 냄새"},{"wordId":19555,"answer":"weak signal","form":"원형","example":"The video call kept freezing because of the weak signal at the cabin.","exampleTranslation":"오두막의 신호가 약해서 영상 통화가 계속 멈췄다.","sense":"약한 신호"},{"wordId":19556,"answer":"high fever","form":"원형","example":"My son stayed home from school yesterday with a high fever and a cough.","exampleTranslation":"아들은 어제 고열과 기침 때문에 학교에 가지 않았다.","sense":"고열"},{"wordId":19557,"answer":"low profile","form":"원형","example":"The famous actor kept a low profile and wore a cap at the airport.","exampleTranslation":"그 유명 배우는 공항에서 모자를 쓰고 눈에 띄지 않게 행동했다.","sense":"눈에 띄지 않는 처신"},{"wordId":19558,"answer":"heavy heart","form":"원형","example":"We sold our family house with a heavy heart after twenty years there.","exampleTranslation":"이십 년을 산 우리 집을 무거운 마음으로 팔았다.","sense":"무거운 마음"},{"wordId":19559,"answer":"hard time","form":"원형","example":"My grandmother had a hard time using the new phone at first.","exampleTranslation":"할머니는 처음에 새 휴대폰을 쓰는 데 애를 먹으셨다.","sense":"힘든 시간"},{"wordId":19560,"answer":"long day","form":"원형","example":"After a long day at the theme park, the kids fell asleep in the car.","exampleTranslation":"놀이공원에서 긴 하루를 보낸 뒤 아이들은 차에서 잠들었다.","sense":"길고 힘든 하루"},{"wordId":19561,"answer":"early night","form":"원형","example":"We have a big hike tomorrow morning, so everyone needs an early night.","exampleTranslation":"내일 아침 긴 등산이 있으니 모두 일찍 자야 해.","sense":"일찍 잠자리에 듦"},{"wordId":19562,"answer":"quick shower","form":"원형","example":"After soccer practice, my son takes a quick shower and eats dinner.","exampleTranslation":"축구 연습이 끝나면 아들은 간단히 샤워하고 저녁을 먹는다.","sense":"간단한 샤워"},{"wordId":19563,"answer":"quick bite","form":"원형","example":"We stopped at a gas station for a quick bite on the drive home.","exampleTranslation":"우리는 집으로 운전해 오는 길에 주유소에 들러 간단히 요기했다.","sense":"간단한 식사"},{"wordId":19564,"answer":"old friend","form":"원형","example":"My mom was so happy when an old friend called her on her birthday.","exampleTranslation":"생일에 오랜 친구가 전화해서 엄마는 무척 기뻐하셨다.","sense":"오랜 친구"},{"wordId":19565,"answer":"sharp turn","form":"원형","example":"The bus driver slowed down before the sharp turn at the top of the hill.","exampleTranslation":"버스 기사는 언덕 꼭대기의 급커브 앞에서 속도를 줄였다.","sense":"급커브"},{"wordId":19566,"answer":"bumpy ride","form":"원형","example":"Starting a small business was a bumpy ride, but we learned a lot.","exampleTranslation":"작은 사업을 시작하는 건 순탄치 않았지만 많이 배웠다.","sense":"순탄치 않은 과정"},{"wordId":19567,"answer":"warm welcome","form":"원형","example":"The new teacher got a warm welcome from her students on the first day.","exampleTranslation":"새 선생님은 첫날 학생들에게서 따뜻한 환영을 받았다.","sense":"따뜻한 환영"},{"wordId":19568,"answer":"big deal","form":"원형","example":"Turning thirty felt like a big deal to my sister, so we threw a party.","exampleTranslation":"언니에게는 서른이 되는 게 큰일 같아서 우리는 파티를 열어 줬다.","sense":"큰일"},{"wordId":19569,"answer":"huge fan","form":"원형","example":"My father is a huge fan of old cowboy movies from the fifties.","exampleTranslation":"아빠는 오십 년대 옛날 카우보이 영화의 열성 팬이다.","sense":"열성 팬"},{"wordId":19570,"answer":"great deal","form":"원형","example":"We found a great deal on plane tickets to Hawaii last night.","exampleTranslation":"어젯밤 하와이행 비행기 표를 아주 싸게 찾았다.","sense":"좋은 거래"},{"wordId":19571,"answer":"good company","form":"원형","example":"My little nephew is good company on long walks because he talks nonstop.","exampleTranslation":"어린 조카는 쉬지 않고 이야기해서 긴 산책길에 함께하면 즐겁다.","sense":"즐거운 동행"},{"wordId":19572,"answer":"bad mood","form":"원형","example":"My teenage brother is always in a bad mood before breakfast.","exampleTranslation":"십 대인 남동생은 아침 먹기 전에는 늘 기분이 안 좋다.","sense":"나쁜 기분"},{"wordId":19573,"answer":"full attention","form":"원형","example":"Driving in heavy snow needs your full attention, so put the phone down.","exampleTranslation":"폭설 속 운전은 온전히 집중해야 하니 휴대폰을 내려놔.","sense":"온전한 집중"},{"wordId":19574,"answer":"common mistake","form":"원형","example":"Forgetting to save your work is a common mistake when using new software.","exampleTranslation":"작업을 저장하는 걸 잊는 것은 새 프로그램을 쓸 때 흔한 실수다.","sense":"흔한 실수"},{"wordId":19575,"answer":"common ground","form":"원형","example":"My new roommate and I found common ground in our love of cooking.","exampleTranslation":"새 룸메이트와 나는 요리를 좋아한다는 공통점을 찾았다.","sense":"공통점"},{"wordId":19576,"answer":"vast majority","form":"원형","example":"The vast majority of students in my class want to study abroad.","exampleTranslation":"우리 반 학생 대다수가 유학을 가고 싶어 한다.","sense":"대다수"},{"wordId":19577,"answer":"wild guess","form":"원형","example":"I did not know the answer on the quiz, so I made a wild guess.","exampleTranslation":"퀴즈 답을 몰라서 어림짐작으로 찍었다.","sense":"어림짐작"},{"wordId":19578,"answer":"educated guess","form":"원형","example":"Based on the traffic, my educated guess is that we will arrive by noon.","exampleTranslation":"교통 상황을 보면 정오쯤 도착할 거라는 게 내 근거 있는 추측이다.","sense":"근거 있는 추측"},{"wordId":19579,"answer":"rough estimate","form":"원형","example":"The painter gave us a rough estimate of three days for the whole house.","exampleTranslation":"페인트공은 집 전체에 대략 사흘이 걸린다고 어림해 줬다.","sense":"대략적인 추정치"},{"wordId":19580,"answer":"fair share","form":"원형","example":"My roommate never pays her fair share of the grocery bill.","exampleTranslation":"룸메이트는 식료품비에서 자기 몫을 제대로 낸 적이 없다.","sense":"정당한 몫"},{"wordId":19581,"answer":"fair price","form":"원형","example":"The farmer at the market always sells his eggs at a fair price.","exampleTranslation":"시장의 그 농부는 늘 달걀을 적정 가격에 판다.","sense":"적정 가격"},{"wordId":19582,"answer":"sharp mind","form":"원형","example":"Playing chess every day helps my grandfather keep a sharp mind.","exampleTranslation":"매일 체스를 두는 게 할아버지가 명석함을 유지하는 데 도움이 된다.","sense":"예리한 두뇌"},{"wordId":19583,"answer":"short temper","form":"원형","example":"Our coach has a short temper when players show up late to practice.","exampleTranslation":"우리 코치는 선수들이 연습에 늦으면 쉽게 화를 낸다.","sense":"급한 성미"},{"wordId":19584,"answer":"dry humor","form":"원형","example":"My science teacher is famous for his dry humor, and the class loves it.","exampleTranslation":"과학 선생님은 무표정한 농담으로 유명한데 반 아이들이 그걸 아주 좋아한다.","sense":"건조한 유머"},{"wordId":19585,"answer":"deep voice","form":"원형","example":"The radio host has a deep voice that sounds great late at night.","exampleTranslation":"그 라디오 진행자는 밤늦게 들으면 멋지게 들리는 굵은 목소리를 가졌다.","sense":"굵은 목소리"},{"wordId":19586,"answer":"loud noise","form":"원형","example":"The dog hides under the bed whenever there is a loud noise outside.","exampleTranslation":"개는 밖에서 큰 소리가 날 때마다 침대 밑에 숨는다.","sense":"큰 소리"},{"wordId":19587,"answer":"dark circles","form":"원형","example":"My sister uses cold spoons in the morning to hide her dark circles.","exampleTranslation":"언니는 아침마다 차가운 숟가락으로 눈 밑 다크서클을 가린다.","sense":"다크서클"},{"wordId":19588,"answer":"stark contrast","form":"원형","example":"My brother's messy room is in stark contrast to my clean one.","exampleTranslation":"오빠의 지저분한 방은 내 깨끗한 방과 극명한 대조를 이룬다.","sense":"극명한 대조"},{"wordId":19589,"answer":"minor injury","form":"원형","example":"The soccer player had a minor injury but returned for the second half.","exampleTranslation":"그 축구 선수는 가벼운 부상을 입었지만 후반전에 다시 뛰었다.","sense":"가벼운 부상"},{"wordId":19590,"answer":"slight delay","form":"원형","example":"The concert started with a slight delay because of a sound problem.","exampleTranslation":"음향 문제로 공연이 약간 늦게 시작됐다.","sense":"약간의 지연"},{"wordId":19591,"answer":"mixed feelings","form":"원형","example":"My mom had mixed feelings when my sister moved to her own apartment.","exampleTranslation":"언니가 자기 아파트로 이사 갈 때 엄마는 마음이 복잡했다.","sense":"복잡한 심경"},{"wordId":19592,"answer":"hard feelings","form":"원형","example":"He beat me badly at tennis, but I have no hard feelings about it.","exampleTranslation":"그가 테니스에서 나를 크게 이겼지만 서운한 마음은 없다.","sense":"서운한 마음"},{"wordId":19593,"answer":"second chance","form":"원형","example":"The restaurant got a second chance after the new chef improved the menu.","exampleTranslation":"새 요리사가 메뉴를 개선한 뒤 그 식당은 다시 기회를 얻었다.","sense":"두 번째 기회"},{"wordId":19594,"answer":"last resort","form":"원형","example":"Sleeping at the airport was our last resort after all the hotels were full.","exampleTranslation":"호텔이 모두 꽉 차서 공항에서 자는 것이 최후의 수단이었다.","sense":"최후의 수단"},{"wordId":19596,"answer":"heated argument","form":"원형","example":"My parents had a heated argument about where to go on vacation.","exampleTranslation":"부모님은 휴가지를 두고 열띤 말다툼을 했다.","sense":"격한 논쟁"},{"wordId":19597,"answer":"big picture","form":"원형","example":"Before you pick a college, think about the big picture of your career.","exampleTranslation":"대학을 고르기 전에 진로의 큰 그림을 생각해 봐.","sense":"큰 그림"},{"wordId":19598,"answer":"white lie","form":"원형","example":"My son told a white lie and said he liked the itchy sweater.","exampleTranslation":"아들은 선의의 거짓말로 그 따가운 스웨터가 좋다고 했다.","sense":"선의의 거짓말"},{"wordId":19599,"answer":"high standards","form":"원형","example":"The chef has high standards, so every plate must look perfect.","exampleTranslation":"그 요리사는 기준이 높아서 모든 접시가 완벽해 보여야 한다.","sense":"높은 기준"},{"wordId":19600,"answer":"sharp drop","form":"원형","example":"The store saw a sharp drop in sales after the new mall opened.","exampleTranslation":"새 쇼핑몰이 생긴 뒤 그 가게 매출이 급격히 떨어졌다.","sense":"급격한 하락"},{"wordId":19601,"answer":"absolutely delicious","form":"원형","example":"The chocolate cake at my cousin's wedding was absolutely delicious.","exampleTranslation":"사촌 결혼식에서 먹은 초콜릿 케이크는 정말 맛있었다.","sense":"정말 맛있는"},{"wordId":19602,"answer":"perfectly normal","form":"원형","example":"The doctor said it is perfectly normal for babies to sleep this much.","exampleTranslation":"의사는 아기가 이만큼 자는 건 지극히 정상이라고 했다.","sense":"지극히 정상적인"},{"wordId":19603,"answer":"deeply concerned","form":"원형","example":"The teachers are deeply concerned about students using phones in class.","exampleTranslation":"선생님들은 학생들이 수업 중에 휴대폰을 쓰는 것을 깊이 우려한다.","sense":"깊이 우려하는"},{"wordId":19604,"answer":"strongly advise","form":"원형","example":"We strongly advise all hikers to carry extra water on this trail.","exampleTranslation":"이 등산로의 모든 등산객에게 물을 여분으로 챙기라고 강력히 권한다.","sense":"강력히 권하다"},{"wordId":19605,"answer":"badly needed","form":"원형","example":"The rain this week was badly needed after a very dry summer.","exampleTranslation":"아주 건조한 여름 뒤라 이번 주 비는 몹시 필요했다.","sense":"몹시 필요한"},{"wordId":19606,"answer":"barely noticeable","form":"원형","example":"The scratch on the car door is barely noticeable unless you look closely.","exampleTranslation":"차 문에 난 긁힌 자국은 자세히 보지 않으면 거의 눈에 띄지 않는다.","sense":"거의 눈에 안 띄는"},{"wordId":19607,"answer":"incredibly lucky","form":"원형","example":"My cousin was incredibly lucky and found his lost wallet in the taxi.","exampleTranslation":"사촌은 엄청나게 운이 좋아서 택시에서 잃어버린 지갑을 찾았다.","sense":"엄청나게 운이 좋은"},{"wordId":19608,"answer":"ridiculously expensive","form":"원형","example":"The snacks at the movie theater are ridiculously expensive, so we bring our own.","exampleTranslation":"영화관 간식은 터무니없이 비싸서 우리는 직접 챙겨 간다.","sense":"터무니없이 비싼"},{"wordId":19609,"answer":"reasonably priced","form":"원형","example":"This used bike is in great shape and reasonably priced for students.","exampleTranslation":"이 중고 자전거는 상태가 아주 좋고 학생에게 가격이 적당하다.","sense":"가격이 적당한"},{"wordId":19610,"answer":"conveniently located","form":"원형","example":"The new gym is conveniently located right next to my office building.","exampleTranslation":"새 헬스장은 우리 회사 건물 바로 옆이라 편리한 곳에 있다.","sense":"편리한 곳에 위치한"},{"wordId":19611,"answer":"perfectly safe","form":"원형","example":"The guide told us the old bridge is perfectly safe for walking.","exampleTranslation":"가이드는 그 오래된 다리가 걸어서 건너기에 완전히 안전하다고 했다.","sense":"완전히 안전한"},{"wordId":19612,"answer":"completely unexpected","form":"원형","example":"The snow in April was completely unexpected, and nobody had a warm coat.","exampleTranslation":"사월에 내린 눈은 전혀 예상치 못한 일이라 아무도 따뜻한 외투가 없었다.","sense":"전혀 예상치 못한"},{"wordId":19613,"answer":"painfully shy","form":"원형","example":"My new classmate is painfully shy and only talks when the teacher asks.","exampleTranslation":"새 반 친구는 몹시 수줍음을 타서 선생님이 물을 때만 말한다.","sense":"몹시 수줍은"},{"wordId":19614,"answer":"hopelessly lost","form":"원형","example":"My phone died during the hike, and we were hopelessly lost in the woods.","exampleTranslation":"등산 중에 휴대폰이 꺼져서 우리는 숲에서 완전히 길을 잃었다.","sense":"완전히 길을 잃은"},{"wordId":19615,"answer":"slightly annoyed","form":"원형","example":"The waiter looked slightly annoyed when we changed our order three times.","exampleTranslation":"우리가 주문을 세 번 바꾸자 종업원은 약간 짜증 난 표정이었다.","sense":"약간 짜증 난"},{"wordId":19616,"answer":"genuinely interested","form":"원형","example":"My grandfather is genuinely interested in learning how to use video calls.","exampleTranslation":"할아버지는 영상 통화 쓰는 법을 배우는 데 진심으로 관심이 있으시다.","sense":"진심으로 관심 있는"},{"wordId":19617,"answer":"quickly realized","form":"원형","example":"On my first day at work, I quickly realized everyone ate lunch at their desks.","exampleTranslation":"출근 첫날 모두가 자기 책상에서 점심을 먹는다는 걸 금세 깨달았다.","sense":"금세 깨달았다"},{"wordId":19618,"answer":"perfectly capable","form":"원형","example":"My twelve-year-old son is perfectly capable of making his own breakfast.","exampleTranslation":"열두 살 아들은 아침을 충분히 혼자 차려 먹을 수 있다.","sense":"충분히 할 수 있는"},{"wordId":19619,"answer":"absolutely ridiculous","form":"원형","example":"The idea of charging money for tap water is absolutely ridiculous.","exampleTranslation":"수돗물에 돈을 받는다는 생각은 정말 말도 안 된다.","sense":"정말 말도 안 되는"},{"wordId":19620,"answer":"entirely possible","form":"원형","example":"With this traffic, it is entirely possible that we will miss the first song.","exampleTranslation":"이렇게 막히면 첫 곡을 놓칠 수도 충분히 있다.","sense":"충분히 가능한"},{"wordId":19621,"answer":"unbelievably hot","form":"원형","example":"The sand on the beach was unbelievably hot, so we ran to the water.","exampleTranslation":"해변 모래가 믿기지 않을 만큼 뜨거워서 우리는 물로 뛰어갔다.","sense":"믿기지 않게 뜨거운"},{"wordId":19622,"answer":"dangerously close","form":"원형","example":"The kids were standing dangerously close to the edge of the pool.","exampleTranslation":"아이들이 수영장 가장자리에 위험할 정도로 가까이 서 있었다.","sense":"위험할 정도로 가까운"},{"wordId":19623,"answer":"wildly popular","form":"원형","example":"The new cartoon is wildly popular with kids at my daughter's school.","exampleTranslation":"새 만화는 딸 학교 아이들에게 엄청나게 인기가 있다.","sense":"엄청나게 인기 있는"},{"wordId":19624,"answer":"fairly easy","form":"원형","example":"Putting together this bookshelf was fairly easy with the clear instructions.","exampleTranslation":"설명서가 명확해서 이 책장을 조립하는 건 꽤 쉬웠다.","sense":"꽤 쉬운"},{"wordId":19625,"answer":"pretty sure","form":"원형","example":"My mom is pretty sure the store closes at nine on Sundays.","exampleTranslation":"엄마는 그 가게가 일요일엔 아홉 시에 닫는다고 꽤 확신하신다.","sense":"꽤 확신하는"},{"wordId":19626,"answer":"relatively cheap","form":"원형","example":"Train tickets in this country are relatively cheap if you book early.","exampleTranslation":"이 나라 기차표는 일찍 예매하면 비교적 싸다.","sense":"비교적 싼"},{"wordId":19627,"answer":"noticeably better","form":"원형","example":"After the new coach arrived, the team played noticeably better on defense.","exampleTranslation":"새 코치가 온 뒤 팀은 수비에서 눈에 띄게 나아졌다.","sense":"눈에 띄게 나은"},{"wordId":19628,"answer":"fully recover","form":"원형","example":"The vet said our dog will fully recover after a few weeks of rest.","exampleTranslation":"수의사는 우리 개가 몇 주 쉬면 완전히 회복할 거라고 했다.","sense":"완전히 회복하다"},{"wordId":19629,"answer":"kindly ask","form":"원형","example":"We kindly ask all guests to keep their voices down after ten at night.","exampleTranslation":"모든 손님께 밤 열 시 이후에는 목소리를 낮춰 주시기를 정중히 부탁드립니다.","sense":"정중히 부탁하다"},{"wordId":19630,"answer":"secretly hope","form":"원형","example":"Many kids secretly hope for a snow day so school will close.","exampleTranslation":"많은 아이가 학교가 쉬도록 눈이 많이 오기를 남몰래 바란다.","sense":"남몰래 바라다"},{"wordId":19631,"answer":"barely made it","form":"원형","example":"The bus was late, but I barely made it to my job interview on time.","exampleTranslation":"버스가 늦었지만 면접에 간신히 제시간에 도착했다.","sense":"간신히 해냈다"},{"wordId":19632,"answer":"nearly impossible","form":"원형","example":"Getting tickets for that concert on a Saturday night is nearly impossible.","exampleTranslation":"토요일 밤 그 공연 표를 구하는 건 거의 불가능하다.","sense":"거의 불가능한"},{"wordId":19633,"answer":"happily accept","form":"원형","example":"If the company offers me more vacation days, I will happily accept the job.","exampleTranslation":"회사가 휴가를 더 준다면 그 일자리를 기꺼이 받아들이겠다.","sense":"기꺼이 받아들이다"},{"wordId":19634,"answer":"openly admit","form":"원형","example":"My father will openly admit that he cannot cook anything but eggs.","exampleTranslation":"아빠는 달걀 요리밖에 못 한다는 걸 솔직히 인정하신다.","sense":"솔직히 인정하다"},{"wordId":19635,"answer":"clearly state","form":"원형","example":"The sign should clearly state that dogs are not allowed on the beach.","exampleTranslation":"표지판에 해변에 개 출입이 안 된다고 분명히 밝혀야 한다.","sense":"분명히 밝히다"},{"wordId":19636,"answer":"quietly leave","form":"원형","example":"During the long speech, a few guests started to quietly leave the hall.","exampleTranslation":"긴 연설 도중 몇몇 손님이 조용히 강당을 빠져나가기 시작했다.","sense":"조용히 자리를 뜨다"},{"wordId":19637,"answer":"immediately regret","form":"원형","example":"Whenever I buy clothes on impulse, I immediately regret it.","exampleTranslation":"충동적으로 옷을 살 때마다 나는 곧바로 후회한다.","sense":"곧바로 후회하다"},{"wordId":19638,"answer":"accidentally delete","form":"원형","example":"Make a backup copy so you do not accidentally delete your school project.","exampleTranslation":"학교 과제를 실수로 지우지 않도록 백업을 만들어 둬.","sense":"실수로 지우다"},{"wordId":19639,"answer":"completely ruined","form":"원형","example":"The dog jumped on the table, and our birthday cake was completely ruined.","exampleTranslation":"개가 식탁에 뛰어올라 생일 케이크가 완전히 망가졌다.","sense":"완전히 망친"},{"wordId":19640,"answer":"thoroughly enjoy","form":"원형","example":"My parents thoroughly enjoy their morning walks along the river.","exampleTranslation":"부모님은 강가를 따라 걷는 아침 산책을 한껏 즐기신다.","sense":"한껏 즐기다"},{"wordId":19641,"answer":"sincerely hope","form":"원형","example":"We sincerely hope our new neighbors like the cookies we baked for them.","exampleTranslation":"새 이웃이 우리가 구워 준 쿠키를 좋아하길 진심으로 바란다.","sense":"진심으로 바라다"},{"wordId":19642,"answer":"madly in love","form":"원형","example":"My grandparents are still madly in love after fifty years together.","exampleTranslation":"조부모님은 함께한 지 오십 년이 지나도 여전히 깊이 사랑하신다.","sense":"미친 듯이 사랑에 빠진"},{"wordId":19643,"answer":"visibly upset","form":"원형","example":"The little girl was visibly upset when her ice cream fell on the ground.","exampleTranslation":"어린 소녀는 아이스크림이 바닥에 떨어지자 눈에 띄게 속상해했다.","sense":"눈에 띄게 속상한"},{"wordId":19644,"answer":"freshly squeezed","form":"원형","example":"The hotel breakfast came with freshly squeezed apple juice and warm bread.","exampleTranslation":"호텔 조식에는 갓 짠 사과 주스와 따뜻한 빵이 나왔다.","sense":"갓 짠"},{"wordId":19645,"answer":"overly sensitive","form":"원형","example":"My little brother gets overly sensitive when we tease him about his hair.","exampleTranslation":"남동생은 우리가 머리 모양을 놀리면 지나치게 예민해진다.","sense":"지나치게 예민한"},{"wordId":19646,"answer":"surprisingly good","form":"원형","example":"The cheap hotel near the station was surprisingly good and very quiet.","exampleTranslation":"역 근처의 싼 호텔은 의외로 좋았고 아주 조용했다.","sense":"의외로 좋은"},{"wordId":19647,"answer":"instantly recognize","form":"원형","example":"Even after ten years, I instantly recognize my teacher's voice on the phone.","exampleTranslation":"십 년이 지나도 전화로 선생님 목소리를 단번에 알아본다.","sense":"단번에 알아보다"},{"wordId":19648,"answer":"constantly complain","form":"원형","example":"Some customers constantly complain about the music in the store.","exampleTranslation":"몇몇 손님은 가게 음악에 대해 끊임없이 불평한다.","sense":"끊임없이 불평하다"},{"wordId":19649,"answer":"barely touched","form":"원형","example":"My dad was so tired that he barely touched his dinner last night.","exampleTranslation":"아빠는 어젯밤 너무 피곤해서 저녁을 거의 손도 대지 않으셨다.","sense":"거의 손도 안 댄"},{"wordId":19650,"answer":"perfectly timed","form":"원형","example":"The fireworks were perfectly timed with the music at the end of the show.","exampleTranslation":"공연 마지막에 불꽃놀이가 음악과 완벽하게 맞아떨어졌다.","sense":"타이밍이 완벽한"},{"wordId":19651,"answer":"traffic jam","form":"원형","example":"A big traffic jam on the highway made my dad late for work.","exampleTranslation":"고속도로의 큰 교통 체증 때문에 아빠가 회사에 늦었다.","sense":"교통 체증"},{"wordId":19652,"answer":"peak hours","form":"원형","example":"The gym is too crowded during peak hours, so I go at noon.","exampleTranslation":"헬스장은 혼잡 시간대에 너무 붐벼서 나는 정오에 간다.","sense":"혼잡 시간대"},{"wordId":19653,"answer":"prices rise","form":"원형","example":"Many families start cooking at home more when prices rise at restaurants.","exampleTranslation":"식당 가격이 오르면 많은 가족이 집에서 요리를 더 하기 시작한다.","sense":"물가가 오르다"},{"wordId":19654,"answer":"the phone rings","form":"원형","example":"My little sister runs to the hallway whenever the phone rings at home.","exampleTranslation":"집에서 전화가 울릴 때마다 여동생은 복도로 뛰어간다.","sense":"전화가 울리다"},{"wordId":19655,"answer":"time passes","form":"원형","example":"My grandmother says that the house feels quieter as time passes.","exampleTranslation":"할머니는 시간이 흐를수록 집이 더 조용하게 느껴진다고 하신다.","sense":"시간이 흐르다"},{"wordId":19656,"answer":"rumors spread","form":"원형","example":"At school, rumors spread quickly through group chats on students' phones.","exampleTranslation":"학교에서는 학생들 휴대폰 단체 대화방을 통해 소문이 빠르게 퍼진다.","sense":"소문이 퍼지다"},{"wordId":19657,"answer":"the engine starts","form":"원형","example":"On cold winter mornings, my dad waits a while after the engine starts.","exampleTranslation":"추운 겨울 아침이면 아빠는 시동이 걸린 뒤 잠시 기다린다.","sense":"시동이 걸리다"},{"wordId":19658,"answer":"the sun rises","form":"원형","example":"The farmers in this village begin working before the sun rises.","exampleTranslation":"이 마을 농부들은 해가 뜨기 전에 일을 시작한다.","sense":"해가 뜨다"},{"wordId":19659,"answer":"the dog barks","form":"원형","example":"Our neighbors complain because the dog barks every time a car passes.","exampleTranslation":"차가 지나갈 때마다 개가 짖어서 이웃들이 불평한다.","sense":"개가 짖다"},{"wordId":19660,"answer":"the price drops","form":"원형","example":"My brother checks the website every day and buys tickets when the price drops.","exampleTranslation":"오빠는 매일 사이트를 확인하고 가격이 떨어지면 표를 산다.","sense":"가격이 떨어지다"},{"wordId":19661,"answer":"sales increase","form":"원형","example":"Ice cream shops usually see their sales increase in the summer months.","exampleTranslation":"아이스크림 가게는 보통 여름철에 매출이 는다.","sense":"매출이 늘다"},{"wordId":19662,"answer":"the battery dies","form":"원형","example":"I always carry a power bank in case the battery dies during my commute.","exampleTranslation":"출퇴근 중에 배터리가 나갈까 봐 늘 보조 배터리를 들고 다닌다.","sense":"배터리가 나가다"},{"wordId":19663,"answer":"the water boils","form":"원형","example":"My son watches the pot closely and calls me when the water boils.","exampleTranslation":"아들은 냄비를 지켜보다가 물이 끓으면 나를 부른다.","sense":"물이 끓다"},{"wordId":19664,"answer":"the ice melts","form":"원형","example":"We can skate on the lake until the ice melts in March.","exampleTranslation":"삼월에 얼음이 녹을 때까지는 호수에서 스케이트를 탈 수 있다.","sense":"얼음이 녹다"},{"wordId":19665,"answer":"my stomach growls","form":"원형","example":"The library is so quiet that everyone hears it when my stomach growls.","exampleTranslation":"도서관이 너무 조용해서 내 배에서 꼬르륵 소리가 나면 다 들린다.","sense":"배에서 꼬르륵하다"},{"wordId":19666,"answer":"my heart races","form":"원형","example":"Every time I see a big spider in the bathroom, my heart races.","exampleTranslation":"욕실에서 큰 거미를 볼 때마다 심장이 두근거린다.","sense":"심장이 두근거리다"},{"wordId":19667,"answer":"tension builds","form":"원형","example":"In the last minute of the final game, tension builds in the stadium.","exampleTranslation":"결승전 마지막 일 분이 되면 경기장에 긴장이 고조된다.","sense":"긴장이 고조되다"},{"wordId":19668,"answer":"prices soar","form":"원형","example":"Every summer, prices soar at the beach towns along the coast.","exampleTranslation":"매년 여름이면 해안가 해변 마을들의 가격이 치솟는다.","sense":"가격이 치솟다"},{"wordId":19669,"answer":"the crowd cheers","form":"원형","example":"My little brother jumps up and down whenever the crowd cheers at the game.","exampleTranslation":"경기에서 관중이 환호할 때마다 남동생은 펄쩍펄쩍 뛴다.","sense":"관중이 환호하다"},{"wordId":19670,"answer":"phone call","form":"원형","example":"I had a long phone call with my grandmother last night.","exampleTranslation":"어젯밤 할머니와 오래 전화 통화를 했다.","sense":"전화 통화"},{"wordId":19671,"answer":"coffee break","form":"원형","example":"The workers at the factory get a coffee break every two hours.","exampleTranslation":"공장 직원들은 두 시간마다 잠깐 쉬는 시간을 갖는다.","sense":"커피 타임"},{"wordId":19672,"answer":"lunch break","form":"원형","example":"My mom calls me every day during her lunch break at the hospital.","exampleTranslation":"엄마는 병원 점심시간마다 매일 나에게 전화하신다.","sense":"점심시간"},{"wordId":19673,"answer":"job offer","form":"원형","example":"My brother turned down a job offer because it was too far from home.","exampleTranslation":"오빠는 집에서 너무 멀어서 채용 제의를 거절했다.","sense":"채용 제의"},{"wordId":19674,"answer":"speed limit","form":"원형","example":"The police officer said I was driving ten miles over the speed limit.","exampleTranslation":"경찰관은 내가 제한 속도보다 십 마일 빠르게 달렸다고 했다.","sense":"제한 속도"},{"wordId":19675,"answer":"sense of humor","form":"원형","example":"Our math teacher has a great sense of humor and tells funny stories.","exampleTranslation":"수학 선생님은 유머 감각이 뛰어나서 재미있는 이야기를 해 주신다.","sense":"유머 감각"},{"wordId":19676,"answer":"body language","form":"원형","example":"Good teachers watch the body language of their students during class.","exampleTranslation":"좋은 선생님은 수업 중에 학생들의 몸짓을 잘 살핀다.","sense":"몸짓 언어"},{"wordId":19677,"answer":"peace of mind","form":"원형","example":"Locking the doors twice at night gives my mom peace of mind.","exampleTranslation":"밤에 문을 두 번 잠그는 게 엄마에게는 안심이 된다.","sense":"마음의 평화"},{"wordId":19678,"answer":"piece of advice","form":"원형","example":"My grandfather gave me one piece of advice before my first job interview.","exampleTranslation":"할아버지는 내 첫 면접 전에 조언 한마디를 해 주셨다.","sense":"조언 한마디"},{"wordId":19679,"answer":"the movie starts","form":"원형","example":"We always buy popcorn and find our seats before the movie starts.","exampleTranslation":"우리는 늘 영화가 시작하기 전에 팝콘을 사고 자리를 찾는다.","sense":"영화가 시작하다"},{"wordId":19680,"answer":"change of plans","form":"원형","example":"There was a change of plans, and the school trip moved to Friday.","exampleTranslation":"계획이 변경돼서 학교 견학이 금요일로 옮겨졌다.","sense":"계획 변경"},{"wordId":19681,"answer":"matter of time","form":"원형","example":"Our old washing machine is so noisy that a breakdown is just a matter of time.","exampleTranslation":"낡은 세탁기가 너무 시끄러워서 고장 나는 건 시간문제다.","sense":"시간문제"},{"wordId":19682,"answer":"lack of sleep","form":"원형","example":"The doctor said my son's bad grades might come from lack of sleep.","exampleTranslation":"의사는 아들의 나쁜 성적이 수면 부족 때문일 수도 있다고 했다.","sense":"수면 부족"},{"wordId":19683,"answer":"burst of energy","form":"원형","example":"The kids got a burst of energy right after eating birthday cake.","exampleTranslation":"아이들은 생일 케이크를 먹자마자 갑자기 기운이 솟았다.","sense":"갑자기 솟는 기운"},{"wordId":19684,"answer":"sense of direction","form":"원형","example":"My dad has a great sense of direction, even in cities he does not know.","exampleTranslation":"아빠는 모르는 도시에서도 방향 감각이 아주 좋으시다.","sense":"방향 감각"},{"wordId":19685,"answer":"time zone","form":"원형","example":"When you fly to Europe, remember to change your watch to the new time zone.","exampleTranslation":"유럽으로 비행기를 타고 가면 시계를 새 시간대에 맞추는 걸 잊지 마.","sense":"시간대"},{"wordId":19686,"answer":"weather forecast","form":"원형","example":"My grandfather watches the weather forecast every evening before dinner.","exampleTranslation":"할아버지는 매일 저녁 식사 전에 일기 예보를 보신다.","sense":"일기 예보"},{"wordId":19687,"answer":"price range","form":"원형","example":"The real estate agent showed us apartments in our price range downtown.","exampleTranslation":"부동산 중개인이 시내에서 우리 가격대에 맞는 아파트를 보여 줬다.","sense":"가격대"},{"wordId":19688,"answer":"food poisoning","form":"원형","example":"Half of the wedding guests got food poisoning from the chicken salad.","exampleTranslation":"결혼식 하객 절반이 치킨 샐러드 때문에 식중독에 걸렸다.","sense":"식중독"},{"wordId":19689,"answer":"the meeting runs late","form":"원형","example":"Please start dinner without me if the meeting runs late tonight.","exampleTranslation":"오늘 밤 회의가 길어지면 나 없이 먼저 저녁 먹어.","sense":"회의가 길어지다"},{"wordId":19690,"answer":"the storm hits","form":"원형","example":"The farmers try to bring the cows inside before the storm hits.","exampleTranslation":"농부들은 폭풍이 닥치기 전에 소들을 안으로 들이려고 한다.","sense":"폭풍이 닥치다"},{"wordId":19691,"answer":"the light turns red","form":"원형","example":"My son always counts out loud when the light turns red at the crosswalk.","exampleTranslation":"아들은 횡단보도에서 신호가 빨간불로 바뀌면 늘 소리 내어 숫자를 센다.","sense":"빨간불로 바뀌다"},{"wordId":19692,"answer":"job market","form":"원형","example":"My sister is studying coding because the job market for programmers is strong.","exampleTranslation":"프로그래머 취업 시장이 좋아서 언니는 코딩을 공부하고 있다.","sense":"취업 시장"},{"wordId":19693,"answer":"car accident","form":"원형","example":"My uncle was in a small car accident, but nobody was hurt.","exampleTranslation":"삼촌이 작은 교통사고를 당했지만 아무도 다치지 않았다.","sense":"교통사고"},{"wordId":19694,"answer":"mood swings","form":"원형","example":"Teenagers often have mood swings when they are hungry or tired.","exampleTranslation":"십 대들은 배고프거나 피곤하면 감정 기복이 심해지곤 한다.","sense":"감정 기복"},{"wordId":19695,"answer":"the rain stops","form":"원형","example":"The kids are waiting by the window to play outside when the rain stops.","exampleTranslation":"아이들은 비가 그치면 밖에서 놀려고 창가에서 기다리고 있다.","sense":"비가 그치다"},{"wordId":19696,"answer":"flight delay","form":"원형","example":"The airline gave us free meal coupons because of the flight delay.","exampleTranslation":"항공편 지연 때문에 항공사가 무료 식사 쿠폰을 줬다.","sense":"항공편 지연"},{"wordId":19697,"answer":"the plane lands","form":"원형","example":"The kids always clap when the plane lands safely on the runway.","exampleTranslation":"아이들은 비행기가 활주로에 무사히 착륙하면 늘 박수를 친다.","sense":"비행기가 착륙하다"},{"wordId":19698,"answer":"the deadline approaches","form":"원형","example":"The office gets very quiet and serious as the deadline approaches each month.","exampleTranslation":"매달 마감이 다가오면 사무실이 아주 조용하고 진지해진다.","sense":"마감이 다가오다"},{"wordId":19699,"answer":"my phone buzzes","form":"원형","example":"At dinner, I ignore all messages, even when my phone buzzes.","exampleTranslation":"저녁 식사 때는 휴대폰이 진동해도 메시지를 모두 무시한다.","sense":"휴대폰이 진동하다"},{"wordId":19700,"answer":"family business","form":"원형","example":"My aunt and uncle run a small bakery as a family business.","exampleTranslation":"이모와 이모부는 작은 빵집을 가업으로 운영한다.","sense":"가족 사업"},{"wordId":19701,"answer":"apologize for","form":"원형","example":"The airline wanted to apologize for the lost bags and offered us a voucher.","exampleTranslation":"항공사는 잃어버린 가방에 대해 사과하고 싶다며 상품권을 줬다.","sense":"사과하다"},{"wordId":19702,"answer":"admit to","form":"원형","example":"My little brother finally decided to admit to breaking the window.","exampleTranslation":"남동생은 결국 창문을 깬 걸 인정하기로 했다.","sense":"인정하다"},{"wordId":19703,"answer":"agree with","form":"원형","example":"Most of the students agree with the new rule about phones in class.","exampleTranslation":"학생 대부분이 수업 중 휴대폰에 관한 새 규칙에 동의한다.","sense":"동의하다"},{"wordId":19704,"answer":"belong to","form":"원형","example":"The lost keys at the front desk might belong to the man in room five.","exampleTranslation":"프런트에 있는 잃어버린 열쇠는 오 호실 남자의 것일지도 모른다.","sense":"의 것이다"},{"wordId":19705,"answer":"major in","form":"원형","example":"My daughter wants to major in biology and become a vet.","exampleTranslation":"딸은 생물학을 전공해서 수의사가 되고 싶어 한다.","sense":"전공하다"},{"wordId":19706,"answer":"worry about","form":"원형","example":"My parents always worry about me when I travel alone.","exampleTranslation":"부모님은 내가 혼자 여행하면 늘 나를 걱정하신다.","sense":"걱정하다"},{"wordId":19707,"answer":"concentrate on","form":"원형","example":"The kids need a quiet room to concentrate on their homework after school.","exampleTranslation":"아이들은 방과 후 숙제에 집중할 조용한 방이 필요하다.","sense":"집중하다"},{"wordId":19708,"answer":"suffer from","form":"원형","example":"Some office workers suffer from back pain after sitting all day.","exampleTranslation":"일부 사무직 직원은 하루 종일 앉아 있어서 허리 통증을 앓는다.","sense":"앓다"},{"wordId":19709,"answer":"recover from","form":"원형","example":"Our soccer team needs a few weeks to recover from the long season.","exampleTranslation":"우리 축구팀은 긴 시즌에서 회복하려면 몇 주가 필요하다.","sense":"회복하다"},{"wordId":19710,"answer":"participate in","form":"원형","example":"All the students in my class want to participate in the school play.","exampleTranslation":"우리 반 학생 모두가 학교 연극에 참여하고 싶어 한다.","sense":"참여하다"},{"wordId":19711,"answer":"believe in","form":"원형","example":"My coach told me to believe in myself before the big race.","exampleTranslation":"코치는 큰 경주 전에 나 자신을 믿으라고 했다.","sense":"믿다"},{"wordId":19712,"answer":"specialize in","form":"원형","example":"The new bakery downtown will specialize in gluten-free cakes and cookies.","exampleTranslation":"시내에 새로 생긴 빵집은 글루텐 없는 케이크와 쿠키를 전문으로 할 것이다.","sense":"전문으로 하다"},{"wordId":19713,"answer":"invest in","form":"원형","example":"Many young people want to invest in a good laptop for their studies.","exampleTranslation":"많은 젊은이가 공부를 위해 좋은 노트북에 투자하고 싶어 한다.","sense":"투자하다"},{"wordId":19714,"answer":"result in","form":"원형","example":"Driving too fast on wet roads can result in serious accidents.","exampleTranslation":"젖은 도로에서 너무 빨리 달리면 큰 사고로 이어질 수 있다.","sense":"낳다"},{"wordId":19715,"answer":"interfere with","form":"원형","example":"Loud music from the apartment upstairs can interfere with my online classes.","exampleTranslation":"위층 아파트의 시끄러운 음악이 내 온라인 수업을 방해할 수 있다.","sense":"방해하다"},{"wordId":19716,"answer":"argue with","form":"원형","example":"My kids sometimes argue with each other about who gets the front seat.","exampleTranslation":"우리 아이들은 가끔 누가 앞자리에 앉을지를 두고 서로 말다툼한다.","sense":"말다툼하다"},{"wordId":19717,"answer":"struggle with","form":"원형","example":"Many new drivers struggle with parking in small spaces downtown.","exampleTranslation":"많은 초보 운전자가 시내의 좁은 공간에 주차하느라 애를 먹는다.","sense":"애를 먹다"},{"wordId":19718,"answer":"respond to","form":"원형","example":"The company promises to respond to every customer email within one day.","exampleTranslation":"그 회사는 모든 고객 이메일에 하루 안에 답하겠다고 약속한다.","sense":"응답하다"},{"wordId":19719,"answer":"agree on","form":"원형","example":"The family could not agree on a restaurant for grandpa's birthday dinner.","exampleTranslation":"가족은 할아버지 생신 저녁 식당을 정하지 못했다.","sense":"함께 정하다"},{"wordId":19720,"answer":"adapt to","form":"원형","example":"Our new puppy needs time to adapt to living in a small apartment.","exampleTranslation":"새 강아지는 작은 아파트 생활에 적응할 시간이 필요하다.","sense":"적응하다"},{"wordId":19721,"answer":"contribute to","form":"원형","example":"Every student can contribute to keeping the classroom clean and tidy.","exampleTranslation":"모든 학생이 교실을 깨끗하게 유지하는 데 기여할 수 있다.","sense":"기여하다"},{"wordId":19722,"answer":"refer to","form":"원형","example":"The teacher asked us to refer to the map on page twenty.","exampleTranslation":"선생님은 이십 쪽에 있는 지도를 참고하라고 하셨다.","sense":"참고하다"},{"wordId":19723,"answer":"laugh at","form":"원형","example":"Good friends laugh at your silly jokes even when they are not funny.","exampleTranslation":"좋은 친구는 재미없는 농담에도 웃어 준다.","sense":"보고 웃다"},{"wordId":19724,"answer":"stare at","form":"원형","example":"The kids at the zoo love to stare at the monkeys for hours.","exampleTranslation":"동물원에 온 아이들은 몇 시간이고 원숭이를 빤히 쳐다보는 걸 좋아한다.","sense":"빤히 쳐다보다"},{"wordId":19725,"answer":"prepare for","form":"원형","example":"Our town is starting to prepare for the winter festival next month.","exampleTranslation":"우리 마을은 다음 달 겨울 축제를 준비하기 시작했다.","sense":"준비하다"},{"wordId":19726,"answer":"vote for","form":"원형","example":"The kids can vote for the best costume at the Halloween party.","exampleTranslation":"아이들은 핼러윈 파티에서 최고의 의상에 투표할 수 있다.","sense":"투표하다"},{"wordId":19727,"answer":"search for","form":"원형","example":"My grandmother uses her phone to search for new soup recipes.","exampleTranslation":"할머니는 휴대폰으로 새 수프 요리법을 검색하신다.","sense":"검색하다"},{"wordId":19728,"answer":"hope for","form":"원형","example":"The farmers in the valley hope for rain after weeks of dry weather.","exampleTranslation":"계곡 농부들은 몇 주 동안 가문 끝에 비를 바란다.","sense":"바라다"},{"wordId":19729,"answer":"comment on","form":"원형","example":"Many viewers comment on the cooking videos with their own tips.","exampleTranslation":"많은 시청자가 요리 영상에 자기만의 요령을 댓글로 단다.","sense":"댓글을 달다"},{"wordId":19730,"answer":"knock on","form":"원형","example":"The delivery driver will knock on the door if nobody answers the bell.","exampleTranslation":"초인종에 아무도 안 나오면 배달 기사가 문을 두드릴 것이다.","sense":"두드리다"},{"wordId":19731,"answer":"dream of","form":"원형","example":"Many children in my town dream of becoming soccer players.","exampleTranslation":"우리 마을의 많은 아이가 축구 선수가 되기를 꿈꾼다.","sense":"꿈꾸다"},{"wordId":19732,"answer":"approve of","form":"원형","example":"My grandmother does not approve of eating dinner in front of the TV.","exampleTranslation":"할머니는 텔레비전 앞에서 저녁 먹는 것을 좋게 여기지 않으신다.","sense":"좋게 여기다"},{"wordId":19733,"answer":"consist of","form":"원형","example":"Our English test will consist of a listening part and a short essay.","exampleTranslation":"우리 영어 시험은 듣기와 짧은 작문으로 구성될 것이다.","sense":"구성되다"},{"wordId":19734,"answer":"get rid of","form":"원형","example":"I sprayed some vinegar in the closet to get rid of the bad smell.","exampleTranslation":"나쁜 냄새를 없애려고 옷장에 식초를 뿌렸다.","sense":"없애다"},{"wordId":19735,"answer":"speak highly of","form":"원형","example":"Former students always speak highly of their old math teacher.","exampleTranslation":"졸업생들은 늘 옛 수학 선생님을 높이 평가한다.","sense":"칭찬하다"},{"wordId":19736,"answer":"succeed in","form":"원형","example":"With hard work, you can succeed in any job you choose.","exampleTranslation":"열심히 하면 어떤 일을 택하든 성공할 수 있다.","sense":"성공하다"},{"wordId":19737,"answer":"arrive in","form":"원형","example":"If the weather is good, we will arrive in Paris before lunch.","exampleTranslation":"날씨가 좋으면 우리는 점심 전에 파리에 도착할 것이다.","sense":"도착하다"},{"wordId":19738,"answer":"graduate from","form":"원형","example":"My little brother is going to graduate from high school in June.","exampleTranslation":"남동생은 유월에 고등학교를 졸업할 예정이다.","sense":"졸업하다"},{"wordId":19739,"answer":"sympathize with","form":"원형","example":"Many parents sympathize with the new teacher because her class is so big.","exampleTranslation":"반이 너무 커서 많은 학부모가 새 선생님에게 공감한다.","sense":"공감하다"},{"wordId":19740,"answer":"compete with","form":"원형","example":"Our small school team will compete with the best teams in the state.","exampleTranslation":"우리 작은 학교 팀이 주에서 가장 강한 팀들과 경쟁할 것이다.","sense":"경쟁하다"},{"wordId":19741,"answer":"care about","form":"원형","example":"Good doctors care about their patients, not just their test results.","exampleTranslation":"좋은 의사는 검사 결과만이 아니라 환자를 소중히 여긴다.","sense":"소중히 여기다"},{"wordId":19742,"answer":"react to","form":"원형","example":"Babies often react to loud noises by crying or covering their ears.","exampleTranslation":"아기들은 큰 소리에 울거나 귀를 막으며 반응하곤 한다.","sense":"반응하다"},{"wordId":19743,"answer":"qualify for","form":"원형","example":"You need to live here for one year to qualify for the lower tuition.","exampleTranslation":"더 낮은 등록금 자격을 얻으려면 여기서 일 년을 살아야 한다.","sense":"자격을 얻다"},{"wordId":19744,"answer":"differ from","form":"원형","example":"My taste in music tends to differ from my twin sister's.","exampleTranslation":"내 음악 취향은 쌍둥이 자매의 취향과 다른 편이다.","sense":"다르다"},{"wordId":19745,"answer":"benefit from","form":"원형","example":"Shy students can benefit from joining a small club at school.","exampleTranslation":"수줍은 학생들은 학교에서 작은 동아리에 들어가면 도움을 받을 수 있다.","sense":"덕을 보다"},{"wordId":19746,"answer":"drive carefully","form":"원형","example":"My mom always reminds my brother to drive carefully near the school.","exampleTranslation":"엄마는 늘 오빠에게 학교 근처에서 조심해서 운전하라고 하신다.","sense":"조심해서 운전하다"},{"wordId":19747,"answer":"sleep soundly","form":"원형","example":"This new pillow is so soft that I sleep soundly every night now.","exampleTranslation":"이 새 베개가 너무 푹신해서 요즘 매일 밤 푹 잔다.","sense":"푹 자다"},{"wordId":19748,"answer":"speak fluently","form":"원형","example":"After a year in Spain, my cousin can speak fluently with the locals.","exampleTranslation":"스페인에서 일 년을 지낸 뒤 사촌은 현지인들과 유창하게 말할 수 있다.","sense":"유창하게 말하다"},{"wordId":19749,"answer":"work remotely","form":"원형","example":"Since the baby was born, my husband prefers to work remotely on Fridays.","exampleTranslation":"아기가 태어난 뒤 남편은 금요일엔 재택근무를 선호한다.","sense":"원격으로 일하다"},{"wordId":19750,"answer":"dress casually","form":"원형","example":"Our office lets everyone dress casually on Fridays during the summer.","exampleTranslation":"우리 회사는 여름 동안 금요일마다 모두 편하게 입을 수 있게 해 준다.","sense":"편하게 입다"},{"wordId":19751,"answer":"a people person","form":"원형","example":"My uncle is a people person, so he enjoys his job as a tour guide.","exampleTranslation":"삼촌은 사교적인 사람이라 관광 안내원 일을 즐긴다.","sense":"사교적인 사람"},{"wordId":19752,"answer":"down to earth","form":"원형","example":"Our new boss is very down to earth and eats lunch with everyone.","exampleTranslation":"새 상사는 아주 소탈해서 모두와 함께 점심을 먹는다.","sense":"소탈한"},{"wordId":19753,"answer":"a night owl","form":"원형","example":"My roommate is a night owl who studies until three in the morning.","exampleTranslation":"룸메이트는 새벽 세 시까지 공부하는 올빼미형이다.","sense":"올빼미형"},{"wordId":19754,"answer":"a social butterfly","form":"원형","example":"My son was a social butterfly on his first day at summer camp.","exampleTranslation":"아들은 여름 캠프 첫날부터 인싸였다.","sense":"사교성 좋은 사람"},{"wordId":19755,"answer":"a wet blanket","form":"원형","example":"Nobody wants to be a wet blanket at a birthday party.","exampleTranslation":"생일 파티에서 흥을 깨는 사람이 되고 싶은 사람은 없다.","sense":"흥을 깨는 사람"},{"wordId":19756,"answer":"a know-it-all","form":"원형","example":"My cousin acts like a know-it-all whenever we talk about cars.","exampleTranslation":"사촌은 자동차 이야기만 나오면 아는 척을 한다.","sense":"아는 척하는 사람"},{"wordId":19757,"answer":"a team player","form":"원형","example":"The coach picked Mia as captain because she is a team player.","exampleTranslation":"코치는 미아가 협동을 잘해서 주장으로 뽑았다.","sense":"협동을 잘하는 사람"},{"wordId":19758,"answer":"a go-getter","form":"원형","example":"My niece is a go-getter who sold lemonade every summer as a kid.","exampleTranslation":"조카는 어릴 때 매년 여름 레모네이드를 판 적극적인 아이다.","sense":"적극적인 사람"},{"wordId":19759,"answer":"a busybody","form":"원형","example":"The new man in our building is a busybody who asks everyone personal questions.","exampleTranslation":"우리 건물에 새로 온 남자는 모두에게 사적인 질문을 하는 참견쟁이다.","sense":"참견쟁이"},{"wordId":19760,"answer":"a cheapskate","form":"원형","example":"My uncle is a cheapskate who cuts coupons for everything he buys.","exampleTranslation":"삼촌은 사는 물건마다 쿠폰을 오려 쓰는 짠돌이다.","sense":"구두쇠"},{"wordId":19761,"answer":"a smart cookie","form":"원형","example":"My little nephew solved the puzzle in a minute, so he is a smart cookie.","exampleTranslation":"어린 조카가 일 분 만에 퍼즐을 풀었으니 똑똑한 아이다.","sense":"똑똑한 사람"},{"wordId":19762,"answer":"a tough cookie","form":"원형","example":"Our coach is a tough cookie who trains outside even in the snow.","exampleTranslation":"우리 코치는 눈 속에서도 밖에서 훈련하는 강인한 사람이다.","sense":"강인한 사람"},{"wordId":19763,"answer":"a party animal","form":"원형","example":"My cousin is a party animal who goes dancing every Friday night.","exampleTranslation":"사촌은 금요일 밤마다 춤추러 가는 파티광이다.","sense":"파티광"},{"wordId":19764,"answer":"a lone wolf","form":"원형","example":"In group projects, my brother acts like a lone wolf and works by himself.","exampleTranslation":"조별 과제에서 오빠는 독불장군처럼 혼자 작업한다.","sense":"혼자 행동하는 사람"},{"wordId":19765,"answer":"a big shot","form":"원형","example":"My old classmate is now a big shot at a famous tech company.","exampleTranslation":"옛 반 친구는 지금 유명한 기술 회사의 거물이다.","sense":"거물"},{"wordId":19766,"answer":"a bookworm","form":"원형","example":"My daughter is a bookworm who always has a novel in her bag.","exampleTranslation":"딸은 가방에 늘 소설책을 넣고 다니는 책벌레다.","sense":"책벌레"},{"wordId":19767,"answer":"a worrywart","form":"원형","example":"My mom is a worrywart who calls me every time it snows.","exampleTranslation":"엄마는 눈이 올 때마다 전화하시는 걱정 대장이다.","sense":"걱정 많은 사람"},{"wordId":19768,"answer":"a control freak","form":"원형","example":"My sister is a control freak when she plans our family trips.","exampleTranslation":"언니는 가족 여행을 계획할 때 모든 걸 통제하려 든다.","sense":"통제하려는 사람"},{"wordId":19769,"answer":"a neat freak","form":"원형","example":"My mother-in-law is a neat freak who cleans the kitchen three times a day.","exampleTranslation":"시어머니는 하루에 세 번 부엌을 청소하는 깔끔쟁이다.","sense":"깔끔쟁이"},{"wordId":19770,"answer":"a pushover","form":"원형","example":"Our substitute teacher was a pushover, so the class was very noisy.","exampleTranslation":"대리 선생님이 만만해서 교실이 아주 시끄러웠다.","sense":"만만한 사람"},{"wordId":19771,"answer":"a sore loser","form":"원형","example":"My little brother is a sore loser and throws the board game pieces.","exampleTranslation":"남동생은 지면 성질을 내며 보드게임 말을 던진다.","sense":"지면 성질내는 사람"},{"wordId":19772,"answer":"a backseat driver","form":"원형","example":"My grandmother is a backseat driver who reminds me about every stop sign.","exampleTranslation":"할머니는 정지 표지판마다 알려 주시는 운전 훈수꾼이다.","sense":"운전 훈수꾼"},{"wordId":19773,"answer":"a jack of all trades","form":"원형","example":"My grandfather was a jack of all trades who built our kitchen table himself.","exampleTranslation":"할아버지는 우리 식탁을 직접 만드신 만능 재주꾼이셨다.","sense":"만능 재주꾼"},{"wordId":19774,"answer":"a late bloomer","form":"원형","example":"My uncle was a late bloomer and started his own restaurant at fifty.","exampleTranslation":"삼촌은 대기만성형이라 쉰 살에 자기 식당을 차렸다.","sense":"대기만성형"},{"wordId":19775,"answer":"a heart of gold","form":"원형","example":"The old woman next door has a heart of gold and bakes for everyone.","exampleTranslation":"옆집 할머니는 마음씨가 고와서 모두를 위해 빵을 구우신다.","sense":"착한 마음씨"},{"wordId":19776,"answer":"hot-headed","form":"원형","example":"Our hot-headed coach yelled at the referee during the final game.","exampleTranslation":"성미 급한 코치가 결승전에서 심판에게 소리를 질렀다.","sense":"욱하는"},{"wordId":19777,"answer":"thick-skinned","form":"원형","example":"Actors need to be thick-skinned because critics can be very harsh.","exampleTranslation":"평론가가 아주 가혹할 수 있어서 배우는 비판에 끄떡없어야 한다.","sense":"비판에 끄떡없는"},{"wordId":19778,"answer":"thin-skinned","form":"원형","example":"My sister is thin-skinned and cries when anyone criticizes her drawings.","exampleTranslation":"언니는 예민해서 누가 그림을 비판하면 운다.","sense":"쉽게 상처받는"},{"wordId":19779,"answer":"level-headed","form":"원형","example":"Our pilot stayed level-headed when the plane hit bad weather.","exampleTranslation":"비행기가 악천후를 만났을 때 기장은 침착함을 유지했다.","sense":"침착한"},{"wordId":19780,"answer":"laid-back","form":"원형","example":"My new roommate is very laid-back and never worries about anything.","exampleTranslation":"새 룸메이트는 아주 느긋해서 무엇도 걱정하지 않는다.","sense":"느긋한"},{"wordId":19781,"answer":"full of himself","form":"원형","example":"After winning one race, my cousin became so full of himself.","exampleTranslation":"경주 한 번 이기고 나서 사촌은 자만심이 하늘을 찔렀다.","sense":"자만심에 찬"},{"wordId":19782,"answer":"stuck-up","form":"원형","example":"The new girl in class seemed stuck-up, but she was just nervous.","exampleTranslation":"반에 새로 온 여자아이는 콧대가 높아 보였지만 그냥 긴장한 거였다.","sense":"거만한"},{"wordId":19783,"answer":"a stick in the mud","form":"원형","example":"My dad is a stick in the mud who never wants to try new restaurants.","exampleTranslation":"아빠는 새로운 식당에 가 보려 하지 않는 고리타분한 사람이다.","sense":"고리타분한 사람"},{"wordId":19784,"answer":"the life of the party","form":"원형","example":"My aunt becomes the life of the party when she starts singing.","exampleTranslation":"이모는 노래를 시작하면 분위기 메이커가 된다.","sense":"분위기 메이커"},{"wordId":19785,"answer":"salt of the earth","form":"원형","example":"The farmers in this village are the salt of the earth and very generous.","exampleTranslation":"이 마을 농부들은 소박하고 정직하며 아주 너그럽다.","sense":"정직한 사람"},{"wordId":19786,"answer":"a chip off the old block","form":"원형","example":"My daughter loves baking like her mom, so she is a chip off the old block.","exampleTranslation":"딸은 엄마처럼 빵 굽기를 좋아하니 엄마를 꼭 닮았다.","sense":"부모를 꼭 닮은 자식"},{"wordId":19787,"answer":"like father, like son","form":"원형","example":"My husband and our son both snore loudly, so like father, like son.","exampleTranslation":"남편과 아들이 둘 다 코를 크게 고니 부전자전이다.","sense":"부전자전"},{"wordId":19788,"answer":"set in his ways","form":"원형","example":"My uncle is set in his ways and still writes letters by hand.","exampleTranslation":"삼촌은 자기 방식을 고집해서 아직도 손으로 편지를 쓴다.","sense":"고지식한"},{"wordId":19789,"answer":"a cold fish","form":"원형","example":"The new manager seemed like a cold fish until the holiday party.","exampleTranslation":"새 매니저는 연말 파티 전까지는 정 없는 사람 같았다.","sense":"냉정한 사람"},{"wordId":19790,"answer":"a big mouth","form":"원형","example":"My cousin has a big mouth, so the whole family knew my news by lunch.","exampleTranslation":"사촌은 입이 가벼워서 점심때쯤 온 가족이 내 소식을 알았다.","sense":"입이 가벼운 사람"},{"wordId":19791,"answer":"a class clown","form":"원형","example":"My son is a class clown, and his teacher says he makes everyone smile.","exampleTranslation":"아들은 반의 익살꾼이라 선생님은 아들이 모두를 웃게 한다고 하신다.","sense":"반의 익살꾼"},{"wordId":19793,"answer":"a copycat","form":"원형","example":"My daughter is a copycat who wears the same shoes as her best friend.","exampleTranslation":"딸은 단짝 친구와 같은 신발을 신는 따라쟁이다.","sense":"따라쟁이"},{"wordId":19794,"answer":"a scaredy-cat","form":"원형","example":"My brother is a scaredy-cat who sleeps with the light on after scary movies.","exampleTranslation":"오빠는 무서운 영화를 보고 나면 불을 켜고 자는 겁쟁이다.","sense":"겁쟁이"},{"wordId":19795,"answer":"a free spirit","form":"원형","example":"My aunt is a free spirit who lives in a small van by the ocean.","exampleTranslation":"이모는 바닷가 작은 밴에서 사는 자유로운 영혼이다.","sense":"자유로운 영혼"},{"wordId":19796,"answer":"an old soul","form":"원형","example":"My teenage daughter is an old soul who loves black and white movies.","exampleTranslation":"십 대인 딸은 흑백 영화를 좋아하는 애어른이다.","sense":"성숙한 사람"},{"wordId":19797,"answer":"a man of few words","form":"원형","example":"Our new neighbor is a man of few words but always waves hello.","exampleTranslation":"새 이웃은 말수가 적지만 늘 손을 흔들어 인사한다.","sense":"말수가 적은 사람"},{"wordId":19798,"answer":"wear your heart on your sleeve","form":"원형","example":"In this job you cannot wear your heart on your sleeve with angry customers.","exampleTranslation":"이 일에서는 화난 손님 앞에서 감정을 그대로 드러내면 안 된다.","sense":"감정을 드러내다"},{"wordId":19799,"answer":"a creature of habit","form":"원형","example":"My grandfather is a creature of habit who walks the same path every morning.","exampleTranslation":"할아버지는 매일 아침 같은 길을 걷는 습관대로 사는 분이다.","sense":"습관대로 사는 사람"},{"wordId":19800,"answer":"a homebody","form":"원형","example":"My brother is a homebody who spends every weekend playing games in his room.","exampleTranslation":"오빠는 주말마다 방에서 게임을 하는 집돌이다.","sense":"집돌이"},{"wordId":19802,"answer":"luck of the draw","form":"원형","example":"At the school raffle, getting the bike was just the luck of the draw.","exampleTranslation":"학교 경품 추첨에서 자전거를 받은 건 그저 운이었다.","sense":"복불복"},{"wordId":19803,"answer":"lucky break","form":"원형","example":"Meeting the director at the coffee shop was a lucky break for the young actor.","exampleTranslation":"커피숍에서 감독을 만난 건 젊은 배우에게 뜻밖의 행운이었다.","sense":"뜻밖의 행운"},{"wordId":19804,"answer":"knock on wood","form":"원형","example":"Our old car has never broken down on a trip, knock on wood.","exampleTranslation":"우리 낡은 차는 여행 중에 한 번도 고장 난 적이 없어, 부정 타지 않게.","sense":"부정 타지 않게"},{"wordId":19805,"answer":"fingers crossed","form":"원형","example":"The doctor will call with the results this afternoon, so fingers crossed.","exampleTranslation":"오늘 오후에 의사가 결과를 알려 준다니 잘되길 빌자.","sense":"행운을 빌다"},{"wordId":19807,"answer":"try your luck","form":"원형","example":"The concert is sold out, but you can try your luck at the door tonight.","exampleTranslation":"공연은 매진이지만 오늘 밤 입구에서 한번 운을 시험해 볼 수 있어.","sense":"운을 시험하다"},{"wordId":19808,"answer":"push your luck","form":"원형","example":"The teacher already gave you extra time, so do not push your luck.","exampleTranslation":"선생님이 이미 시간을 더 주셨으니 너무 무리하지 마.","sense":"운을 믿고 무리하다"},{"wordId":19809,"answer":"out of luck","form":"원형","example":"We reached the bakery at noon but were out of luck; the bread was gone.","exampleTranslation":"정오에 빵집에 갔지만 빵이 다 팔려서 허탕 쳤다.","sense":"허탕 친"},{"wordId":19810,"answer":"as luck would have it","form":"원형","example":"As luck would have it, my old teacher was sitting next to me on the plane.","exampleTranslation":"공교롭게도 비행기에서 옛 선생님이 내 옆자리에 앉아 계셨다.","sense":"공교롭게도"},{"wordId":19811,"answer":"a stroke of luck","form":"원형","example":"It was a stroke of luck that the rain stopped right before the outdoor wedding.","exampleTranslation":"야외 결혼식 직전에 비가 그친 건 뜻밖의 행운이었다.","sense":"뜻밖의 행운"},{"wordId":19812,"answer":"make it big","form":"원형","example":"My cousin plays guitar every night because she wants to make it big someday.","exampleTranslation":"사촌은 언젠가 크게 성공하고 싶어서 매일 밤 기타를 친다.","sense":"크게 성공하다"},{"wordId":19813,"answer":"break a leg","form":"원형","example":"Before the school play started, I hugged my daughter and told her to break a leg.","exampleTranslation":"학교 연극이 시작되기 전에 딸을 안아 주며 잘하라고 행운을 빌어 줬다.","sense":"행운을 빌어"},{"wordId":19814,"answer":"give it a whirl","form":"원형","example":"The new yoga class looks hard, but my mom wants to give it a whirl.","exampleTranslation":"새 요가 수업이 어려워 보이지만 엄마는 한번 해 보고 싶어 하신다.","sense":"한번 해 보다"},{"wordId":19815,"answer":"take a stab at","form":"원형","example":"Nobody could fix the old radio, so my grandfather decided to take a stab at it.","exampleTranslation":"아무도 낡은 라디오를 못 고쳐서 할아버지가 한번 해 보기로 하셨다.","sense":"시도해 보다"},{"wordId":19816,"answer":"work your fingers to the bone","form":"원형","example":"To pay for college, you might have to work your fingers to the bone for years.","exampleTranslation":"대학 학비를 내려면 몇 년 동안 뼈 빠지게 일해야 할지도 모른다.","sense":"뼈 빠지게 일하다"},{"wordId":19817,"answer":"burn the candle at both ends","form":"원형","example":"Students who burn the candle at both ends during exams often get sick.","exampleTranslation":"시험 기간에 무리해서 공부하는 학생들은 종종 병이 난다.","sense":"무리하다"},{"wordId":19818,"answer":"pull out all the stops","form":"원형","example":"The school will pull out all the stops for its one hundredth anniversary.","exampleTranslation":"학교는 개교 백 주년 기념행사에 총력을 기울일 것이다.","sense":"총력을 기울이다"},{"wordId":19819,"answer":"go all out","form":"원형","example":"Our neighbors always go all out with costumes and candy on Halloween.","exampleTranslation":"이웃들은 핼러윈마다 의상과 사탕에 아낌없이 공을 들인다.","sense":"전력을 다하다"},{"wordId":19820,"answer":"leave no stone unturned","form":"원형","example":"We will leave no stone unturned until we find the missing cat.","exampleTranslation":"잃어버린 고양이를 찾을 때까지 백방으로 찾아볼 것이다.","sense":"백방으로 노력하다"},{"wordId":19821,"answer":"keep at it","form":"원형","example":"Learning the piano is slow at first, but if you keep at it, you improve.","exampleTranslation":"피아노는 처음엔 더디지만 꾸준히 하면 늘어.","sense":"꾸준히 계속하다"},{"wordId":19822,"answer":"tough it out","form":"원형","example":"The hike up the mountain was tiring, but the kids decided to tough it out.","exampleTranslation":"산 오르는 길이 힘들었지만 아이들은 끝까지 버티기로 했다.","sense":"끝까지 버티다"},{"wordId":19823,"answer":"get back on your feet","form":"원형","example":"With help from good friends, you can get back on your feet after a hard year.","exampleTranslation":"좋은 친구들의 도움이 있으면 힘든 한 해를 보낸 뒤에도 다시 일어설 수 있다.","sense":"다시 일어서다"},{"wordId":19824,"answer":"land on your feet","form":"원형","example":"Do not worry about moving abroad, because you always land on your feet.","exampleTranslation":"해외로 이사하는 거 걱정하지 마, 너는 늘 잘 풀리잖아.","sense":"잘 풀리다"},{"wordId":19825,"answer":"come out on top","form":"원형","example":"After a long night of board games, my grandmother managed to come out on top.","exampleTranslation":"긴 보드게임 밤 끝에 할머니가 결국 이기셨다.","sense":"결국 이기다"},{"wordId":19826,"answer":"a win-win","form":"원형","example":"Sharing a car to work is a win-win for me and my coworker.","exampleTranslation":"차를 같이 타고 출근하는 건 나와 동료 모두에게 이롭다.","sense":"모두에게 이로운 상황"},{"wordId":19827,"answer":"win hands down","form":"원형","example":"If we had a pie contest, my aunt would win hands down every year.","exampleTranslation":"파이 대회가 있다면 이모가 매년 손쉽게 이길 것이다.","sense":"손쉽게 이기다"},{"wordId":19828,"answer":"with flying colors","form":"원형","example":"My son passed his swimming test with flying colors on Saturday.","exampleTranslation":"아들은 토요일 수영 시험을 아주 훌륭하게 통과했다.","sense":"아주 훌륭하게"},{"wordId":19829,"answer":"a feather in your cap","form":"원형","example":"Winning the science award will be a feather in your cap for college applications.","exampleTranslation":"과학상을 타면 대학 지원 때 자랑할 만한 업적이 될 거야.","sense":"자랑할 만한 업적"},{"wordId":19830,"answer":"a dream come true","form":"원형","example":"For my father, seeing the ocean for the first time was a dream come true.","exampleTranslation":"아빠에게 처음 바다를 본 것은 꿈이 이루어진 일이었다.","sense":"꿈이 이루어짐"},{"wordId":19831,"answer":"an overnight success","form":"원형","example":"The small band became an overnight success after their video went viral.","exampleTranslation":"그 작은 밴드는 영상이 퍼진 뒤 하루아침에 성공했다.","sense":"벼락 성공"},{"wordId":19832,"answer":"make a name for yourself","form":"원형","example":"You can make a name for yourself by posting your songs online every week.","exampleTranslation":"매주 노래를 온라인에 올리면 이름을 알릴 수 있다.","sense":"이름을 알리다"},{"wordId":19833,"answer":"shoot for the moon","form":"원형","example":"My teacher told the class to shoot for the moon when choosing their goals.","exampleTranslation":"선생님은 목표를 정할 때 원대하게 세우라고 반 아이들에게 말씀하셨다.","sense":"원대한 목표를 세우다"},{"wordId":19834,"answer":"go for it","form":"원형","example":"The water looks cold, but if you want to swim, go for it.","exampleTranslation":"물이 차가워 보이지만 수영하고 싶으면 해 봐.","sense":"도전해 봐"},{"wordId":19835,"answer":"you win some, you lose some","form":"원형","example":"Our team lost the final game, but you win some, you lose some.","exampleTranslation":"우리 팀이 결승에서 졌지만 이길 때도 있고 질 때도 있는 법이다.","sense":"이길 때도 질 때도 있다"},{"wordId":19836,"answer":"bend over backwards","form":"원형","example":"My grandparents bend over backwards to make every guest feel at home.","exampleTranslation":"조부모님은 모든 손님이 편하게 느끼도록 무척 애쓰신다.","sense":"무척 애쓰다"},{"wordId":19837,"answer":"work like a dog","form":"원형","example":"During the holiday season, my uncle has to work like a dog at the post office.","exampleTranslation":"연말 시즌에는 삼촌이 우체국에서 죽어라 일해야 한다.","sense":"죽어라 일하다"},{"wordId":19838,"answer":"slow and steady wins the race","form":"원형","example":"My grandmother walks a little farther each day because slow and steady wins the race.","exampleTranslation":"천천히 꾸준히 하는 사람이 이기니까 할머니는 매일 조금씩 더 걸으신다.","sense":"천천히 꾸준히가 이긴다"},{"wordId":19839,"answer":"keep your eye on the ball","form":"원형","example":"Your exam is next week, so skip the games and keep your eye on the ball.","exampleTranslation":"다음 주가 시험이니 게임은 그만하고 목표에 집중해.","sense":"목표에 집중하다"},{"wordId":19840,"answer":"reap the rewards","form":"원형","example":"If you save a little every month, you will reap the rewards when you retire.","exampleTranslation":"매달 조금씩 저축하면 은퇴할 때 결실을 거둘 것이다.","sense":"결실을 거두다"},{"wordId":19841,"answer":"knock it out of the park","form":"원형","example":"The chef hopes to knock it out of the park with her new menu tonight.","exampleTranslation":"요리사는 오늘 밤 새 메뉴로 대성공을 거두기를 바란다.","sense":"대성공을 거두다"},{"wordId":19842,"answer":"nail it","form":"원형","example":"My daughter practiced her dance every day, and she will nail it on stage.","exampleTranslation":"딸은 매일 춤을 연습했으니 무대에서 완벽하게 해낼 것이다.","sense":"완벽하게 해내다"},{"wordId":19843,"answer":"jump at the chance","form":"원형","example":"If the coach asks me to play in the final, I will jump at the chance.","exampleTranslation":"코치가 결승에 뛰라고 하면 그 기회를 덥석 잡을 것이다.","sense":"기회를 덥석 잡다"},{"wordId":19844,"answer":"strike while the iron is hot","form":"원형","example":"The store has a big sale today, so we should strike while the iron is hot.","exampleTranslation":"오늘 가게에 큰 세일이 있으니 기회가 왔을 때 잡아야 해.","sense":"기회를 잡아라"},{"wordId":19845,"answer":"down on your luck","form":"원형","example":"If you are ever down on your luck, the food bank downtown can help you.","exampleTranslation":"형편이 어려워지면 시내 푸드 뱅크가 도와줄 수 있어요.","sense":"형편이 어려운"},{"wordId":19847,"answer":"easy come, easy go","form":"원형","example":"I spent the twenty dollars I found on candy, so easy come, easy go.","exampleTranslation":"주운 이십 달러를 사탕에 다 썼으니 쉽게 얻은 건 쉽게 잃는 법이다.","sense":"쉽게 얻고 쉽게 잃다"},{"wordId":19848,"answer":"the icing on the cake","form":"원형","example":"The food was great, and the live music was the icing on the cake.","exampleTranslation":"음식이 훌륭했고 라이브 음악은 금상첨화였다.","sense":"금상첨화"},{"wordId":19849,"answer":"a shot in the dark","form":"원형","example":"I had no idea where the restaurant was, so I took a shot in the dark.","exampleTranslation":"그 식당이 어디 있는지 전혀 몰라서 어림짐작으로 말했다.","sense":"어림짐작"},{"wordId":19850,"answer":"make the cut","form":"원형","example":"My brother practiced all summer and hopes to make the cut for the basketball team.","exampleTranslation":"오빠는 여름 내내 연습했고 농구팀에 선발되기를 바란다.","sense":"선발되다"},{"wordId":19851,"answer":"the honest truth","form":"원형","example":"The honest truth is that I forgot to mail the birthday card.","exampleTranslation":"거짓 없는 사실은 내가 생일 카드 보내는 걸 잊었다는 거야.","sense":"거짓 없는 사실"},{"wordId":19852,"answer":"a white lie","form":"원형","example":"My son told a white lie and said he loved his aunt's burnt cookies.","exampleTranslation":"아들은 고모가 태운 쿠키가 정말 맛있다고 선의의 거짓말을 했다.","sense":"선의의 거짓말"},{"wordId":19853,"answer":"stretch the truth","form":"원형","example":"Some online sellers stretch the truth about how new their products are.","exampleTranslation":"일부 온라인 판매자는 상품이 얼마나 새것인지 부풀려 말한다.","sense":"사실을 부풀리다"},{"wordId":19854,"answer":"hit the nail on the head","form":"원형","example":"My little sister hit the nail on the head when she said I needed a haircut.","exampleTranslation":"여동생이 내가 머리를 잘라야 한다고 말한 건 정곡을 찔렀다.","sense":"정곡을 찌르다"},{"wordId":19856,"answer":"have a way with words","form":"원형","example":"Good teachers have a way with words that makes hard topics easy to understand.","exampleTranslation":"좋은 선생님은 어려운 주제도 쉽게 이해시키는 말솜씨가 있다.","sense":"말솜씨가 좋다"},{"wordId":19857,"answer":"talk shop","form":"원형","example":"My parents both work at the hospital, so they talk shop during dinner.","exampleTranslation":"부모님 두 분 다 병원에서 일하셔서 저녁 식사 때 일 얘기를 하신다.","sense":"일 얘기를 하다"},{"wordId":19858,"answer":"the gift of gab","form":"원형","example":"The tour guide had the gift of gab and kept us laughing all day.","exampleTranslation":"관광 안내원은 말재주가 타고나서 하루 종일 우리를 웃게 했다.","sense":"타고난 말재주"},{"wordId":19859,"answer":"talk a mile a minute","form":"원형","example":"My grandmother can talk a mile a minute when she tells stories about her travels.","exampleTranslation":"할머니는 여행 이야기를 하실 때 속사포처럼 말씀하신다.","sense":"속사포처럼 말하다"},{"wordId":19860,"answer":"all talk and no action","form":"원형","example":"My brother says he will clean the garage, but he is all talk and no action.","exampleTranslation":"오빠는 차고를 치우겠다고 하지만 말만 하고 행동은 안 한다.","sense":"말만 하는"},{"wordId":19861,"answer":"actions speak louder than words","form":"원형","example":"My dad says sorry a lot, but actions speak louder than words.","exampleTranslation":"아빠는 미안하다는 말을 자주 하지만 말보다 행동이 중요하다.","sense":"말보다 행동"},{"wordId":19862,"answer":"you can say that again","form":"원형","example":"When I said the line was too long, my friend replied, \\"You can say that again.\\"","exampleTranslation":"내가 줄이 너무 길다고 하자 친구는 정말 그렇다고 맞장구쳤다.","sense":"정말 그래"},{"wordId":19863,"answer":"took the words right out of my mouth","form":"원형","example":"When my sister suggested ice cream, she took the words right out of my mouth.","exampleTranslation":"언니가 아이스크림을 먹자고 했을 때 내가 하려던 말을 그대로 했다.","sense":"내 말을 그대로 했다"},{"wordId":19864,"answer":"that makes two of us","form":"원형","example":"My coworker said he was starving before lunch, and I said, \\"That makes two of us.\\"","exampleTranslation":"점심 전에 동료가 배고파 죽겠다고 해서 나도 마찬가지라고 했다.","sense":"나도 마찬가지"},{"wordId":19865,"answer":"tongue in cheek","form":"원형","example":"My dad called our tiny car a limousine, but he said it tongue in cheek.","exampleTranslation":"아빠는 우리 작은 차를 리무진이라고 했지만 농담조로 한 말이었다.","sense":"농담조로"},{"wordId":19866,"answer":"bite my head off","form":"원형","example":"Please do not bite my head off, but you forgot to wash the dishes again.","exampleTranslation":"버럭 화내지 말고 들어 줘, 너 또 설거지 안 했어.","sense":"버럭 화내다"},{"wordId":19867,"answer":"the third degree","form":"원형","example":"My dad gave my sister's new boyfriend the third degree at dinner.","exampleTranslation":"아빠는 저녁 식사 때 언니의 새 남자친구에게 꼬치꼬치 캐물으셨다.","sense":"꼬치꼬치 캐묻기"},{"wordId":19868,"answer":"come clean","form":"원형","example":"My son finally decided to come clean about the broken vase.","exampleTranslation":"아들은 마침내 깨진 꽃병에 대해 사실대로 털어놓기로 했다.","sense":"사실대로 털어놓다"},{"wordId":19869,"answer":"the moment of truth","form":"원형","example":"We opened the envelope with the test results, and it was the moment of truth.","exampleTranslation":"시험 결과가 든 봉투를 열었고 결정적인 순간이었다.","sense":"결정적인 순간"},{"wordId":19870,"answer":"a slip of the tongue","form":"원형","example":"Calling my teacher mom was a slip of the tongue that made everyone laugh.","exampleTranslation":"선생님을 엄마라고 부른 건 모두를 웃게 한 말실수였다.","sense":"말실수"},{"wordId":19871,"answer":"train of thought","form":"원형","example":"The dog barked in the middle of my speech, and I lost my train of thought.","exampleTranslation":"연설 도중 개가 짖어서 생각의 흐름을 놓쳤다.","sense":"생각의 흐름"},{"wordId":19872,"answer":"food for thought","form":"원형","example":"The documentary about ocean trash gave the whole class food for thought.","exampleTranslation":"바다 쓰레기에 관한 다큐멘터리는 반 전체에게 생각할 거리를 줬다.","sense":"생각해 볼 거리"},{"wordId":19873,"answer":"my two cents","form":"원형","example":"Here is my two cents: the blue sofa will look better in your living room.","exampleTranslation":"내 짧은 의견을 말하자면 거실에는 파란 소파가 더 어울릴 거야.","sense":"내 짧은 의견"},{"wordId":19875,"answer":"a matter of opinion","form":"원형","example":"Which pizza topping is best is really a matter of opinion.","exampleTranslation":"어떤 피자 토핑이 최고인지는 정말 사람마다 다르다.","sense":"보기 나름인 문제"},{"wordId":19876,"answer":"stand your ground","form":"원형","example":"When a salesman keeps pushing, you need to stand your ground and say no.","exampleTranslation":"판매원이 계속 밀어붙이면 입장을 굽히지 말고 거절해야 한다.","sense":"입장을 굽히지 않다"},{"wordId":19877,"answer":"change your tune","form":"원형","example":"You hate camping now, but you will change your tune after one night by the lake.","exampleTranslation":"지금은 캠핑을 싫어하지만 호숫가에서 하룻밤 자면 태도가 싹 바뀔 거야.","sense":"태도를 싹 바꾸다"},{"wordId":19878,"answer":"eat your words","form":"원형","example":"If my team wins the game tonight, you will have to eat your words.","exampleTranslation":"오늘 밤 우리 팀이 이기면 너는 했던 말을 주워 담아야 할 거야.","sense":"했던 말을 주워 담다"},{"wordId":19879,"answer":"say no more","form":"원형","example":"When my sister asked me to babysit, I said, \\"Say no more,\\" and drove over.","exampleTranslation":"언니가 아이를 봐 달라고 하자 나는 더 말 안 해도 된다며 차를 몰고 건너갔다.","sense":"더 말 안 해도 알겠어"},{"wordId":19880,"answer":"word for word","form":"원형","example":"The students had to copy the poem word for word into their notebooks.","exampleTranslation":"학생들은 그 시를 공책에 한 글자도 틀리지 않고 베껴야 했다.","sense":"그대로"},{"wordId":19881,"answer":"the bottom line","form":"원형","example":"The bottom line is that the kids need more sleep on school nights.","exampleTranslation":"핵심은 아이들이 학교 가기 전날 밤에 잠을 더 자야 한다는 것이다.","sense":"핵심"},{"wordId":19882,"answer":"get the wrong idea","form":"원형","example":"I hope my coworker does not get the wrong idea about the flowers.","exampleTranslation":"동료가 꽃을 두고 오해하지 않았으면 좋겠다.","sense":"오해하다"},{"wordId":19883,"answer":"let the cat out of the bag","form":"원형","example":"My little brother will probably let the cat out of the bag about the gift.","exampleTranslation":"남동생이 아마 선물에 대한 비밀을 누설할 것이다.","sense":"비밀을 누설하다"},{"wordId":19884,"answer":"a straight answer","form":"원형","example":"The landlord never gives a straight answer about when he will fix the heater.","exampleTranslation":"집주인은 히터를 언제 고칠지 절대 솔직하게 대답하지 않는다.","sense":"솔직한 대답"},{"wordId":19885,"answer":"lie through your teeth","form":"원형","example":"Do not lie through your teeth, because I saw the candy wrappers in your room.","exampleTranslation":"뻔뻔하게 거짓말하지 마, 네 방에서 사탕 껍질 봤어.","sense":"뻔뻔하게 거짓말하다"},{"wordId":19886,"answer":"call a spade a spade","form":"원형","example":"My grandmother likes to call a spade a spade when she judges our cooking.","exampleTranslation":"할머니는 우리 요리를 평가할 때 있는 그대로 직설적으로 말씀하신다.","sense":"직설적으로 말하다"},{"wordId":19887,"answer":"out of line","form":"원형","example":"The teacher said the student's rude joke in class was out of line.","exampleTranslation":"선생님은 그 학생이 수업 중에 한 무례한 농담이 선을 넘었다고 했다.","sense":"선을 넘은"},{"wordId":19888,"answer":"talk in circles","form":"원형","example":"My parents talk in circles when they try to decide where to eat.","exampleTranslation":"부모님은 어디서 먹을지 정하려 할 때 같은 얘기만 맴도신다.","sense":"말을 빙빙 돌리다"},{"wordId":19889,"answer":"strike a chord","form":"원형","example":"The old song on the radio seemed to strike a chord with my grandfather.","exampleTranslation":"라디오에서 나온 옛 노래가 할아버지의 마음에 와닿은 것 같았다.","sense":"공감을 일으키다"},{"wordId":19890,"answer":"a sore subject","form":"원형","example":"My brother failed his driving test twice, so it is a sore subject at home.","exampleTranslation":"오빠가 운전면허 시험에 두 번 떨어져서 집에서는 민감한 화제다.","sense":"민감한 화제"},{"wordId":19891,"answer":"put words in my mouth","form":"원형","example":"I only said the soup was salty, so do not put words in my mouth.","exampleTranslation":"나는 수프가 짜다고만 했으니 내가 하지도 않은 말을 했다고 하지 마.","sense":"없는 말을 했다고 하다"},{"wordId":19892,"answer":"famous last words","form":"원형","example":"My brother said he would never get lost here, and those were famous last words.","exampleTranslation":"오빠는 여기서 절대 길을 잃지 않을 거라고 했는데 그 장담은 보기 좋게 빗나갔다.","sense":"장담한 마지막 말"},{"wordId":19893,"answer":"speak volumes","form":"원형","example":"The empty seats at the meeting seem to speak volumes about the new plan.","exampleTranslation":"회의의 빈자리들이 새 계획에 대해 많은 것을 말해 주는 것 같다.","sense":"많은 것을 말해 주다"},{"wordId":19894,"answer":"sugarcoats","form":"3인칭 단수형","example":"Our coach never sugarcoats the truth after a bad game.","exampleTranslation":"우리 코치는 경기를 망친 뒤에 절대 진실을 듣기 좋게 포장하지 않는다.","sense":"듣기 좋게 포장하다"},{"wordId":19895,"answer":"hear me out","form":"원형","example":"Mom, please hear me out before you say no to the camping trip.","exampleTranslation":"엄마, 캠핑 여행을 반대하시기 전에 내 말 끝까지 들어 주세요.","sense":"내 말 끝까지 들어 봐"},{"wordId":19896,"answer":"talk is cheap","form":"원형","example":"Everyone says they will help with the move, but talk is cheap.","exampleTranslation":"다들 이사를 돕겠다고 하지만 말로는 뭘 못 하겠어.","sense":"말로는 뭘 못 해"},{"wordId":19897,"answer":"the naked truth","form":"원형","example":"The naked truth is that our old car will not make it through winter.","exampleTranslation":"적나라한 진실은 우리 낡은 차가 이번 겨울을 못 넘길 거라는 거야.","sense":"적나라한 진실"},{"wordId":19898,"answer":"short and sweet","form":"원형","example":"The principal kept her speech at graduation short and sweet.","exampleTranslation":"교장 선생님은 졸업식 연설을 짧고 간결하게 하셨다.","sense":"짧고 간결하게"},{"wordId":19899,"answer":"for the record","form":"원형","example":"For the record, my brother was the one who ate the last cookie.","exampleTranslation":"분명히 말해 두는데 마지막 쿠키를 먹은 건 오빠야.","sense":"분명히 말해 두자면"},{"wordId":19900,"answer":"a broken record","form":"원형","example":"My mom says she sounds like a broken record about turning off the lights.","exampleTranslation":"엄마는 불을 끄라는 말을 하도 해서 같은 말만 되풀이하는 것 같다고 하신다.","sense":"같은 말 반복하는 사람"},{"wordId":19901,"answer":"bite the hand that feeds you","form":"원형","example":"Do not bite the hand that feeds you by complaining about your boss online.","exampleTranslation":"온라인에서 상사 욕을 해서 은혜를 원수로 갚지 마라.","sense":"은혜를 원수로 갚다"},{"wordId":19902,"answer":"raining cats and dogs","form":"원형","example":"We canceled our picnic because it was raining cats and dogs all morning.","exampleTranslation":"아침 내내 비가 억수같이 쏟아져서 소풍을 취소했다.","sense":"비가 억수같이 오는"},{"wordId":19903,"answer":"hold your horses","form":"원형","example":"Hold your horses, kids, because we will open the gifts after dinner.","exampleTranslation":"얘들아, 서두르지 마. 선물은 저녁 먹고 열 거야.","sense":"서두르지 마"},{"wordId":19904,"answer":"crocodile tears","form":"원형","example":"My little brother cried crocodile tears so mom would buy him a toy.","exampleTranslation":"남동생은 엄마가 장난감을 사 주게 하려고 거짓 눈물을 흘렸다.","sense":"거짓 눈물"},{"wordId":19905,"answer":"eat like a horse","form":"원형","example":"My teenage son can eat like a horse at every family barbecue.","exampleTranslation":"십 대 아들은 가족 바비큐 때마다 엄청나게 먹는다.","sense":"엄청나게 많이 먹다"},{"wordId":19906,"answer":"a little bird told me","form":"원형","example":"A little bird told me that you are moving to a new apartment.","exampleTranslation":"누가 그러던데 너 새 아파트로 이사 간다며.","sense":"누가 그러던데"},{"wordId":19907,"answer":"a fish out of water","form":"원형","example":"At the fancy restaurant, my dad in old jeans looked like a fish out of water.","exampleTranslation":"고급 식당에서 낡은 청바지 차림의 아빠는 물 밖에 나온 물고기 같았다.","sense":"낯선 곳의 어색한 사람"},{"wordId":19908,"answer":"something fishy","form":"원형","example":"My mom noticed something fishy about the email asking for her bank details.","exampleTranslation":"엄마는 은행 정보를 묻는 이메일에서 뭔가 수상한 점을 알아챘다.","sense":"뭔가 수상한 것"},{"wordId":19909,"answer":"smell a rat","form":"원형","example":"When the cheap phone online had no reviews, I began to smell a rat.","exampleTranslation":"온라인의 싼 휴대폰에 후기가 하나도 없자 뭔가 수상하다고 느꼈다.","sense":"수상하다고 느끼다"},{"wordId":19911,"answer":"sick as a dog","form":"원형","example":"My brother caught the flu and was sick as a dog for a whole week.","exampleTranslation":"오빠는 독감에 걸려서 일주일 내내 몹시 아팠다.","sense":"몹시 아픈"},{"wordId":19912,"answer":"dog-tired","form":"원형","example":"After a full day at the amusement park, the whole family was dog-tired.","exampleTranslation":"놀이공원에서 하루를 꼬박 보낸 뒤 온 가족이 녹초가 됐다.","sense":"녹초가 된"},{"wordId":19913,"answer":"in the doghouse","form":"원형","example":"My son broke the lamp with his ball, so he is in the doghouse tonight.","exampleTranslation":"아들이 공으로 전등을 깨서 오늘 밤 미운털이 박혔다.","sense":"미운털 박힌"},{"wordId":19914,"answer":"the black sheep","form":"원형","example":"My cousin felt like the black sheep because he chose art instead of medicine.","exampleTranslation":"사촌은 의학 대신 미술을 택해서 집안의 이단아가 된 기분이었다.","sense":"이단아"},{"wordId":19915,"answer":"a wild goose chase","form":"원형","example":"Looking for that old bookstore without a map was a wild goose chase.","exampleTranslation":"지도 없이 그 오래된 서점을 찾는 건 헛수고였다.","sense":"헛수고"},{"wordId":19917,"answer":"take the bull by the horns","form":"원형","example":"Afraid of speaking in public, my sister chose to take the bull by the horns.","exampleTranslation":"사람들 앞에서 말하기가 두려웠던 언니는 정면으로 맞서기로 했다.","sense":"정면으로 맞서다"},{"wordId":19918,"answer":"when pigs fly","form":"원형","example":"My brother says he will wake up early on Saturday. Sure, when pigs fly.","exampleTranslation":"오빠는 토요일에 일찍 일어나겠다고 한다. 그래, 해가 서쪽에서 뜨면.","sense":"절대 그럴 리 없음"},{"wordId":19919,"answer":"make a beeline for","form":"원형","example":"At every wedding, my uncle tends to make a beeline for the dessert table.","exampleTranslation":"결혼식마다 삼촌은 곧장 디저트 테이블로 향하곤 한다.","sense":"곧장 향하다"},{"wordId":19920,"answer":"cat nap","form":"원형","example":"Our old cat takes a cat nap on the warm windowsill every afternoon.","exampleTranslation":"우리 늙은 고양이는 매일 오후 따뜻한 창턱에서 토막잠을 잔다.","sense":"토막잠"},{"wordId":19921,"answer":"a sight for sore eyes","form":"원형","example":"After a long day of hiking, the little cabin was a sight for sore eyes.","exampleTranslation":"하루 종일 등산한 뒤라 그 작은 오두막은 보기만 해도 반가웠다.","sense":"보기만 해도 반가운"},{"wordId":19922,"answer":"eat like a bird","form":"원형","example":"Before a big game, my brother gets nervous and starts to eat like a bird.","exampleTranslation":"큰 경기 전이면 오빠는 긴장해서 아주 조금만 먹는다.","sense":"아주 적게 먹다"},{"wordId":19923,"answer":"all ears","form":"원형","example":"When grandpa starts talking about his trip to Japan, the kids are all ears.","exampleTranslation":"할아버지가 일본 여행 이야기를 시작하시면 아이들이 귀를 쫑긋 세운다.","sense":"잘 듣고 있는"},{"wordId":19924,"answer":"monkey business","form":"원형","example":"The teacher left the room and told the students there would be no monkey business.","exampleTranslation":"선생님은 교실을 나가며 학생들에게 허튼짓하지 말라고 했다.","sense":"허튼짓"},{"wordId":19925,"answer":"all thumbs","form":"원형","example":"My husband is all thumbs in the kitchen, so I do the cooking.","exampleTranslation":"남편은 부엌에서 영 서툴러서 요리는 내가 한다.","sense":"서투른"},{"wordId":19926,"answer":"neck and neck","form":"원형","example":"The two runners were neck and neck as they reached the finish line.","exampleTranslation":"두 선수는 결승선에 다다를 때까지 막상막하였다.","sense":"막상막하인"},{"wordId":19927,"answer":"over my head","form":"원형","example":"My son's math homework is already way over my head.","exampleTranslation":"아들의 수학 숙제는 벌써 내 수준을 훨씬 넘는다.","sense":"이해하기 어려운"},{"wordId":19928,"answer":"stick your neck out","form":"원형","example":"It takes courage to stick your neck out for a new coworker.","exampleTranslation":"새 동료를 위해 위험을 무릅쓰고 나서는 건 용기가 필요하다.","sense":"위험을 무릅쓰다"},{"wordId":19929,"answer":"on the tip of my tongue","form":"원형","example":"The name of that song is on the tip of my tongue right now.","exampleTranslation":"그 노래 제목이 지금 혀끝에서 맴돈다.","sense":"혀끝에서 맴도는"},{"wordId":19930,"answer":"twist my arm","form":"원형","example":"Nobody had to twist my arm to get me to join the beach trip.","exampleTranslation":"아무도 조르지 않았는데 나는 바닷가 여행에 기꺼이 따라갔다.","sense":"억지로 시키다"},{"wordId":19931,"answer":"put your foot down","form":"원형","example":"As a parent, you sometimes need to put your foot down about screen time.","exampleTranslation":"부모라면 때로는 화면 보는 시간에 대해 단호하게 나가야 한다.","sense":"단호하게 나가다"},{"wordId":19932,"answer":"put your feet up","form":"원형","example":"After the long drive, you should take off your shoes and put your feet up.","exampleTranslation":"오래 운전했으니 신발 벗고 편히 쉬어.","sense":"편히 쉬다"},{"wordId":19933,"answer":"gut feeling","form":"원형","example":"My mom had a gut feeling that it would rain, so she packed umbrellas.","exampleTranslation":"엄마는 비가 올 거라는 직감이 들어서 우산을 챙기셨다.","sense":"직감"},{"wordId":19934,"answer":"have your cake and eat it too","form":"원형","example":"Sleep late or catch the early train; you cannot have your cake and eat it too.","exampleTranslation":"늦잠을 자든지 첫 기차를 타든지 해, 두 마리 토끼를 다 잡을 순 없어.","sense":"두 마리 토끼를 잡다"},{"wordId":19935,"answer":"a change of heart","form":"원형","example":"My dad had a change of heart and let us get a puppy.","exampleTranslation":"아빠는 마음이 바뀌어서 강아지를 키우게 해 주셨다.","sense":"마음이 바뀜"},{"wordId":19936,"answer":"cry over spilled milk","form":"원형","example":"The vase is already broken, so do not cry over spilled milk now.","exampleTranslation":"꽃병은 이미 깨졌으니 이제 와서 한탄하지 마.","sense":"엎질러진 일 한탄하다"},{"wordId":19937,"answer":"the apple of my eye","form":"원형","example":"My little dog Max has been the apple of my eye for ten years.","exampleTranslation":"내 작은 개 맥스는 십 년 동안 눈에 넣어도 안 아픈 존재였다.","sense":"눈에 넣어도 안 아픈 사람"},{"wordId":19938,"answer":"bread and butter","form":"원형","example":"For our family farm, selling eggs at the market is our bread and butter.","exampleTranslation":"우리 가족 농장에서는 시장에 달걀을 파는 게 주 수입원이다.","sense":"주 수입원"},{"wordId":19939,"answer":"the best thing since sliced bread","form":"원형","example":"My grandmother thinks her new robot vacuum is the best thing since sliced bread.","exampleTranslation":"할머니는 새 로봇 청소기가 최고의 발명품이라고 생각하신다.","sense":"굉장히 좋은 것"},{"wordId":19940,"answer":"as cool as a cucumber","form":"원형","example":"When the power went out, our teacher stayed as cool as a cucumber.","exampleTranslation":"정전이 됐을 때 선생님은 아주 침착하셨다.","sense":"아주 침착한"},{"wordId":19941,"answer":"go bananas","form":"원형","example":"My daughter will go bananas when she sees the snow tomorrow morning.","exampleTranslation":"딸은 내일 아침 눈을 보면 신나서 펄쩍 뛸 것이다.","sense":"몹시 흥분하다"},{"wordId":19942,"answer":"egg on your face","form":"원형","example":"If you promise a perfect score and then fail, you will have egg on your face.","exampleTranslation":"만점을 장담했다가 떨어지면 망신을 당할 거야.","sense":"망신"},{"wordId":19943,"answer":"put all your eggs in one basket","form":"원형","example":"When you save for the future, do not put all your eggs in one basket.","exampleTranslation":"미래를 위해 저축할 때는 한 곳에 모든 걸 걸지 마.","sense":"한 곳에 다 걸다"},{"wordId":19944,"answer":"sell like hotcakes","form":"원형","example":"In summer, the cold drinks at the beach stand sell like hotcakes.","exampleTranslation":"여름이면 해변 가판대의 시원한 음료가 불티나게 팔린다.","sense":"불티나게 팔리다"},{"wordId":19945,"answer":"a hot potato","form":"원형","example":"The question of who pays for the party became a hot potato in our family.","exampleTranslation":"파티 비용을 누가 낼지가 우리 집에서 뜨거운 감자가 됐다.","sense":"뜨거운 감자"},{"wordId":19946,"answer":"skin and bones","form":"원형","example":"The stray dog we found was skin and bones, so we fed him right away.","exampleTranslation":"우리가 발견한 떠돌이 개는 피골이 상접해서 바로 먹이를 줬다.","sense":"피골이 상접한"},{"wordId":19948,"answer":"apples and oranges","form":"원형","example":"Comparing a bike and a car is like comparing apples and oranges.","exampleTranslation":"자전거와 차를 비교하는 건 전혀 다른 것을 비교하는 셈이다.","sense":"비교 불가한 것"},{"wordId":19949,"answer":"half-baked","form":"원형","example":"My brother had a half-baked idea to sell lemonade in the middle of winter.","exampleTranslation":"오빠는 한겨울에 레모네이드를 팔겠다는 어설픈 생각을 했다.","sense":"설익은"},{"wordId":19950,"answer":"pat yourself on the back","form":"원형","example":"You finished your first marathon, so take a moment to pat yourself on the back.","exampleTranslation":"첫 마라톤을 완주했으니 잠시 스스로를 칭찬해 줘.","sense":"스스로를 칭찬하다"},{"wordId":19951,"answer":"cold turkey","form":"원형","example":"My dad stopped drinking coffee cold turkey last month and felt tired for days.","exampleTranslation":"아빠는 지난달 커피를 단번에 끊었고 며칠 동안 피곤해하셨다.","sense":"단번에 끊고"},{"wordId":19952,"answer":"turn over a new leaf","form":"원형","example":"After failing math, my son promised to turn over a new leaf this semester.","exampleTranslation":"수학에서 낙제한 뒤 아들은 이번 학기에 새사람이 되겠다고 약속했다.","sense":"새사람이 되다"},{"wordId":19953,"answer":"a turning point","form":"원형","example":"Joining the soccer team was a turning point for my shy son.","exampleTranslation":"축구팀에 들어간 것은 수줍은 아들에게 전환점이 되었다.","sense":"전환점"},{"wordId":19954,"answer":"a game changer","form":"원형","example":"Online classes were a game changer for students who live far from school.","exampleTranslation":"온라인 수업은 학교에서 먼 곳에 사는 학생들에게 판도를 바꾸는 일이었다.","sense":"판도를 바꾸는 것"},{"wordId":19955,"answer":"go back and forth","form":"원형","example":"My parents go back and forth about whether to paint the house blue or white.","exampleTranslation":"부모님은 집을 파란색으로 칠할지 흰색으로 칠할지 이랬다저랬다 하신다.","sense":"오락가락하다"},{"wordId":19956,"answer":"think twice","form":"원형","example":"Next time, you should think twice before eating gas station sushi.","exampleTranslation":"다음엔 주유소 초밥을 먹기 전에 신중히 다시 생각해 봐.","sense":"다시 생각하다"},{"wordId":19957,"answer":"second-guess","form":"원형","example":"New drivers often second-guess every turn when they drive in a big city.","exampleTranslation":"초보 운전자들은 대도시에서 운전할 때 꺾을 때마다 자꾸 자기 판단을 의심한다.","sense":"자꾸 의심하다"},{"wordId":19958,"answer":"have second thoughts","form":"원형","example":"Many students have second thoughts about their major after the first year.","exampleTranslation":"많은 학생이 일 학년이 끝나면 전공에 대해 망설이게 된다.","sense":"다시 망설이다"},{"wordId":19959,"answer":"torn between","form":"원형","example":"My daughter is torn between the piano lessons and the swimming team.","exampleTranslation":"딸은 피아노 수업과 수영팀 사이에서 갈등하고 있다.","sense":"사이에서 갈등하는"},{"wordId":19960,"answer":"a leap of faith","form":"원형","example":"Adopting a dog from the shelter felt like a leap of faith for us.","exampleTranslation":"보호소에서 개를 입양하는 건 우리에게 과감한 결단 같았다.","sense":"과감한 결단"},{"wordId":19961,"answer":"go out on a limb","form":"원형","example":"I will go out on a limb and say our team will win the cup.","exampleTranslation":"과감히 말하자면 우리 팀이 우승할 거야.","sense":"모험을 감수하다"},{"wordId":19962,"answer":"take a step back","form":"원형","example":"When the kids argue, I ask them to take a step back and breathe.","exampleTranslation":"아이들이 다투면 한발 물러서서 숨을 고르라고 한다.","sense":"한발 물러서다"},{"wordId":19963,"answer":"on a whim","form":"원형","example":"My grandmother bought a bright red coat on a whim at the mall.","exampleTranslation":"할머니는 쇼핑몰에서 충동적으로 새빨간 코트를 사셨다.","sense":"충동적으로"},{"wordId":19964,"answer":"now or never","form":"원형","example":"The concert tickets go on sale at noon, and it is now or never.","exampleTranslation":"공연 표가 정오에 판매를 시작하니 지금 아니면 기회가 없다.","sense":"지금 아니면 끝"},{"wordId":19965,"answer":"the point of no return","form":"원형","example":"Halfway across the lake in our small boat, we passed the point of no return.","exampleTranslation":"작은 배로 호수를 절반쯤 건넜을 때 우리는 돌이킬 수 없는 지점을 지났다.","sense":"돌이킬 수 없는 지점"},{"wordId":19967,"answer":"a new lease on life","form":"원형","example":"Moving to the countryside gave my parents a new lease on life.","exampleTranslation":"시골로 이사한 것은 부모님께 새 활력을 주었다.","sense":"새 활력"},{"wordId":19968,"answer":"shake things up","form":"원형","example":"Our teacher moved all the desks into a circle to shake things up.","exampleTranslation":"선생님은 분위기를 바꾸려고 책상을 모두 원형으로 옮기셨다.","sense":"분위기를 바꾸다"},{"wordId":19969,"answer":"a change of pace","form":"원형","example":"For a change of pace, I took the train to work instead of driving.","exampleTranslation":"기분 전환 삼아 운전 대신 기차로 출근했다.","sense":"기분 전환"},{"wordId":19970,"answer":"the new normal","form":"원형","example":"Paying with a phone instead of cash is the new normal in many cities.","exampleTranslation":"현금 대신 휴대폰으로 결제하는 것이 많은 도시에서 새로운 일상이다.","sense":"새로운 일상"},{"wordId":19971,"answer":"the tables have turned","form":"원형","example":"My son used to lose at chess, but the tables have turned and now he wins.","exampleTranslation":"아들은 체스에서 지곤 했지만 형세가 역전돼서 이제는 이긴다.","sense":"형세가 역전되다"},{"wordId":19972,"answer":"a whole new ball game","form":"원형","example":"Raising twins is a whole new ball game after having just one child.","exampleTranslation":"아이 하나만 키우다가 쌍둥이를 키우는 건 완전히 다른 상황이다.","sense":"완전히 다른 상황"},{"wordId":19973,"answer":"a different story","form":"원형","example":"Riding a bike is easy, but riding a horse is a different story.","exampleTranslation":"자전거 타기는 쉽지만 말 타기는 전혀 다른 이야기다.","sense":"전혀 다른 이야기"},{"wordId":19974,"answer":"back to normal","form":"원형","example":"After the long holiday, the school schedule is finally back to normal.","exampleTranslation":"긴 연휴가 끝나고 학교 일정이 마침내 평소대로 돌아왔다.","sense":"정상으로 돌아온"},{"wordId":19975,"answer":"when push comes to shove","form":"원형","example":"My brother complains a lot, but when push comes to shove, he always helps.","exampleTranslation":"오빠는 불평이 많지만 정말 필요할 때는 늘 도와준다.","sense":"정말 필요할 때"},{"wordId":19976,"answer":"the writing on the wall","form":"원형","example":"When the store stopped ordering new stock, the workers saw the writing on the wall.","exampleTranslation":"가게가 새 물건 주문을 멈추자 직원들은 불길한 징조를 알아챘다.","sense":"불길한 징조"},{"wordId":19977,"answer":"a step in the right direction","form":"원형","example":"Eating breakfast every day is a step in the right direction for your health.","exampleTranslation":"매일 아침을 먹는 것은 건강을 위한 올바른 한 걸음이다.","sense":"올바른 방향의 한 걸음"},{"wordId":19978,"answer":"go with your gut","form":"원형","example":"When you pick a new apartment, sometimes you just have to go with your gut.","exampleTranslation":"새 아파트를 고를 때는 가끔 그냥 직감을 따라야 한다.","sense":"직감을 따르다"},{"wordId":19979,"answer":"call it quits","form":"원형","example":"It was getting dark, so the hikers decided to call it quits and head home.","exampleTranslation":"어두워지고 있어서 등산객들은 그만하고 집에 가기로 했다.","sense":"그만두다"},{"wordId":19980,"answer":"a toss-up","form":"원형","example":"Who will win the cooking contest this year is a toss-up.","exampleTranslation":"올해 요리 대회에서 누가 이길지는 반반이다.","sense":"반반인 상황"},{"wordId":19981,"answer":"flip a coin","form":"원형","example":"The two captains will flip a coin to decide which team kicks first.","exampleTranslation":"두 주장이 동전을 던져 어느 팀이 먼저 찰지 정할 것이다.","sense":"동전을 던져 정하다"},{"wordId":19982,"answer":"the best of both worlds","form":"원형","example":"Working from a cafe by the park gives me the best of both worlds.","exampleTranslation":"공원 옆 카페에서 일하면 두 가지 장점을 다 누린다.","sense":"양쪽 장점을 다 누림"},{"wordId":19983,"answer":"have it both ways","form":"원형","example":"My son wants a dog but no chores, and he cannot have it both ways.","exampleTranslation":"아들은 개는 원하면서 집안일은 싫다는데 둘 다 가질 순 없다.","sense":"두 가지를 다 취하다"},{"wordId":19984,"answer":"a fresh start","form":"원형","example":"The new school year felt like a fresh start for my daughter.","exampleTranslation":"새 학년은 딸에게 새 출발처럼 느껴졌다.","sense":"새 출발"},{"wordId":19985,"answer":"start from scratch","form":"원형","example":"The cake fell on the floor, so the baker had to start from scratch.","exampleTranslation":"케이크가 바닥에 떨어져서 제빵사는 처음부터 다시 시작해야 했다.","sense":"처음부터 다시 하다"},{"wordId":19986,"answer":"stick to your guns","form":"원형","example":"Your plan is good, so stick to your guns even if your boss disagrees.","exampleTranslation":"네 계획은 좋으니 상사가 반대해도 소신을 굽히지 마.","sense":"소신을 굽히지 않다"},{"wordId":19987,"answer":"wipe the slate clean","form":"원형","example":"The teacher let the class wipe the slate clean after the bad first week.","exampleTranslation":"선생님은 첫 주를 망친 반에게 과거를 잊고 새로 시작하게 해 주셨다.","sense":"새로 시작하다"},{"wordId":19988,"answer":"the calm before the storm","form":"원형","example":"The quiet morning before the shoppers arrived was the calm before the storm.","exampleTranslation":"손님들이 몰려오기 전 조용한 아침은 폭풍 전의 고요였다.","sense":"폭풍 전의 고요"},{"wordId":19989,"answer":"make the best of it","form":"원형","example":"Our campsite flooded, but the kids decided to make the best of it.","exampleTranslation":"캠핑장이 물에 잠겼지만 아이들은 그 상황에서 최선을 다하기로 했다.","sense":"최선을 다하다"},{"wordId":19990,"answer":"roll with the punches","form":"원형","example":"Parents of young kids learn to roll with the punches every single day.","exampleTranslation":"어린아이를 둔 부모는 매일 역경에 유연하게 대처하는 법을 배운다.","sense":"유연하게 대처하다"},{"wordId":19991,"answer":"come full circle","form":"원형","example":"My mom taught at the school where she studied, so she has come full circle.","exampleTranslation":"엄마는 자신이 다녔던 학교에서 가르치셨으니 한 바퀴 돌아 제자리로 오신 셈이다.","sense":"처음으로 돌아오다"},{"wordId":19992,"answer":"rock the boat","form":"원형","example":"My brother did not want to rock the boat at the family dinner.","exampleTranslation":"오빠는 가족 저녁 식사 자리에서 분란을 일으키고 싶지 않았다.","sense":"분란을 일으키다"},{"wordId":19993,"answer":"a done deal","form":"원형","example":"The school trip to the museum is a done deal, and the bus is booked.","exampleTranslation":"박물관 견학은 확정됐고 버스도 예약됐다.","sense":"확정된 일"},{"wordId":19994,"answer":"set in stone","form":"원형","example":"The menu for the wedding is not set in stone yet.","exampleTranslation":"결혼식 메뉴는 아직 확정되지 않았다.","sense":"확정된"},{"wordId":19995,"answer":"take it or leave it","form":"원형","example":"The seller said fifty dollars off was his final offer, take it or leave it.","exampleTranslation":"판매자는 오십 달러 깎은 게 마지막 제안이니 받든지 말든지 하라고 했다.","sense":"받든지 말든지"},{"wordId":19996,"answer":"a matter of time","form":"원형","example":"He drives so fast that a speeding ticket is only a matter of time.","exampleTranslation":"그는 운전을 너무 빨리 해서 과속 딱지를 받는 건 시간문제다.","sense":"시간문제"},{"wordId":19997,"answer":"all bets are off","form":"원형","example":"If the star player gets hurt before the final, all bets are off.","exampleTranslation":"결승 전에 스타 선수가 다치면 어떻게 될지 모른다.","sense":"어떻게 될지 모른다"},{"wordId":19998,"answer":"if worst comes to worst","form":"원형","example":"If worst comes to worst, we can take a taxi to the stadium.","exampleTranslation":"최악의 경우에는 경기장까지 택시를 타면 된다.","sense":"최악의 경우"},{"wordId":19999,"answer":"a fork in the road","form":"원형","example":"My sister reached a fork in the road when two colleges accepted her.","exampleTranslation":"언니는 두 대학에 합격하면서 인생의 갈림길에 섰다.","sense":"갈림길"},{"wordId":20000,"answer":"jump ship","form":"원형","example":"Several players may jump ship if the team does not get a new coach.","exampleTranslation":"팀이 새 코치를 구하지 못하면 몇몇 선수가 떠날지도 모른다.","sense":"버리고 떠나다"},{"wordId":20001,"answer":"oat milk","form":"원형","example":"My sister cannot drink dairy, so she always buys oat milk at the store.","exampleTranslation":"여동생은 유제품을 못 마셔서 가게에서 항상 귀리 우유를 산다.","sense":"귀리 우유"},{"wordId":20002,"answer":"baristas","form":"복수형","example":"The baristas at this shop remember the names of all their regular customers.","exampleTranslation":"이 가게의 바리스타들은 단골손님들의 이름을 모두 기억한다.","sense":"바리스타"},{"wordId":20003,"answer":"lattes","form":"복수형","example":"My coworker brought two lattes to the meeting, one for me and one for her.","exampleTranslation":"동료가 회의에 라테 두 잔을 가져왔는데, 하나는 내 것이고 하나는 그녀 것이었다.","sense":"라테"},{"wordId":20004,"answer":"cappuccinos","form":"복수형","example":"We ordered three cappuccinos and sat by the window to chat for an hour.","exampleTranslation":"우리는 카푸치노 세 잔을 주문하고 창가에 앉아 한 시간 동안 이야기했다.","sense":"카푸치노"},{"wordId":20005,"answer":"espressos","form":"복수형","example":"After two espressos, my brother could not stop talking during the whole drive.","exampleTranslation":"에스프레소 두 잔을 마신 뒤 형은 운전하는 내내 말을 멈추지 못했다.","sense":"에스프레소"},{"wordId":20006,"answer":"americanos","form":"복수형","example":"Our team ordered ten americanos for the early morning training session.","exampleTranslation":"우리 팀은 이른 아침 교육 시간을 위해 아메리카노 열 잔을 주문했다.","sense":"아메리카노"},{"wordId":20007,"answer":"decaf","form":"원형","example":"My doctor told me to drink decaf because regular coffee makes my heart race.","exampleTranslation":"의사는 일반 커피가 심장을 빨리 뛰게 하니 디카페인 커피를 마시라고 했다.","sense":"디카페인 커피"},{"wordId":20008,"answer":"cold brew","form":"원형","example":"On hot summer days, I keep a big jar of cold brew in the fridge.","exampleTranslation":"더운 여름날에는 냉장고에 콜드브루 커피를 큰 병으로 넣어 둔다.","sense":"콜드브루"},{"wordId":20009,"answer":"drip coffee","form":"원형","example":"The hotel lobby offers free drip coffee to guests every morning until ten.","exampleTranslation":"호텔 로비에서는 매일 아침 열 시까지 손님들에게 드립 커피를 무료로 준다.","sense":"드립 커피"},{"wordId":20010,"answer":"extra shot","form":"원형","example":"I was so tired after the night shift that I asked for an extra shot.","exampleTranslation":"야간 근무 후 너무 피곤해서 샷 추가를 부탁했다.","sense":"샷 추가"},{"wordId":20011,"answer":"whipped cream","form":"원형","example":"My grandmother always puts whipped cream on the strawberry pie she bakes for us.","exampleTranslation":"할머니는 우리에게 구워 주시는 딸기 파이에 항상 휘핑크림을 올리신다.","sense":"휘핑크림"},{"wordId":20012,"answer":"to go","form":"원형","example":"We are running late, so can we get two sandwiches to go?","exampleTranslation":"우리가 늦어서 그러는데 샌드위치 두 개를 포장해 갈 수 있을까요?","sense":"포장해서"},{"wordId":20013,"answer":"for here","form":"원형","example":"Two iced teas for here, please, and we will sit on the patio.","exampleTranslation":"아이스티 두 잔 매장에서 마실게요, 테라스에 앉을 거예요.","sense":"매장에서"},{"wordId":20014,"answer":"reusable cup","form":"원형","example":"I keep a reusable cup in my backpack so I never need a paper one.","exampleTranslation":"종이컵이 필요 없도록 가방에 다회용 컵을 넣고 다닌다.","sense":"다회용 컵"},{"wordId":20015,"answer":"cup sleeve","form":"원형","example":"The barista forgot the cup sleeve, so I wrapped a napkin around my drink.","exampleTranslation":"바리스타가 컵 홀더를 빠뜨려서 음료에 냅킨을 감쌌다.","sense":"컵 홀더"},{"wordId":20016,"answer":"pastries","form":"복수형","example":"My aunt brought a box of pastries to the office for everyone to share.","exampleTranslation":"이모가 모두 나눠 먹으라고 사무실에 페이스트리 한 상자를 가져왔다.","sense":"페이스트리"},{"wordId":20017,"answer":"croissants","form":"복수형","example":"The hotel breakfast had warm croissants, fresh fruit, and several kinds of cheese.","exampleTranslation":"호텔 조식에는 따뜻한 크루아상과 신선한 과일, 여러 종류의 치즈가 있었다.","sense":"크루아상"},{"wordId":20018,"answer":"muffins","form":"복수형","example":"My son and I baked banana muffins for his class party on Friday.","exampleTranslation":"아들과 나는 금요일 학급 파티를 위해 바나나 머핀을 구웠다.","sense":"머핀"},{"wordId":20019,"answer":"bagels","form":"복수형","example":"We picked up a dozen bagels for the team breakfast before the big meeting.","exampleTranslation":"우리는 중요한 회의 전에 팀 아침 식사로 베이글 열두 개를 사 왔다.","sense":"베이글"},{"wordId":20020,"answer":"scones","form":"복수형","example":"The hotel serves warm scones with butter during afternoon tea in the lobby.","exampleTranslation":"그 호텔은 로비에서 오후 티타임에 따뜻한 스콘을 버터와 함께 낸다.","sense":"스콘"},{"wordId":20021,"answer":"sourdough","form":"원형","example":"My neighbor started baking sourdough at home and now gives us a loaf every week.","exampleTranslation":"이웃이 집에서 사워도우 빵을 굽기 시작해서 이제 매주 우리에게 한 덩어리씩 준다.","sense":"사워도우 빵"},{"wordId":20022,"answer":"loaves","form":"복수형","example":"The church volunteers baked twenty loaves of bread for the charity sale.","exampleTranslation":"교회 봉사자들이 자선 바자회를 위해 빵 스무 덩어리를 구웠다.","sense":"빵 한 덩어리"},{"wordId":20023,"answer":"baguettes","form":"복수형","example":"For the picnic, we bought two baguettes, some cheese, and a bottle of juice.","exampleTranslation":"소풍을 위해 바게트 두 개와 치즈 조금, 주스 한 병을 샀다.","sense":"바게트"},{"wordId":20024,"answer":"cinnamon roll","form":"원형","example":"My roommate and I split a giant cinnamon roll at the mall food court.","exampleTranslation":"룸메이트와 나는 쇼핑몰 푸드코트에서 커다란 시나몬 롤을 나눠 먹었다.","sense":"시나몬 롤"},{"wordId":20025,"answer":"display case","form":"원형","example":"The jewelry store keeps its most expensive rings in a locked display case.","exampleTranslation":"그 보석 가게는 가장 비싼 반지를 잠긴 진열장에 보관한다.","sense":"진열장"},{"wordId":20026,"answer":"tip jar","form":"원형","example":"The street musician smiled when the little girl put a dollar in his tip jar.","exampleTranslation":"어린 여자아이가 팁 통에 1달러를 넣자 거리의 음악가가 미소 지었다.","sense":"팁 통"},{"wordId":20027,"answer":"punch card","form":"원형","example":"The sandwich shop gave me a punch card, and I already have six stamps.","exampleTranslation":"샌드위치 가게에서 쿠폰 카드를 받았는데 벌써 도장이 여섯 개다.","sense":"쿠폰 카드"},{"wordId":20028,"answer":"mugs","form":"복수형","example":"We gave our teachers personalized mugs with their names on them at graduation.","exampleTranslation":"우리는 졸업식 때 선생님들께 이름이 새겨진 머그잔을 드렸다.","sense":"머그잔"},{"wordId":20029,"answer":"milk foam","form":"원형","example":"The barista showed us how to draw a leaf in the milk foam.","exampleTranslation":"바리스타가 우유 거품에 나뭇잎을 그리는 법을 보여 주었다.","sense":"우유 거품"},{"wordId":20030,"answer":"chai latte","form":"원형","example":"When my friend visited from India, she said my homemade chai latte was too sweet.","exampleTranslation":"인도에서 친구가 놀러 왔을 때 내가 만든 차이 라테가 너무 달다고 했다.","sense":"차이 라테"},{"wordId":20031,"answer":"matcha","form":"원형","example":"My mom adds a spoonful of matcha to her smoothie every morning for energy.","exampleTranslation":"엄마는 기운을 내려고 매일 아침 스무디에 말차를 한 숟가락 넣으신다.","sense":"말차"},{"wordId":20032,"answer":"hot chocolate","form":"원형","example":"After building a snowman, the children came inside and drank hot chocolate by the fire.","exampleTranslation":"눈사람을 만든 뒤 아이들은 안으로 들어와 난로 옆에서 핫초코를 마셨다.","sense":"핫초코"},{"wordId":20033,"answer":"sweeteners","form":"복수형","example":"My dad avoids sugar, so he tried several sweeteners before finding one he liked.","exampleTranslation":"아빠는 설탕을 피하셔서 마음에 드는 것을 찾기 전까지 여러 감미료를 써 보셨다.","sense":"감미료"},{"wordId":20034,"answer":"mobile order","form":"원형","example":"The line was really long, so I placed a mobile order from the parking lot.","exampleTranslation":"줄이 너무 길어서 주차장에서 모바일 주문을 했다.","sense":"모바일 주문"},{"wordId":20035,"answer":"pickup counter","form":"원형","example":"Three people were waiting at the pickup counter when my name was finally called.","exampleTranslation":"마침내 내 이름이 불렸을 때 픽업대에 세 사람이 기다리고 있었다.","sense":"픽업대"},{"wordId":20036,"answer":"bakeries","form":"복수형","example":"This town has five bakeries, and each one is famous for a different bread.","exampleTranslation":"이 동네에는 빵집이 다섯 곳 있는데 각각 다른 빵으로 유명하다.","sense":"빵집"},{"wordId":20037,"answer":"cupcakes","form":"복수형","example":"Our class sold cupcakes after school to raise money for the field trip.","exampleTranslation":"우리 반은 현장 학습 비용을 모으려고 방과 후에 컵케이크를 팔았다.","sense":"컵케이크"},{"wordId":20038,"answer":"doughnuts","form":"복수형","example":"The new manager brought two boxes of doughnuts on her first day at work.","exampleTranslation":"새 매니저가 출근 첫날 도넛 두 상자를 가져왔다.","sense":"도넛"},{"wordId":20039,"answer":"sprinkles","form":"원형","example":"My little brother poured way too many sprinkles on his ice cream cone.","exampleTranslation":"남동생은 아이스크림콘에 스프링클을 너무 많이 뿌렸다.","sense":"스프링클"},{"wordId":20040,"answer":"brewed","form":"과거형","example":"My grandfather brewed a big pot of ginger tea for us yesterday when we had colds.","exampleTranslation":"어제 우리가 감기에 걸렸을 때 할아버지가 생강차를 큰 주전자로 우려 주셨다.","sense":"우리다"},{"wordId":20041,"answer":"roasts","form":"복수형","example":"The coffee shop offers three roasts, from light and fruity to dark and smoky.","exampleTranslation":"그 커피숍은 가볍고 과일 향이 나는 것부터 진하고 스모키한 것까지 세 가지 로스팅을 제공한다.","sense":"로스팅"},{"wordId":20042,"answer":"coffee beans","form":"원형","example":"My uncle brought back some coffee beans from his trip to Vietnam last spring.","exampleTranslation":"삼촌이 지난봄 베트남 여행에서 원두를 조금 사 오셨다.","sense":"원두"},{"wordId":20043,"answer":"ground coffee","form":"원형","example":"We forgot the grinder at home, so we bought ground coffee for the camping trip.","exampleTranslation":"집에 그라인더를 두고 와서 캠핑용으로 분쇄 원두를 샀다.","sense":"분쇄 원두"},{"wordId":20044,"answer":"half-and-half","form":"원형","example":"My father pours a little half-and-half into his morning tea instead of regular milk.","exampleTranslation":"아빠는 아침 차에 일반 우유 대신 하프앤하프를 조금 부으신다.","sense":"하프앤하프"},{"wordId":20045,"answer":"skim milk","form":"원형","example":"My doctor suggested switching to skim milk to cut down on fat in my diet.","exampleTranslation":"의사는 식단에서 지방을 줄이려면 무지방 우유로 바꾸라고 권했다.","sense":"무지방 우유"},{"wordId":20046,"answer":"pour-over","form":"원형","example":"My brother made me a pour-over at his apartment using a fancy glass dripper.","exampleTranslation":"오빠가 자기 아파트에서 멋진 유리 드리퍼로 핸드드립 커피를 내려 줬다.","sense":"핸드드립 커피"},{"wordId":20047,"answer":"house blend","form":"원형","example":"The waiter recommended the house blend because it is less bitter than the dark roast.","exampleTranslation":"웨이터는 다크 로스트보다 덜 쓰다며 하우스 블렌드를 추천했다.","sense":"하우스 블렌드"},{"wordId":20048,"answer":"crumblier","form":"비교급","example":"This homemade cake is crumblier than the one we bought at the store.","exampleTranslation":"이 집에서 만든 케이크는 가게에서 산 것보다 더 잘 부스러진다.","sense":"잘 부스러지는"},{"wordId":20049,"answer":"flakiest","form":"최상급","example":"My aunt makes the flakiest pie crust I have ever tasted.","exampleTranslation":"이모는 내가 먹어 본 것 중 가장 결이 바삭한 파이 껍질을 만드신다.","sense":"결이 바삭한"},{"wordId":20050,"answer":"day-old","form":"원형","example":"My mom uses day-old bread to make French toast on Sunday mornings.","exampleTranslation":"엄마는 일요일 아침마다 하루 지난 빵으로 프렌치토스트를 만드신다.","sense":"하루 지난"},{"wordId":20051,"answer":"library card","form":"원형","example":"I lost my wallet yesterday, and my library card was inside it too.","exampleTranslation":"어제 지갑을 잃어버렸는데 도서관 카드도 그 안에 있었다.","sense":"도서관 카드"},{"wordId":20052,"answer":"overdue","form":"원형","example":"The librarian said the DVD I returned this morning was three days overdue.","exampleTranslation":"사서는 오늘 아침 내가 반납한 디브이디가 기한을 사흘 넘겼다고 했다.","sense":"기한이 지난"},{"wordId":20053,"answer":"renewed","form":"과거분사","example":"I have renewed this cookbook three times because I keep using its recipes.","exampleTranslation":"이 요리책의 레시피를 계속 쓰느라 대출을 세 번이나 연장했다.","sense":"연장하다","alts":["extended"]},{"wordId":20054,"answer":"borrowing","form":"-ing형","example":"My cousin is borrowing my car this weekend while hers is at the repair shop.","exampleTranslation":"사촌의 차가 정비소에 있어서 이번 주말에 내 차를 빌려 간다.","sense":"빌리다"},{"wordId":20055,"answer":"book return","form":"원형","example":"My daughter ran ahead and pushed her picture books into the book return.","exampleTranslation":"딸이 앞서 뛰어가서 그림책들을 도서 반납함에 밀어 넣었다.","sense":"도서 반납함"},{"wordId":20056,"answer":"reading room","form":"원형","example":"During exam season, the reading room fills up with students before nine in the morning.","exampleTranslation":"시험 기간에는 아홉 시 전에 열람실이 학생들로 가득 찬다.","sense":"열람실"},{"wordId":20057,"answer":"book drop","form":"원형","example":"I returned the books late at night by putting them in the book drop.","exampleTranslation":"밤늦게 무인 반납함에 넣어서 책을 반납했다.","sense":"무인 반납함"},{"wordId":20058,"answer":"call number","form":"원형","example":"The call number on the screen led me straight to the cooking section.","exampleTranslation":"화면의 청구기호를 따라가니 바로 요리 코너가 나왔다.","sense":"청구기호"},{"wordId":20059,"answer":"librarians","form":"복수형","example":"The librarians organized a summer reading contest for kids in our neighborhood.","exampleTranslation":"사서들이 우리 동네 아이들을 위한 여름 독서 대회를 열었다.","sense":"사서"},{"wordId":20060,"answer":"bookstores","form":"복수형","example":"There used to be three bookstores on this street, but only one is left.","exampleTranslation":"이 거리에 서점이 세 곳 있었는데 지금은 한 곳만 남았다.","sense":"서점"},{"wordId":20061,"answer":"paperbacks","form":"복수형","example":"I packed four paperbacks for the beach trip because they hardly weigh anything.","exampleTranslation":"거의 무게가 안 나가서 바닷가 여행에 종이 표지 책 네 권을 챙겼다.","sense":"페이퍼백"},{"wordId":20062,"answer":"hardcovers","form":"복수형","example":"My grandfather keeps all his hardcovers on a tall wooden shelf in the study.","exampleTranslation":"할아버지는 양장본을 모두 서재의 높은 나무 책장에 꽂아 두신다.","sense":"양장본"},{"wordId":20063,"answer":"bestsellers","form":"복수형","example":"The airport shop only sells bestsellers and a few travel guides.","exampleTranslation":"공항 가게는 베스트셀러와 여행 안내서 몇 권만 판다.","sense":"베스트셀러"},{"wordId":20064,"answer":"new arrival","form":"원형","example":"This cookbook is a new arrival, so it is on the front table.","exampleTranslation":"이 요리책은 신간이라 앞쪽 진열대에 놓여 있다.","sense":"신간"},{"wordId":20065,"answer":"authors","form":"복수형","example":"Three local authors visited our school to talk about how they write stories.","exampleTranslation":"지역 작가 세 명이 우리 학교에 와서 이야기를 어떻게 쓰는지 말해 주었다.","sense":"작가","alts":["writers"]},{"wordId":20066,"answer":"signed copy","form":"원형","example":"My best friend gave me a signed copy of my favorite cookbook for my birthday.","exampleTranslation":"가장 친한 친구가 생일 선물로 내가 좋아하는 요리책의 사인본을 줬다.","sense":"사인본"},{"wordId":20067,"answer":"book signing","form":"원형","example":"Hundreds of fans lined up outside the mall for the book signing.","exampleTranslation":"수백 명의 팬이 작가 사인회를 위해 쇼핑몰 밖에 줄을 섰다.","sense":"작가 사인회"},{"wordId":20068,"answer":"genres","form":"복수형","example":"My brother reads all kinds of genres, from history to science fiction.","exampleTranslation":"오빠는 역사부터 공상 과학까지 온갖 장르의 책을 읽는다.","sense":"장르"},{"wordId":20069,"answer":"fiction","form":"원형","example":"Our book club decided to read only fiction this year to keep things light.","exampleTranslation":"우리 독서 모임은 가볍게 가려고 올해는 소설만 읽기로 했다.","sense":"소설"},{"wordId":20070,"answer":"nonfiction","form":"원형","example":"My father rarely reads novels and prefers nonfiction about history and nature.","exampleTranslation":"아빠는 소설은 거의 안 읽고 역사와 자연에 관한 비소설을 좋아하신다.","sense":"비소설"},{"wordId":20071,"answer":"biographies","form":"복수형","example":"My teacher keeps a shelf of biographies about famous scientists in the classroom.","exampleTranslation":"선생님은 교실에 유명한 과학자들의 전기를 한 칸 두고 계신다.","sense":"전기"},{"wordId":20072,"answer":"graphic novel","form":"원형","example":"My niece drew her own graphic novel about a cat who travels to space.","exampleTranslation":"조카는 우주로 여행하는 고양이에 관한 그래픽 노블을 직접 그렸다.","sense":"그래픽 노블"},{"wordId":20073,"answer":"due back","form":"원형","example":"The rented camping gear is due back at the shop by Monday morning.","exampleTranslation":"빌린 캠핑 장비는 월요일 아침까지 가게에 반납해야 한다.","sense":"반납 예정인"},{"wordId":20074,"answer":"periodicals","form":"복수형","example":"The old periodicals are stored in the basement, and you need staff help to see them.","exampleTranslation":"오래된 정기 간행물은 지하에 보관되어 있어 보려면 직원의 도움이 필요하다.","sense":"정기 간행물"},{"wordId":20075,"answer":"interlibrary loan","form":"원형","example":"My history textbook arrived from another city by interlibrary loan in five days.","exampleTranslation":"역사 교과서가 상호 대차로 닷새 만에 다른 도시에서 도착했다.","sense":"상호 대차"},{"wordId":20076,"answer":"quiet zone","form":"원형","example":"The train car near the back is a quiet zone, so please turn off your ringer.","exampleTranslation":"뒤쪽 객차는 정숙 구역이니 벨소리를 꺼 주세요.","sense":"정숙 구역"},{"wordId":20077,"answer":"study room","form":"원형","example":"Our group met in a study room to finish the science project together.","exampleTranslation":"우리 조는 과학 과제를 함께 끝내려고 스터디룸에서 만났다.","sense":"스터디룸"},{"wordId":20078,"answer":"reference desk","form":"원형","example":"The man at the reference desk showed me how to find old newspaper articles.","exampleTranslation":"참고 데스크의 남자가 옛날 신문 기사를 찾는 법을 알려 주었다.","sense":"참고 데스크"},{"wordId":20079,"answer":"online catalog","form":"원형","example":"I checked the online catalog from home before driving all the way to the library.","exampleTranslation":"도서관까지 차를 몰고 가기 전에 집에서 온라인 도서 목록을 확인했다.","sense":"온라인 목록"},{"wordId":20080,"answer":"bookmarks","form":"복수형","example":"My daughter made colorful bookmarks for her classmates as end-of-year gifts.","exampleTranslation":"딸은 학년 말 선물로 반 친구들에게 줄 알록달록한 책갈피를 만들었다.","sense":"책갈피"},{"wordId":20081,"answer":"chapters","form":"복수형","example":"The last three chapters were so exciting that I stayed up until two.","exampleTranslation":"마지막 세 장이 너무 흥미진진해서 두 시까지 깨어 있었다.","sense":"장"},{"wordId":20082,"answer":"used bookstore","form":"원형","example":"My uncle runs a small used bookstore that smells like old paper and coffee.","exampleTranslation":"삼촌은 오래된 종이와 커피 냄새가 나는 작은 헌책방을 운영하신다.","sense":"헌책방"},{"wordId":20083,"answer":"dust jacket","form":"원형","example":"The dust jacket on this old book is torn, but the pages are still perfect.","exampleTranslation":"이 오래된 책의 덧표지는 찢어졌지만 속 페이지는 아직 멀쩡하다.","sense":"덧표지"},{"wordId":20084,"answer":"back-ordered","form":"원형","example":"The shoes I wanted in my size are back-ordered until the end of the month.","exampleTranslation":"내가 원하던 사이즈의 신발은 이달 말까지 입고 대기 중이다.","sense":"입고 대기 중인"},{"wordId":20085,"answer":"preordered","form":"과거분사","example":"I have preordered the new video game, so it should arrive on release day.","exampleTranslation":"새 비디오 게임을 예약 주문해서 출시일에 도착할 것이다.","sense":"예약 주문하다"},{"wordId":20086,"answer":"in print","form":"원형","example":"My favorite childhood picture book is still in print after forty years.","exampleTranslation":"어릴 때 가장 좋아했던 그림책은 사십 년이 지난 지금도 출간되고 있다.","sense":"출간 중인"},{"wordId":20087,"answer":"out of print","form":"원형","example":"My mother searched online for weeks because her old textbook is out of print.","exampleTranslation":"엄마의 옛 교과서가 절판되어서 엄마는 몇 주 동안 인터넷을 뒤지셨다.","sense":"절판된"},{"wordId":20089,"answer":"story time","form":"원형","example":"The children sat on the carpet and listened quietly during story time.","exampleTranslation":"아이들은 동화 시간 동안 카펫에 앉아 조용히 들었다.","sense":"동화 시간"},{"wordId":20090,"answer":"reading nook","form":"원형","example":"My dad built a reading nook under the stairs with pillows and a small lamp.","exampleTranslation":"아빠는 계단 밑에 베개와 작은 램프를 두고 책 읽는 공간을 만드셨다.","sense":"책 읽는 공간"},{"wordId":20091,"answer":"page-turners","form":"복수형","example":"My mom likes page-turners, so I gave her two mystery novels for her trip.","exampleTranslation":"엄마는 손을 못 떼는 책을 좋아하셔서 여행용으로 추리 소설 두 권을 드렸다.","sense":"손 못 떼는 책"},{"wordId":20092,"answer":"plots","form":"복수형","example":"The plots of these soap operas are always full of surprise twins and lost memories.","exampleTranslation":"이 연속극들의 줄거리는 항상 깜짝 쌍둥이와 기억 상실로 가득하다.","sense":"줄거리"},{"wordId":20093,"answer":"spoilers","form":"복수형","example":"My friends were posting spoilers online, so I turned off my phone before the finale.","exampleTranslation":"친구들이 인터넷에 결말을 올리고 있어서 마지막 회 전에 휴대폰을 껐다.","sense":"스포일러"},{"wordId":20094,"answer":"editions","form":"복수형","example":"The museum shop sells both cheap and deluxe editions of the art guide.","exampleTranslation":"박물관 기념품점은 미술 안내서의 저렴한 판과 고급 판을 모두 판다.","sense":"판"},{"wordId":20095,"answer":"publishers","form":"복수형","example":"She sent her children's book to five publishers before one finally said yes.","exampleTranslation":"그녀는 동화책을 출판사 다섯 곳에 보낸 끝에 마침내 한 곳에서 승낙을 받았다.","sense":"출판사"},{"wordId":20096,"answer":"best-selling","form":"원형","example":"This blender is the best-selling item in our store this month.","exampleTranslation":"이 믹서기가 이번 달 우리 가게에서 가장 많이 팔리는 상품이다.","sense":"잘 팔리는"},{"wordId":20097,"answer":"author talk","form":"원형","example":"After the author talk, the writer answered questions from students for an hour.","exampleTranslation":"작가와의 만남이 끝난 뒤 작가는 한 시간 동안 학생들의 질문에 답했다.","sense":"작가와의 만남"},{"wordId":20098,"answer":"borrowing limit","form":"원형","example":"I reached my borrowing limit, so I had to return two books first.","exampleTranslation":"대출 한도에 도달해서 먼저 책 두 권을 반납해야 했다.","sense":"대출 한도"},{"wordId":20099,"answer":"magazine rack","form":"원형","example":"The dentist's waiting room has a magazine rack full of old cooking magazines.","exampleTranslation":"치과 대기실에는 오래된 요리 잡지로 가득한 잡지 꽂이가 있다.","sense":"잡지 꽂이"},{"wordId":20100,"answer":"self-checkout machine","form":"원형","example":"The self-checkout machine was broken, so I waited in line for the front desk.","exampleTranslation":"무인 대출기가 고장 나서 안내 데스크 앞에 줄을 섰다.","sense":"무인 대출기"},{"wordId":20101,"answer":"homework","form":"원형","example":"My daughter finished her math homework before dinner so she could watch a movie.","exampleTranslation":"딸은 영화를 보려고 저녁 전에 수학 숙제를 끝냈다.","sense":"숙제"},{"wordId":20102,"answer":"report card","form":"원형","example":"My son hid his report card in his backpack because he failed science.","exampleTranslation":"아들은 과학 과목에서 낙제해서 성적표를 가방에 숨겼다.","sense":"성적표"},{"wordId":20103,"answer":"parent-teacher conference","form":"원형","example":"My husband took the afternoon off to attend the parent-teacher conference at our son's school.","exampleTranslation":"남편은 아들 학교의 학부모 상담에 가려고 오후 반차를 냈다.","sense":"학부모 상담"},{"wordId":20104,"answer":"field trip","form":"원형","example":"On our field trip to the farm, the kids fed goats and picked apples.","exampleTranslation":"농장으로 간 현장 학습에서 아이들은 염소에게 먹이를 주고 사과를 땄다.","sense":"현장 학습"},{"wordId":20105,"answer":"permission slip","form":"원형","example":"My daughter could not go to the zoo because I forgot the permission slip.","exampleTranslation":"내가 동의서를 깜빡해서 딸이 동물원에 가지 못했다.","sense":"동의서"},{"wordId":20106,"answer":"school bus","form":"원형","example":"My son missed the school bus this morning, so I drove him to class.","exampleTranslation":"아들이 오늘 아침 통학 버스를 놓쳐서 내가 학교까지 태워다 줬다.","sense":"통학 버스"},{"wordId":20107,"answer":"cafeterias","form":"복수형","example":"Many cafeterias in our city now serve vegetarian meals twice a week.","exampleTranslation":"우리 시의 많은 급식실이 이제 일주일에 두 번 채식 식단을 낸다.","sense":"급식실"},{"wordId":20108,"answer":"school lunch","form":"원형","example":"My son forgot his lunch box, so he ate school lunch for once.","exampleTranslation":"아들이 도시락을 깜빡해서 이번엔 학교 급식을 먹었다.","sense":"학교 급식"},{"wordId":20109,"answer":"recess","form":"원형","example":"It was raining hard, so the children spent recess playing board games inside.","exampleTranslation":"비가 많이 와서 아이들은 쉬는 시간에 안에서 보드게임을 했다.","sense":"쉬는 시간"},{"wordId":20110,"answer":"principals","form":"복수형","example":"The principals from five schools met to discuss safer routes for students.","exampleTranslation":"다섯 학교의 교장 선생님들이 학생들의 더 안전한 등하굣길을 논의하려고 모였다.","sense":"교장 선생님"},{"wordId":20111,"answer":"homeroom teacher","form":"원형","example":"My homeroom teacher in high school still sends me a card every new year.","exampleTranslation":"고등학교 때 담임 선생님은 지금도 매년 새해에 카드를 보내 주신다.","sense":"담임 선생님"},{"wordId":20112,"answer":"semesters","form":"복수형","example":"My cousin studied in Spain for two semesters and came back speaking great Spanish.","exampleTranslation":"사촌은 스페인에서 두 학기 동안 공부하고 스페인어를 아주 잘하게 되어 돌아왔다.","sense":"학기","alts":["terms"]},{"wordId":20113,"answer":"midterms","form":"복수형","example":"The library stays open until midnight during midterms for students who need to study.","exampleTranslation":"중간고사 기간에는 공부해야 하는 학생들을 위해 도서관이 자정까지 문을 연다.","sense":"중간고사"},{"wordId":20114,"answer":"math test","form":"원형","example":"My daughter cried after school because she forgot her calculator for the math test.","exampleTranslation":"딸은 수학 시험에 계산기를 깜빡해서 방과 후에 울었다.","sense":"수학 시험"},{"wordId":20115,"answer":"after-school program","form":"원형","example":"The after-school program at the community center offers free soccer and painting classes.","exampleTranslation":"주민 센터의 방과 후 프로그램은 무료 축구와 그림 수업을 제공한다.","sense":"방과 후 활동"},{"wordId":20116,"answer":"absent","form":"원형","example":"Our team leader was absent from the meeting, so we postponed the big decision.","exampleTranslation":"팀장님이 회의에 빠져서 우리는 중요한 결정을 미뤘다.","sense":"결석한"},{"wordId":20117,"answer":"tardy","form":"원형","example":"The bus broke down on the highway, so half the class was tardy this morning.","exampleTranslation":"고속도로에서 버스가 고장 나서 오늘 아침 반 학생 절반이 지각했다.","sense":"지각한"},{"wordId":20119,"answer":"dismissal time","form":"원형","example":"Parents start lining up in their cars ten minutes before dismissal time.","exampleTranslation":"부모들은 하교 시간 십 분 전부터 차를 타고 줄을 서기 시작한다.","sense":"하교 시간"},{"wordId":20120,"answer":"drop-off","form":"원형","example":"The drop-off area in front of the school gets crowded when it rains.","exampleTranslation":"비가 오면 학교 앞 하차 구역이 붐빈다.","sense":"내려 주는 곳"},{"wordId":20121,"answer":"backpacks","form":"복수형","example":"The volunteers filled fifty backpacks with notebooks and pencils for children in need.","exampleTranslation":"봉사자들은 어려운 아이들을 위해 가방 쉰 개에 공책과 연필을 채웠다.","sense":"책가방"},{"wordId":20122,"answer":"lockers","form":"복수형","example":"The gym has free lockers, but you need to bring your own lock.","exampleTranslation":"체육관에 무료 사물함이 있지만 자물쇠는 직접 가져와야 한다.","sense":"사물함"},{"wordId":20123,"answer":"gym class","form":"원형","example":"My son twisted his ankle while playing basketball in gym class today.","exampleTranslation":"아들이 오늘 체육 수업에서 농구를 하다가 발목을 삐었다.","sense":"체육 수업"},{"wordId":20124,"answer":"parent association","form":"원형","example":"The parent association raised enough money to buy new books for the school library.","exampleTranslation":"학부모회는 학교 도서관에 새 책을 살 만큼 충분한 돈을 모았다.","sense":"학부모회"},{"wordId":20125,"answer":"school supplies","form":"원형","example":"The store puts school supplies on sale every August before classes begin.","exampleTranslation":"그 가게는 개학 전인 매년 팔월에 학용품을 할인한다.","sense":"학용품"},{"wordId":20126,"answer":"school uniform","form":"원형","example":"My son grew so much this year that his school uniform is already too short.","exampleTranslation":"아들이 올해 너무 커서 교복이 벌써 짧아졌다.","sense":"교복"},{"wordId":20127,"answer":"honor roll","form":"원형","example":"My niece was proud to see her name on the honor roll in the hallway.","exampleTranslation":"조카는 복도에 붙은 우등생 명단에서 자기 이름을 보고 뿌듯해했다.","sense":"우등생 명단"},{"wordId":20128,"answer":"spelling test","form":"원형","example":"My son got every word right on his spelling test and wanted ice cream.","exampleTranslation":"아들은 받아쓰기 시험에서 모든 단어를 맞히고 아이스크림을 사 달라고 했다.","sense":"받아쓰기 시험"},{"wordId":20129,"answer":"science fair","form":"원형","example":"My daughter won second place at the science fair with her plant experiment.","exampleTranslation":"딸은 식물 실험으로 과학 경진 대회에서 이등을 했다.","sense":"과학 대회"},{"wordId":20130,"answer":"school play","form":"원형","example":"Grandma flew in from Texas just to watch her grandson in the school play.","exampleTranslation":"할머니는 손자의 학교 연극을 보려고 텍사스에서 비행기를 타고 오셨다.","sense":"학교 연극"},{"wordId":20131,"answer":"show-and-tell","form":"원형","example":"My daughter wants to bring our new puppy to school for show-and-tell tomorrow.","exampleTranslation":"딸은 내일 발표 시간에 새 강아지를 학교에 데려가고 싶어 한다.","sense":"발표 시간"},{"wordId":20132,"answer":"enrolled","form":"과거형","example":"We enrolled our son in a summer swimming class last month.","exampleTranslation":"우리는 지난달 아들을 여름 수영 수업에 등록시켰다.","sense":"등록하다","alts":["registered"]},{"wordId":20133,"answer":"transfer student","form":"원형","example":"As a transfer student, I felt lonely until I joined the school soccer team.","exampleTranslation":"전학생이었던 나는 학교 축구부에 들어가기 전까지 외로웠다.","sense":"전학생"},{"wordId":20134,"answer":"classrooms","form":"복수형","example":"The old school building has twelve classrooms, but only eight are used now.","exampleTranslation":"오래된 학교 건물에는 교실이 열두 개 있지만 지금은 여덟 개만 쓴다.","sense":"교실"},{"wordId":20135,"answer":"school nurse","form":"원형","example":"My daughter felt dizzy in class, so she went to see the school nurse.","exampleTranslation":"딸은 수업 중에 어지러워서 보건 선생님을 찾아갔다.","sense":"보건 선생님"},{"wordId":20137,"answer":"school year","form":"원형","example":"My son is excited because this school year he finally has his own locker.","exampleTranslation":"아들은 이번 학년도에 드디어 자기 사물함이 생겨서 신이 났다.","sense":"학년도"},{"wordId":20138,"answer":"winter break","form":"원형","example":"My roommate went skiing in Colorado for the whole winter break.","exampleTranslation":"룸메이트는 겨울 방학 내내 콜로라도로 스키를 타러 갔다.","sense":"겨울 방학"},{"wordId":20139,"answer":"snow day","form":"원형","example":"On the snow day, my kids built a huge snowman in the front yard.","exampleTranslation":"폭설로 휴교한 날 아이들은 앞마당에 커다란 눈사람을 만들었다.","sense":"폭설 휴교일"},{"wordId":20140,"answer":"open house","form":"원형","example":"At the open house, my son proudly showed us his science project on the wall.","exampleTranslation":"학교 공개의 날에 아들은 벽에 붙은 과학 과제를 자랑스럽게 보여 주었다.","sense":"학교 공개일"},{"wordId":20141,"answer":"school calendar","form":"원형","example":"I put the school calendar on the fridge so I never miss a field day.","exampleTranslation":"운동회 날을 놓치지 않으려고 학사 일정표를 냉장고에 붙여 두었다.","sense":"학사 일정표"},{"wordId":20142,"answer":"grade level","form":"원형","example":"The teacher gives extra reading help to students who are below grade level.","exampleTranslation":"선생님은 학년 수준보다 뒤처진 학생들에게 읽기 지도를 더 해 준다.","sense":"학년 수준"},{"wordId":20143,"answer":"crossing guard","form":"원형","example":"The friendly crossing guard waves to every child and knows most of their names.","exampleTranslation":"친절한 교통 지도원은 아이들 모두에게 손을 흔들고 대부분의 이름을 안다.","sense":"교통 지도원"},{"wordId":20144,"answer":"hall pass","form":"원형","example":"The teacher gave me a hall pass so I could go to the nurse's office.","exampleTranslation":"선생님이 보건실에 갈 수 있도록 복도 통행증을 주셨다.","sense":"복도 통행증"},{"wordId":20145,"answer":"gifted program","form":"원형","example":"My nephew joined the gifted program and now takes advanced math on Saturdays.","exampleTranslation":"조카는 영재 프로그램에 들어가서 이제 토요일마다 심화 수학을 배운다.","sense":"영재 프로그램"},{"wordId":20146,"answer":"participating","form":"-ing형","example":"Our company is participating in the city marathon to raise money for the hospital.","exampleTranslation":"우리 회사는 병원 기금을 모으려고 시 마라톤에 참여하고 있다.","sense":"참여하다"},{"wordId":20147,"answer":"behavior chart","form":"원형","example":"We made a behavior chart at home to help our son brush his teeth every night.","exampleTranslation":"아들이 매일 밤 이를 닦도록 집에 칭찬 스티커판을 만들었다.","sense":"칭찬 스티커판"},{"wordId":20148,"answer":"school counselor","form":"원형","example":"The school counselor helped my daughter choose which colleges to apply to.","exampleTranslation":"학교 상담 선생님이 딸이 지원할 대학을 고르는 것을 도와주셨다.","sense":"상담 교사"},{"wordId":20149,"answer":"lunch money","form":"원형","example":"When I was a kid, I sometimes spent my lunch money on comic books.","exampleTranslation":"어릴 때 나는 가끔 점심값을 만화책 사는 데 썼다.","sense":"점심값"},{"wordId":20150,"answer":"class picture","form":"원형","example":"In our old class picture, my best friend is the one with crazy curly hair.","exampleTranslation":"옛날 단체 사진에서 머리가 엄청 곱슬곱슬한 아이가 내 가장 친한 친구다.","sense":"단체 사진"},{"wordId":20151,"answer":"tents","form":"복수형","example":"The music festival field was covered with colorful tents by Friday night.","exampleTranslation":"금요일 밤이 되자 음악 축제 들판은 알록달록한 텐트로 뒤덮였다.","sense":"텐트"},{"wordId":20152,"answer":"sleeping bag","form":"원형","example":"My son wants to sleep in his sleeping bag on the living room floor tonight.","exampleTranslation":"아들은 오늘 밤 거실 바닥에서 침낭을 깔고 자고 싶어 한다.","sense":"침낭"},{"wordId":20153,"answer":"campsites","form":"복수형","example":"All the campsites near the beach were full, so we stayed in the forest.","exampleTranslation":"해변 근처 야영지가 모두 꽉 차서 우리는 숲에서 묵었다.","sense":"야영지"},{"wordId":20154,"answer":"campfires","form":"복수형","example":"The town banned campfires this month because the forest is extremely dry.","exampleTranslation":"숲이 너무 건조해서 마을은 이번 달 모닥불을 금지했다.","sense":"모닥불"},{"wordId":20155,"answer":"firewood","form":"원형","example":"My grandfather chops firewood every fall so the house stays warm all winter.","exampleTranslation":"할아버지는 겨울 내내 집이 따뜻하도록 매년 가을 장작을 패신다.","sense":"장작"},{"wordId":20157,"answer":"flashlights","form":"복수형","example":"When the power went out, we searched every drawer for flashlights and batteries.","exampleTranslation":"정전이 되자 우리는 손전등과 건전지를 찾으려고 서랍을 다 뒤졌다.","sense":"손전등"},{"wordId":20158,"answer":"headlamps","form":"복수형","example":"The cave tour guide handed out headlamps to everyone before we went inside.","exampleTranslation":"동굴 투어 가이드가 들어가기 전에 모두에게 헤드랜턴을 나눠 주었다.","sense":"헤드랜턴"},{"wordId":20159,"answer":"lanterns","form":"복수형","example":"For the garden party, we hung paper lanterns along the fence.","exampleTranslation":"정원 파티를 위해 우리는 울타리를 따라 종이 랜턴을 걸었다.","sense":"랜턴"},{"wordId":20160,"answer":"bug spray","form":"원형","example":"The mosquitoes at the baseball game were terrible, and nobody had bug spray.","exampleTranslation":"야구 경기장에 모기가 엄청났는데 벌레 퇴치 스프레이를 가진 사람이 아무도 없었다.","sense":"벌레 스프레이"},{"wordId":20161,"answer":"trekking poles","form":"원형","example":"My father bought trekking poles before his first trip to the Rocky Mountains.","exampleTranslation":"아빠는 첫 로키산맥 여행을 앞두고 등산 스틱을 사셨다.","sense":"등산 스틱"},{"wordId":20162,"answer":"trailheads","form":"복수형","example":"This national park has several trailheads, so check the map before you drive in.","exampleTranslation":"이 국립공원에는 등산로 입구가 여러 곳이니 차를 몰고 들어가기 전에 지도를 확인하세요.","sense":"등산로 입구"},{"wordId":20163,"answer":"backpacking","form":"원형","example":"My sister spent a month backpacking through South America after college.","exampleTranslation":"언니는 대학 졸업 후 한 달 동안 남미를 배낭여행했다.","sense":"배낭여행"},{"wordId":20164,"answer":"coolers","form":"복수형","example":"The volunteers brought three coolers full of cold drinks to the beach cleanup.","exampleTranslation":"자원봉사자들이 해변 청소에 시원한 음료가 가득한 아이스박스 세 개를 가져왔다.","sense":"아이스박스"},{"wordId":20165,"answer":"camp stove","form":"원형","example":"When the power went out, we boiled water for tea on our camp stove.","exampleTranslation":"정전이 되었을 때 캠핑용 버너로 찻물을 끓였다.","sense":"캠핑용 버너"},{"wordId":20166,"answer":"pitch a tent","form":"원형","example":"My kids want to pitch a tent in the backyard and sleep outside tonight.","exampleTranslation":"아이들은 오늘 밤 뒷마당에 텐트를 치고 밖에서 자고 싶어 한다.","sense":"텐트를 치다"},{"wordId":20167,"answer":"tent stake","form":"원형","example":"Our dog ran off with a tent stake, so we used a stick instead.","exampleTranslation":"개가 텐트 팩을 물고 달아나서 대신 막대기를 썼다.","sense":"텐트 팩"},{"wordId":20168,"answer":"tarps","form":"복수형","example":"The farmers covered the hay with tarps before the heavy rain arrived.","exampleTranslation":"농부들은 폭우가 오기 전에 건초를 방수포로 덮었다.","sense":"방수포"},{"wordId":20169,"answer":"hammocks","form":"복수형","example":"The beach hotel has hammocks under the palm trees for guests to relax.","exampleTranslation":"그 해변 호텔은 손님들이 쉴 수 있도록 야자수 아래에 해먹을 두었다.","sense":"해먹"},{"wordId":20170,"answer":"canteens","form":"복수형","example":"The soldiers in the old movie shared their canteens during the long desert march.","exampleTranslation":"그 옛날 영화 속 병사들은 긴 사막 행군 동안 수통을 나눠 마셨다.","sense":"수통"},{"wordId":20171,"answer":"compasses","form":"복수형","example":"The scout leader handed out compasses and taught the kids how to use them.","exampleTranslation":"스카우트 대장이 나침반을 나눠 주고 아이들에게 사용법을 가르쳤다.","sense":"나침반"},{"wordId":20172,"answer":"park ranger","form":"원형","example":"A park ranger gave a fun talk about owls at the visitor center.","exampleTranslation":"공원 관리인이 방문자 센터에서 부엉이에 관한 재미있는 강연을 했다.","sense":"공원 관리인"},{"wordId":20173,"answer":"wildlife","form":"원형","example":"We took a boat tour to see the wildlife along the river at sunrise.","exampleTranslation":"해 뜰 무렵 강을 따라 야생 동물을 보려고 보트 투어를 했다.","sense":"야생 동물"},{"wordId":20174,"answer":"bear-proof","form":"원형","example":"The campground gave us a bear-proof container for our snacks and toothpaste.","exampleTranslation":"캠핑장에서 간식과 치약을 넣을 곰이 열 수 없는 통을 줬다.","sense":"곰이 못 여는"},{"wordId":20175,"answer":"mosquito bite","form":"원형","example":"My daughter could not sleep because a mosquito bite on her ankle itched so much.","exampleTranslation":"딸은 발목에 모기 물린 자리가 너무 가려워서 잠을 못 잤다.","sense":"모기 물린 곳"},{"wordId":20176,"answer":"poison ivy","form":"원형","example":"My son got a rash on his arms after touching poison ivy in the woods.","exampleTranslation":"아들은 숲에서 덩굴옻나무를 만진 뒤 팔에 발진이 났다.","sense":"덩굴옻나무"},{"wordId":20177,"answer":"camper van","form":"원형","example":"My parents sold their house and now travel the country in a camper van.","exampleTranslation":"부모님은 집을 팔고 지금은 캠핑카로 전국을 여행하신다.","sense":"캠핑카"},{"wordId":20178,"answer":"log cabin","form":"원형","example":"My uncle built a log cabin by the lake with help from his friends.","exampleTranslation":"삼촌은 친구들의 도움을 받아 호숫가에 통나무 오두막을 지었다.","sense":"통나무 오두막"},{"wordId":20179,"answer":"fire pit","form":"원형","example":"We invited the neighbors over and sat around the fire pit in our backyard.","exampleTranslation":"이웃을 초대해서 뒷마당 화로 주위에 둘러앉았다.","sense":"화로"},{"wordId":20180,"answer":"kindling","form":"원형","example":"My dad taught me to use old newspaper and small sticks as kindling.","exampleTranslation":"아빠는 헌 신문과 작은 나뭇가지를 불쏘시개로 쓰는 법을 가르쳐 주셨다.","sense":"불쏘시개"},{"wordId":20181,"answer":"pocketknives","form":"복수형","example":"The airport staff took away two pocketknives from passengers in front of me.","exampleTranslation":"공항 직원이 내 앞 승객들에게서 주머니칼 두 개를 압수했다.","sense":"주머니칼"},{"wordId":20182,"answer":"rain gear","form":"원형","example":"The tour company lends rain gear to everyone visiting the waterfall.","exampleTranslation":"그 여행사는 폭포를 찾는 모든 사람에게 비옷 장비를 빌려준다.","sense":"비옷 장비"},{"wordId":20183,"answer":"summits","form":"복수형","example":"From the plane window, we could see snowy summits all the way to the horizon.","exampleTranslation":"비행기 창밖으로 지평선까지 눈 덮인 산봉우리들이 보였다.","sense":"정상","alts":["crests"]},{"wordId":20184,"answer":"canoes","form":"복수형","example":"The summer camp has ten canoes, and the older kids race them every Friday.","exampleTranslation":"여름 캠프에는 카누가 열 척 있는데 큰 아이들이 금요일마다 경주를 한다.","sense":"카누"},{"wordId":20185,"answer":"stargazing","form":"원형","example":"Our astronomy club drives out of the city once a month for stargazing.","exampleTranslation":"우리 천문 동아리는 별을 보러 한 달에 한 번 도시 밖으로 나간다.","sense":"별 보기"},{"wordId":20186,"answer":"leave no trace","form":"원형","example":"Our hiking club asks every member to leave no trace on the mountain trails.","exampleTranslation":"우리 등산 동호회는 모든 회원에게 산길에 흔적을 남기지 말라고 당부한다.","sense":"흔적 안 남기기"},{"wordId":20187,"answer":"campgrounds","form":"복수형","example":"Most campgrounds in this area close in October when the weather turns cold.","exampleTranslation":"이 지역 캠핑장 대부분은 날씨가 추워지는 시월에 문을 닫는다.","sense":"캠핑장"},{"wordId":20188,"answer":"camping chair","form":"원형","example":"My grandpa watched the fireworks from a camping chair at the end of the driveway.","exampleTranslation":"할아버지는 진입로 끝에서 캠핑 의자에 앉아 불꽃놀이를 보셨다.","sense":"캠핑 의자"},{"wordId":20189,"answer":"sleeping pad","form":"원형","example":"My sleeping pad got a hole, so I woke up with a sore back.","exampleTranslation":"캠핑 매트에 구멍이 나서 허리가 아픈 채로 깼다.","sense":"캠핑 매트"},{"wordId":20190,"answer":"matches","form":"원형","example":"The waiter lit the birthday candles with matches from the kitchen.","exampleTranslation":"웨이터가 주방에서 가져온 성냥으로 생일 초에 불을 붙였다.","sense":"성냥"},{"wordId":20191,"answer":"roast marshmallows","form":"원형","example":"After dinner at the beach, the kids wanted to roast marshmallows over the grill.","exampleTranslation":"해변에서 저녁을 먹은 뒤 아이들은 그릴에 마시멜로를 굽고 싶어 했다.","sense":"마시멜로 굽다"},{"wordId":20192,"answer":"put out the fire","form":"원형","example":"The firefighters needed three hours to put out the fire at the old warehouse.","exampleTranslation":"소방관들이 낡은 창고의 불을 끄는 데 세 시간이 걸렸다.","sense":"불을 끄다"},{"wordId":20193,"answer":"rough it","form":"원형","example":"My parents like to rough it on vacation, but I prefer a nice hotel.","exampleTranslation":"부모님은 휴가 때 불편하게 지내는 걸 좋아하시지만 나는 좋은 호텔이 더 좋다.","sense":"불편하게 지내다"},{"wordId":20194,"answer":"glamping","form":"원형","example":"For our anniversary, we tried glamping in a tent with heaters and a real bathroom.","exampleTranslation":"기념일에 우리는 난방기와 진짜 욕실이 있는 텐트에서 글램핑을 해 봤다.","sense":"글램핑"},{"wordId":20195,"answer":"most outdoorsy","form":"최상급","example":"My aunt is the most outdoorsy person in our family and loves kayaking.","exampleTranslation":"이모는 우리 가족 중에서 야외 활동을 가장 좋아하고 카약 타기를 즐긴다.","sense":"야외 좋아하는"},{"wordId":20196,"answer":"insect repellent","form":"원형","example":"The pharmacy near the hotel sells insect repellent made for small children.","exampleTranslation":"호텔 근처 약국은 어린아이용 벌레 기피제를 판다.","sense":"벌레 기피제"},{"wordId":20197,"answer":"water filter","form":"원형","example":"We installed a water filter under the kitchen sink because the tap water tastes strange.","exampleTranslation":"수돗물 맛이 이상해서 부엌 싱크대 밑에 정수 필터를 달았다.","sense":"정수 필터"},{"wordId":20198,"answer":"dry bag","form":"원형","example":"My dry bag kept my camera safe when our raft flipped over.","exampleTranslation":"래프트가 뒤집혔을 때 방수 가방 덕분에 카메라가 무사했다.","sense":"방수 가방"},{"wordId":20199,"answer":"set up camp","form":"원형","example":"The hikers decided to set up camp next to a small waterfall.","exampleTranslation":"등산객들은 작은 폭포 옆에 야영지를 차리기로 했다.","sense":"야영 준비하다"},{"wordId":20200,"answer":"starry","form":"원형","example":"My daughter painted a starry sky on the ceiling of her bedroom.","exampleTranslation":"딸은 자기 방 천장에 별이 총총한 하늘을 그렸다.","sense":"별이 총총한"},{"wordId":20201,"answer":"volunteers","form":"복수형","example":"Twenty volunteers helped clean up the park after the music festival.","exampleTranslation":"음악 축제가 끝난 뒤 자원봉사자 스무 명이 공원 청소를 도왔다.","sense":"자원봉사자"},{"wordId":20202,"answer":"donating","form":"-ing형","example":"My neighbor is donating her old furniture to a family who just moved here.","exampleTranslation":"이웃은 막 이사 온 가족에게 오래된 가구를 기증하고 있다.","sense":"기부하다"},{"wordId":20203,"answer":"donations","form":"복수형","example":"The food bank needs more donations of rice and canned beans this winter.","exampleTranslation":"푸드뱅크는 이번 겨울에 쌀과 콩 통조림 기부가 더 필요하다.","sense":"기부"},{"wordId":20204,"answer":"charities","form":"복수형","example":"My company supports three local charities that help older people living alone.","exampleTranslation":"우리 회사는 혼자 사는 어르신을 돕는 지역 자선 단체 세 곳을 후원한다.","sense":"자선 단체"},{"wordId":20205,"answer":"nonprofits","form":"복수형","example":"Several nonprofits in our city offer free English classes for new immigrants.","exampleTranslation":"우리 시의 여러 비영리 단체가 새로 온 이민자들에게 무료 영어 수업을 제공한다.","sense":"비영리 단체"},{"wordId":20206,"answer":"fundraisers","form":"복수형","example":"Our soccer club holds two fundraisers a year to pay for new uniforms.","exampleTranslation":"우리 축구 클럽은 새 유니폼 비용을 마련하려고 일 년에 두 번 모금 행사를 연다.","sense":"모금 행사"},{"wordId":20207,"answer":"food bank","form":"원형","example":"The food bank ran out of baby formula, so they asked stores for help.","exampleTranslation":"푸드뱅크에 분유가 떨어져서 가게들에 도움을 요청했다.","sense":"푸드뱅크"},{"wordId":20208,"answer":"soup kitchen","form":"원형","example":"On Thanksgiving, our whole family helps cook turkey at the soup kitchen downtown.","exampleTranslation":"추수감사절에는 우리 가족 모두가 시내 무료 급식소에서 칠면조 요리를 돕는다.","sense":"무료 급식소"},{"wordId":20209,"answer":"homeless shelter","form":"원형","example":"The homeless shelter opens extra beds when the temperature drops below freezing.","exampleTranslation":"기온이 영하로 떨어지면 노숙인 쉼터는 침대를 추가로 연다.","sense":"노숙인 쉼터"},{"wordId":20210,"answer":"animal shelter","form":"원형","example":"We adopted our old cat from the animal shelter near my office.","exampleTranslation":"우리는 회사 근처 동물 보호소에서 나이 든 고양이를 입양했다.","sense":"동물 보호소"},{"wordId":20211,"answer":"blood drive","form":"원형","example":"The university held a blood drive after the local hospital ran low on blood.","exampleTranslation":"지역 병원의 혈액이 부족해지자 대학교가 헌혈 캠페인을 열었다.","sense":"헌혈 캠페인"},{"wordId":20212,"answer":"volunteer shift","form":"원형","example":"I switched my volunteer shift to Sunday because I have a class on Saturday.","exampleTranslation":"토요일에 수업이 있어서 봉사 시간대를 일요일로 바꿨다.","sense":"봉사 근무"},{"wordId":20213,"answer":"food pantry","form":"원형","example":"The college opened a food pantry for students who cannot afford groceries.","exampleTranslation":"그 대학은 장 볼 형편이 안 되는 학생들을 위해 식료품 나눔터를 열었다.","sense":"식료품 나눔터"},{"wordId":20214,"answer":"community service","form":"원형","example":"My son planted trees in the park for his community service hours this summer.","exampleTranslation":"아들은 이번 여름 지역 사회 봉사 시간을 채우려고 공원에 나무를 심었다.","sense":"지역 사회 봉사"},{"wordId":20215,"answer":"nonperishable food","form":"원형","example":"Our emergency kit has bottled water, a radio, and three days of nonperishable food.","exampleTranslation":"우리 비상용 가방에는 생수와 라디오, 사흘 치 장기 보관 식품이 들어 있다.","sense":"장기 보관 식품"},{"wordId":20216,"answer":"food drive","form":"원형","example":"Each class competed to bring the most cans to the school food drive.","exampleTranslation":"각 반은 학교 식품 기부 운동에 통조림을 가장 많이 가져오려고 경쟁했다.","sense":"식품 기부 운동"},{"wordId":20217,"answer":"clothing drive","form":"원형","example":"The college dorms hold a clothing drive at the end of every school year.","exampleTranslation":"대학 기숙사는 매 학년 말에 의류 기부 운동을 연다.","sense":"의류 기부 운동"},{"wordId":20218,"answer":"pledging","form":"-ing형","example":"Our office is pledging a full day's pay to families hurt by the earthquake.","exampleTranslation":"우리 사무실은 지진 피해 가족들에게 하루 치 급여 전액을 기부하기로 약정하고 있다.","sense":"기부 약정하다"},{"wordId":20219,"answer":"sponsors","form":"3인칭 단수형","example":"Every year, a local bakery sponsors our town's summer music festival.","exampleTranslation":"매년 동네 빵집이 우리 마을의 여름 음악 축제를 후원한다.","sense":"후원하다"},{"wordId":20220,"answer":"donors","form":"복수형","example":"The hospital put the names of its donors on a wall near the entrance.","exampleTranslation":"병원은 입구 근처 벽에 기부자들의 이름을 새겼다.","sense":"기부자"},{"wordId":20221,"answer":"beach cleanup","form":"원형","example":"My kids found an old glass bottle with a note during the beach cleanup.","exampleTranslation":"아이들이 해변 쓰레기 줍기 행사 중에 쪽지가 든 오래된 유리병을 발견했다.","sense":"해변 정화 행사"},{"wordId":20222,"answer":"mentors","form":"복수형","example":"The company pairs new employees with mentors for their first six months.","exampleTranslation":"그 회사는 신입 사원에게 첫 여섯 달 동안 멘토를 짝지어 준다.","sense":"멘토"},{"wordId":20223,"answer":"senior center","form":"원형","example":"My grandmother plays cards with her friends at the senior center every afternoon.","exampleTranslation":"할머니는 매일 오후 노인 복지관에서 친구들과 카드놀이를 하신다.","sense":"노인 복지관"},{"wordId":20224,"answer":"tax-deductible","form":"원형","example":"My accountant told me that my home office costs might be tax-deductible.","exampleTranslation":"회계사는 내 재택 사무실 비용이 세금 공제가 될 수도 있다고 했다.","sense":"세금 공제되는"},{"wordId":20225,"answer":"donation receipt","form":"원형","example":"The thrift store gave me a donation receipt for the bags of clothes I dropped off.","exampleTranslation":"중고 가게에서 내가 맡긴 옷 가방들에 대한 기부금 영수증을 줬다.","sense":"기부금 영수증"},{"wordId":20226,"answer":"bake sale","form":"원형","example":"My daughter made lemon bars for the bake sale at her soccer club.","exampleTranslation":"딸은 축구 클럽 바자회에 낼 레몬 바를 만들었다.","sense":"빵 바자회"},{"wordId":20227,"answer":"charity auction","form":"원형","example":"My boss bought a weekend at a beach house at the charity auction.","exampleTranslation":"사장님은 자선 경매에서 해변 별장 주말 숙박권을 샀다.","sense":"자선 경매"},{"wordId":20228,"answer":"charity run","form":"원형","example":"My whole office wore matching shirts for the charity run in the park.","exampleTranslation":"우리 사무실 사람들은 모두 공원 자선 달리기 대회에 똑같은 티셔츠를 입었다.","sense":"자선 달리기"},{"wordId":20229,"answer":"charity event","form":"원형","example":"The famous singer performed for free at the charity event last night.","exampleTranslation":"그 유명 가수는 어젯밤 자선 행사에서 무료로 공연했다.","sense":"자선 행사"},{"wordId":20230,"answer":"outreach","form":"원형","example":"The clinic does outreach in small villages where people rarely see a doctor.","exampleTranslation":"그 병원은 사람들이 의사를 거의 못 보는 작은 마을로 찾아가는 지원을 한다.","sense":"봉사 활동"},{"wordId":20231,"answer":"volunteer coordinator","form":"원형","example":"The volunteer coordinator gave everyone a yellow vest and a map of the course.","exampleTranslation":"자원봉사 담당자가 모두에게 노란 조끼와 코스 지도를 나눠 줬다.","sense":"봉사 담당자"},{"wordId":20232,"answer":"orientation session","form":"원형","example":"The gym offers a free orientation session to show new members how the machines work.","exampleTranslation":"그 체육관은 신규 회원에게 기구 사용법을 알려 주는 무료 사전 교육을 제공한다.","sense":"사전 교육"},{"wordId":20233,"answer":"hands-on","form":"원형","example":"The science museum has hands-on exhibits where kids can build their own robots.","exampleTranslation":"과학관에는 아이들이 직접 로봇을 만들어 볼 수 있는 체험 전시가 있다.","sense":"직접 해 보는"},{"wordId":20234,"answer":"donation box","form":"원형","example":"Someone left an envelope with five hundred dollars in the donation box last week.","exampleTranslation":"지난주 누군가 모금함에 오백 달러가 든 봉투를 넣고 갔다.","sense":"모금함"},{"wordId":20235,"answer":"in need","form":"원형","example":"My grandmother knits hats every winter for babies in need at the hospital.","exampleTranslation":"할머니는 매년 겨울 병원의 어려운 아기들을 위해 모자를 뜨신다.","sense":"도움이 필요한"},{"wordId":20236,"answer":"disaster relief","form":"원형","example":"Our company sent trucks of blankets and medicine for disaster relief after the storm.","exampleTranslation":"폭풍이 지나간 뒤 우리 회사는 재난 구호를 위해 담요와 약을 실은 트럭을 보냈다.","sense":"재난 구호"},{"wordId":20237,"answer":"thank-you note","form":"원형","example":"My mother taught me to send a thank-you note after every birthday party.","exampleTranslation":"엄마는 생일 파티가 끝날 때마다 감사 카드를 보내라고 가르치셨다.","sense":"감사 카드"},{"wordId":20238,"answer":"helping hand","form":"원형","example":"My neighbor gave me a helping hand when I moved my heavy sofa upstairs.","exampleTranslation":"무거운 소파를 위층으로 옮길 때 이웃이 도움의 손길을 내밀었다.","sense":"도움의 손길"},{"wordId":20239,"answer":"big-hearted","form":"원형","example":"The big-hearted bus driver waited for the old man to reach his seat.","exampleTranslation":"인정 많은 버스 기사는 할아버지가 자리에 앉을 때까지 기다려 주었다.","sense":"인정 많은"},{"wordId":20240,"answer":"goodwill","form":"원형","example":"The new restaurant gave free coffee to neighbors to build some goodwill.","exampleTranslation":"새 식당은 이웃들의 호감을 얻으려고 무료 커피를 나눠 줬다.","sense":"호의"},{"wordId":20241,"answer":"most charitable","form":"최상급","example":"My grandfather was the most charitable man in our small town.","exampleTranslation":"할아버지는 우리 작은 마을에서 가장 너그러운 분이셨다.","sense":"너그러운"},{"wordId":20242,"answer":"more selfless","form":"비교급","example":"My brother became more selfless after he started working as a nurse.","exampleTranslation":"오빠는 간호사로 일하기 시작한 뒤 더 이타적인 사람이 되었다.","sense":"이타적인"},{"wordId":20243,"answer":"most rewarding","form":"최상급","example":"For my father, building a treehouse with his grandkids was the most rewarding project.","exampleTranslation":"아빠에게는 손주들과 나무 위 집을 지은 것이 가장 보람 있는 일이었다.","sense":"보람 있는"},{"wordId":20244,"answer":"habitats","form":"복수형","example":"The new highway could destroy the habitats of several rare frogs.","exampleTranslation":"새 고속도로가 희귀한 개구리 몇 종의 서식지를 망가뜨릴 수 있다.","sense":"서식지"},{"wordId":20245,"answer":"care package","form":"원형","example":"My mom mailed me a care package full of snacks during my first college exams.","exampleTranslation":"대학 첫 시험 기간에 엄마가 간식이 가득한 위문품 꾸러미를 부쳐 주셨다.","sense":"위문품"},{"wordId":20246,"answer":"fundraising goal","form":"원형","example":"The school set a fundraising goal of five thousand dollars for a new piano.","exampleTranslation":"학교는 새 피아노를 위해 오천 달러를 모금 목표액으로 정했다.","sense":"모금 목표액"},{"wordId":20247,"answer":"matching gift","form":"원형","example":"Ask your human resources office whether your employer offers a matching gift program.","exampleTranslation":"회사가 매칭 기부 제도를 운영하는지 인사과에 물어보세요.","sense":"매칭 기부"},{"wordId":20248,"answer":"sign-up sheet","form":"원형","example":"The sign-up sheet for the cooking class filled up in ten minutes.","exampleTranslation":"요리 수업 신청자 명단이 십 분 만에 꽉 찼다.","sense":"신청자 명단"},{"wordId":20249,"answer":"nursing home","form":"원형","example":"My grandfather moved into a nursing home near our house so we can visit often.","exampleTranslation":"할아버지는 우리가 자주 찾아뵐 수 있도록 집 근처 요양원으로 옮기셨다.","sense":"요양원"},{"wordId":20250,"answer":"tutoring","form":"-ing형","example":"My older sister is tutoring her classmate in chemistry after school this month.","exampleTranslation":"언니는 이번 달 방과 후에 반 친구에게 화학을 가르쳐 주고 있다.","sense":"공부를 봐 주다"},{"wordId":20251,"answer":"go viral","form":"원형","example":"Nobody expected a simple photo of our cat to go viral around the world.","exampleTranslation":"우리 고양이의 평범한 사진이 전 세계에 퍼질 줄은 아무도 몰랐다.","sense":"입소문 나다"},{"wordId":20252,"answer":"hashtags","form":"복수형","example":"My nephew uses so many hashtags that nobody can read his captions.","exampleTranslation":"조카는 해시태그를 너무 많이 써서 아무도 설명 글을 읽을 수가 없다.","sense":"해시태그"},{"wordId":20253,"answer":"posted","form":"과거분사","example":"My cousin has posted photos of her new baby on every social media site.","exampleTranslation":"사촌은 모든 소셜 미디어에 새로 태어난 아기 사진을 올렸다.","sense":"올리다"},{"wordId":20254,"answer":"reposting","form":"-ing형","example":"Thousands of people are reposting the video of the firefighter saving a kitten.","exampleTranslation":"수천 명이 새끼 고양이를 구하는 소방관 영상을 퍼 나르고 있다.","sense":"다시 올리다"},{"wordId":20255,"answer":"followers","form":"복수형","example":"The small bakery now has ten thousand followers thanks to its cute cake photos.","exampleTranslation":"그 작은 빵집은 귀여운 케이크 사진 덕분에 이제 팔로워가 만 명이다.","sense":"팔로워"},{"wordId":20256,"answer":"unfollowed","form":"과거형","example":"I unfollowed the gossip page yesterday because it was making me angry.","exampleTranslation":"그 가십 페이지 때문에 화가 나서 어제 팔로우를 끊었다.","sense":"언팔로우하다"},{"wordId":20257,"answer":"direct message","form":"원형","example":"The shoe company answered my complaint quickly through a direct message.","exampleTranslation":"그 신발 회사는 개인 메시지로 내 불만에 빨리 답해 줬다.","sense":"개인 메시지"},{"wordId":20258,"answer":"captions","form":"복수형","example":"My sister writes funny captions for every picture of her dog.","exampleTranslation":"언니는 강아지 사진마다 재미있는 설명 글을 쓴다.","sense":"캡션"},{"wordId":20259,"answer":"livestreams","form":"복수형","example":"Our church started offering livestreams of Sunday services for people who are sick.","exampleTranslation":"우리 교회는 아픈 사람들을 위해 주일 예배 생방송을 시작했다.","sense":"생방송"},{"wordId":20260,"answer":"comment section","form":"원형","example":"The comment section under my recipe video is full of helpful cooking tips.","exampleTranslation":"내 레시피 영상 아래 댓글란은 유용한 요리 팁으로 가득하다.","sense":"댓글란"},{"wordId":20261,"answer":"trolls","form":"복수형","example":"The singer turned off comments because trolls kept attacking her new song.","exampleTranslation":"악플러들이 새 노래를 계속 공격해서 그 가수는 댓글을 막았다.","sense":"악플러"},{"wordId":20262,"answer":"tagging","form":"-ing형","example":"My friends keep tagging me in old high school photos this week.","exampleTranslation":"친구들이 이번 주에 고등학교 때 옛날 사진에 계속 나를 태그하고 있다.","sense":"태그하다"},{"wordId":20263,"answer":"subscribes","form":"3인칭 단수형","example":"My dad subscribes to three fishing channels and watches them every evening.","exampleTranslation":"아빠는 낚시 채널 세 개를 구독하고 매일 저녁 보신다.","sense":"구독하다"},{"wordId":20264,"answer":"influencers","form":"복수형","example":"The hotel invited several travel influencers to stay for free before opening.","exampleTranslation":"그 호텔은 개장 전에 여행 인플루언서 몇 명을 무료로 초대했다.","sense":"인플루언서"},{"wordId":20265,"answer":"content creator","form":"원형","example":"As a content creator, my friend films her cooking every morning in her tiny kitchen.","exampleTranslation":"크리에이터인 친구는 매일 아침 작은 부엌에서 요리하는 모습을 찍는다.","sense":"콘텐츠 제작자"},{"wordId":20266,"answer":"feeds","form":"복수형","example":"Our social media feeds were full of snow pictures after the first snowstorm of the year.","exampleTranslation":"올해 첫 눈보라가 지나간 뒤 우리 소셜 미디어 피드는 눈 사진으로 가득했다.","sense":"피드"},{"wordId":20267,"answer":"scrolls","form":"3인칭 단수형","example":"My husband usually scrolls through the news while he drinks his morning coffee.","exampleTranslation":"남편은 보통 아침 커피를 마시며 뉴스를 넘겨 본다.","sense":"넘겨 보다"},{"wordId":20268,"answer":"doomscrolling","form":"원형","example":"My therapist said doomscrolling late at night was making my anxiety worse.","exampleTranslation":"상담 선생님은 밤늦게 우울한 뉴스를 넘겨 보는 것이 불안을 키운다고 했다.","sense":"둠스크롤링"},{"wordId":20269,"answer":"profile picture","form":"원형","example":"My grandmother asked me to help her change her profile picture to a flower.","exampleTranslation":"할머니가 프로필 사진을 꽃 사진으로 바꾸는 걸 도와 달라고 하셨다.","sense":"프로필 사진"},{"wordId":20270,"answer":"bios","form":"복수형","example":"The conference website shows short bios of all the speakers with their photos.","exampleTranslation":"학회 웹사이트에는 모든 발표자의 짧은 소개 글이 사진과 함께 있다.","sense":"자기소개란"},{"wordId":20271,"answer":"handles","form":"복수형","example":"We wrote our social media handles on name tags at the meetup.","exampleTranslation":"모임에서 우리는 이름표에 소셜 미디어 계정 이름을 적었다.","sense":"계정 이름"},{"wordId":20272,"answer":"private account","form":"원형","example":"My teenage son keeps a private account that only his close friends can follow.","exampleTranslation":"십 대 아들은 친한 친구들만 팔로우할 수 있는 비공개 계정을 쓴다.","sense":"비공개 계정"},{"wordId":20273,"answer":"screenshots","form":"복수형","example":"I took screenshots of the hotel booking in case the website lost my reservation.","exampleTranslation":"웹사이트에서 예약이 사라질까 봐 호텔 예약 화면을 캡처해 두었다.","sense":"화면 캡처"},{"wordId":20274,"answer":"memes","form":"복수형","example":"My coworkers share funny memes in our team chat every Monday morning.","exampleTranslation":"동료들은 매주 월요일 아침 팀 채팅방에 웃긴 짤을 공유한다.","sense":"밈"},{"wordId":20275,"answer":"online community","form":"원형","example":"My dad joined an online community for people who restore old cars.","exampleTranslation":"아빠는 오래된 자동차를 복원하는 사람들의 온라인 커뮤니티에 가입하셨다.","sense":"온라인 커뮤니티"},{"wordId":20276,"answer":"forums","form":"복수형","example":"Travel forums helped me find a cheap way to get from the airport to downtown.","exampleTranslation":"여행 게시판 덕분에 공항에서 시내로 가는 저렴한 방법을 찾았다.","sense":"게시판","alts":["boards"]},{"wordId":20277,"answer":"upvoted","form":"과거분사","example":"Over two thousand people have upvoted my question about cheap camping gear.","exampleTranslation":"이천 명이 넘는 사람이 저렴한 캠핑 장비에 관한 내 질문에 추천을 눌렀다.","sense":"추천을 누르다"},{"wordId":20278,"answer":"lurkers","form":"복수형","example":"Most members of our gardening group are lurkers who never write anything.","exampleTranslation":"우리 원예 모임 회원 대부분은 글은 안 쓰고 보기만 하는 사람들이다.","sense":"눈팅족"},{"wordId":20279,"answer":"spam","form":"원형","example":"The new email filter catches most spam before it reaches my inbox.","exampleTranslation":"새 이메일 필터가 대부분의 스팸을 받은편지함에 오기 전에 걸러 낸다.","sense":"스팸"},{"wordId":20280,"answer":"fake news","form":"원형","example":"Our teacher showed us how to spot fake news by checking the date and author.","exampleTranslation":"선생님은 날짜와 작성자를 확인해서 가짜 뉴스를 알아보는 법을 보여 주셨다.","sense":"가짜 뉴스"},{"wordId":20281,"answer":"go offline","form":"원형","example":"During family dinners, we all agree to go offline and put our phones away.","exampleTranslation":"가족 저녁 식사 때는 모두 인터넷을 끊고 휴대폰을 치우기로 한다.","sense":"인터넷을 끊다"},{"wordId":20282,"answer":"trending","form":"원형","example":"The trending topic this morning was a lost dog who rode the subway alone.","exampleTranslation":"오늘 아침 화제는 혼자 지하철을 탄 길 잃은 강아지였다.","sense":"화제인"},{"wordId":20283,"answer":"algorithms","form":"복수형","example":"Shopping apps use algorithms to guess what you might want to buy next.","exampleTranslation":"쇼핑 앱은 다음에 무엇을 살지 추측하려고 알고리즘을 쓴다.","sense":"알고리즘"},{"wordId":20284,"answer":"clickbait","form":"원형","example":"My grandfather believes every headline, so I taught him how to spot clickbait.","exampleTranslation":"할아버지는 모든 기사 제목을 믿으셔서 낚시성 제목을 알아보는 법을 알려 드렸다.","sense":"낚시성 제목"},{"wordId":20285,"answer":"overshared","form":"과거분사","example":"I think I have overshared about my breakup with my new coworkers.","exampleTranslation":"새 동료들에게 이별 이야기를 너무 많이 털어놓은 것 같다.","sense":"과하게 공개하다"},{"wordId":20286,"answer":"privacy settings","form":"원형","example":"My son helped me update the privacy settings on my new phone.","exampleTranslation":"아들이 새 휴대폰의 개인정보 보호 설정을 바꾸는 것을 도와줬다.","sense":"공개 범위 설정"},{"wordId":20287,"answer":"typos","form":"복수형","example":"My boss found three typos in the report right before the meeting.","exampleTranslation":"사장님이 회의 직전에 보고서에서 오타 세 개를 찾아냈다.","sense":"오타"},{"wordId":20288,"answer":"follow back","form":"원형","example":"When a local bakery followed me first, I decided to follow back right away.","exampleTranslation":"동네 빵집이 먼저 나를 팔로우해서 바로 맞팔로우하기로 했다.","sense":"맞팔로우하다"},{"wordId":20289,"answer":"go live","form":"원형","example":"The band plans to go live from the stage right before the concert starts.","exampleTranslation":"그 밴드는 콘서트 시작 직전에 무대에서 라이브 방송을 시작할 계획이다.","sense":"라이브 시작하다"},{"wordId":20290,"answer":"verified account","form":"원형","example":"The airline posted the schedule changes on its verified account early this morning.","exampleTranslation":"항공사는 오늘 아침 일찍 공식 계정에 일정 변경을 올렸다.","sense":"공식 계정"},{"wordId":20291,"answer":"fact-checks","form":"3인칭 단수형","example":"My sister usually fact-checks every health tip before she shares it with us.","exampleTranslation":"언니는 보통 건강 정보를 우리에게 공유하기 전에 사실 확인을 한다.","sense":"사실 확인하다"},{"wordId":20292,"answer":"reactions","form":"복수형","example":"The funny video of my dad dancing got hundreds of reactions in one hour.","exampleTranslation":"아빠가 춤추는 웃긴 영상이 한 시간 만에 공감 수백 개를 받았다.","sense":"공감 표시"},{"wordId":20293,"answer":"stickers","form":"복수형","example":"My niece bought a pack of cute cat stickers for her messaging app.","exampleTranslation":"조카는 메신저 앱에 쓸 귀여운 고양이 이모티콘 세트를 샀다.","sense":"이모티콘"},{"wordId":20294,"answer":"netiquette","form":"원형","example":"Our teacher gave a short lesson on netiquette before the online class started.","exampleTranslation":"선생님은 온라인 수업을 시작하기 전에 인터넷 예절에 대해 짧게 가르쳐 주셨다.","sense":"인터넷 예절"},{"wordId":20295,"answer":"keyboard warrior","form":"원형","example":"My uncle turns into a keyboard warrior whenever someone criticizes his favorite team.","exampleTranslation":"삼촌은 누가 자기가 좋아하는 팀을 비판하면 키보드 워리어로 변한다.","sense":"키보드 워리어"},{"wordId":20296,"answer":"friend request","form":"원형","example":"My boss sent me a friend request, and I am not sure what to do.","exampleTranslation":"사장님이 친구 신청을 보냈는데 어떻게 해야 할지 모르겠다.","sense":"친구 신청"},{"wordId":20297,"answer":"pinned post","form":"원형","example":"Please read the pinned post before asking questions in this group.","exampleTranslation":"이 모임에서 질문하기 전에 상단 고정 글을 읽어 주세요.","sense":"고정 게시물"},{"wordId":20298,"answer":"link in bio","form":"원형","example":"The singer told her fans to use the link in bio to buy concert tickets.","exampleTranslation":"그 가수는 팬들에게 프로필 링크로 콘서트 표를 사라고 했다.","sense":"프로필 링크"},{"wordId":20299,"answer":"view count","form":"원형","example":"My daughter checks the view count on her dance video every hour.","exampleTranslation":"딸은 한 시간마다 자기 춤 영상의 조회수를 확인한다.","sense":"조회수"},{"wordId":20300,"answer":"online friend","form":"원형","example":"My son plays chess every night with an online friend who lives in Brazil.","exampleTranslation":"아들은 매일 밤 브라질에 사는 인터넷 친구와 체스를 둔다.","sense":"온라인 친구"},{"wordId":20301,"answer":"outfits","form":"복수형","example":"My daughter changed outfits three times on the morning of her first day of school.","exampleTranslation":"딸은 개학 첫날 아침에 옷을 세 번이나 갈아입었다.","sense":"옷차림"},{"wordId":20302,"answer":"more casual","form":"비교급","example":"Our office became more casual after the new boss let us wear sneakers.","exampleTranslation":"새 사장님이 운동화를 허락한 뒤 우리 사무실 분위기가 더 편해졌다.","sense":"편한"},{"wordId":20303,"answer":"most formal","form":"최상급","example":"My graduation dinner was the most formal event I have ever attended.","exampleTranslation":"졸업 만찬은 내가 가 본 행사 중 가장 격식을 차린 자리였다.","sense":"격식을 차린"},{"wordId":20304,"answer":"business casual","form":"원형","example":"The job interview invitation said to wear business casual, so I chose a nice sweater.","exampleTranslation":"면접 안내에 단정한 평상복을 입으라고 해서 깔끔한 스웨터를 골랐다.","sense":"비즈니스 캐주얼"},{"wordId":20305,"answer":"hoodies","form":"복수형","example":"Our team ordered matching hoodies with the company logo for the summer picnic.","exampleTranslation":"우리 팀은 여름 야유회를 위해 회사 로고가 박힌 똑같은 후드티를 주문했다.","sense":"후드티"},{"wordId":20306,"answer":"sweatshirts","form":"복수형","example":"The college bookstore sells sweatshirts in every color with the school name on them.","exampleTranslation":"대학 서점은 학교 이름이 새겨진 온갖 색깔의 맨투맨 티셔츠를 판다.","sense":"맨투맨 티셔츠"},{"wordId":20307,"answer":"jeans","form":"원형","example":"My father wore the same pair of jeans to every family barbecue for years.","exampleTranslation":"아빠는 몇 년 동안 가족 바비큐 때마다 같은 청바지를 입으셨다.","sense":"청바지"},{"wordId":20308,"answer":"sneakers","form":"원형","example":"My son grows so fast that he needs new sneakers every six months.","exampleTranslation":"아들은 너무 빨리 자라서 여섯 달마다 새 운동화가 필요하다.","sense":"운동화"},{"wordId":20309,"answer":"blazers","form":"복수형","example":"All the waiters at the hotel restaurant wear dark blazers and white gloves.","exampleTranslation":"호텔 식당의 웨이터들은 모두 짙은 색 재킷과 흰 장갑을 착용한다.","sense":"블레이저"},{"wordId":20310,"answer":"tank top","form":"원형","example":"My brother wore a tank top to the gym and forgot his jacket afterward.","exampleTranslation":"오빠는 민소매 티셔츠를 입고 헬스장에 갔다가 재킷을 두고 왔다.","sense":"민소매 티셔츠"},{"wordId":20311,"answer":"cardigans","form":"복수형","example":"The shop near my office sells soft wool cardigans at half price in March.","exampleTranslation":"회사 근처 가게는 삼월에 부드러운 울 카디건을 반값에 판다.","sense":"카디건"},{"wordId":20312,"answer":"scarves","form":"복수형","example":"The airport gift shop sells silk scarves printed with famous paintings.","exampleTranslation":"공항 기념품점은 유명한 그림이 프린트된 실크 스카프를 판다.","sense":"스카프"},{"wordId":20313,"answer":"accessories","form":"원형","example":"My niece makes her own accessories from beads and sells them online.","exampleTranslation":"조카는 구슬로 직접 장신구를 만들어 인터넷에서 판다.","sense":"장신구"},{"wordId":20314,"answer":"belts","form":"복수형","example":"The leather shop downtown makes belts by hand and adds your name for free.","exampleTranslation":"시내의 가죽 가게는 허리띠를 손으로 만들고 이름을 무료로 새겨 준다.","sense":"허리띠"},{"wordId":20315,"answer":"heels","form":"원형","example":"My sister carried her heels in her hand and walked home barefoot after the party.","exampleTranslation":"언니는 파티가 끝나고 하이힐을 손에 들고 맨발로 집까지 걸어왔다.","sense":"하이힐"},{"wordId":20316,"answer":"loafers","form":"원형","example":"My grandfather polishes his loafers every Sunday night before church.","exampleTranslation":"할아버지는 매주 일요일 밤 교회 가기 전에 로퍼를 닦으신다.","sense":"로퍼"},{"wordId":20317,"answer":"size down","form":"원형","example":"The salesperson told me to size down because these boots stretch over time.","exampleTranslation":"점원은 이 부츠가 시간이 지나면 늘어나니 한 치수 작게 사라고 했다.","sense":"작게 사다"},{"wordId":20318,"answer":"baggier","form":"비교급","example":"My brother lost a lot of weight, so all his shirts look baggier now.","exampleTranslation":"오빠가 살이 많이 빠져서 이제 셔츠가 다 더 헐렁해 보인다.","sense":"헐렁한"},{"wordId":20319,"answer":"tightest","form":"최상급","example":"After the holidays, my tightest jeans did not fit me at all.","exampleTranslation":"연휴가 지나고 나니 가장 꽉 끼는 청바지가 전혀 맞지 않았다.","sense":"꽉 끼는"},{"wordId":20320,"answer":"looser","form":"비교급","example":"My doctor told me to wear looser clothes while my back heals.","exampleTranslation":"의사는 허리가 나을 때까지 더 느슨한 옷을 입으라고 했다.","sense":"느슨한","alts":["slacker"]},{"wordId":20321,"answer":"matched","form":"과거분사","example":"My tie and socks are perfectly matched for my brother's wedding today.","exampleTranslation":"오늘 형 결혼식을 위해 넥타이와 양말 색을 완벽하게 맞췄다.","sense":"짝이 맞다"},{"wordId":20322,"answer":"clashing","form":"-ing형","example":"My son proudly wore clashing colors, a green shirt with orange pants.","exampleTranslation":"아들은 초록 셔츠에 주황 바지라는 안 어울리는 색 조합을 자랑스럽게 입었다.","sense":"안 어울리는"},{"wordId":20323,"answer":"most stylish","form":"최상급","example":"Everyone agreed that my grandmother was the most stylish guest at the wedding.","exampleTranslation":"모두 할머니가 결혼식에서 가장 멋진 하객이었다고 입을 모았다.","sense":"멋진","alts":["most wonderful"]},{"wordId":20324,"answer":"trendier","form":"비교급","example":"The new coffee shop downtown is trendier, but the old one has better coffee.","exampleTranslation":"시내의 새 커피숍이 더 유행을 타지만 커피는 옛날 가게가 더 맛있다.","sense":"유행하는"},{"wordId":20325,"answer":"most outdated","form":"최상급","example":"The hotel room had the most outdated television I have seen in years.","exampleTranslation":"그 호텔 방에는 몇 년 만에 본 가장 구식인 텔레비전이 있었다.","sense":"구식의"},{"wordId":20326,"answer":"dress down","form":"원형","example":"The new company lets employees dress down every day except when meeting clients.","exampleTranslation":"새 회사는 고객을 만날 때 빼고는 매일 직원들이 편하게 입도록 한다.","sense":"편하게 입다"},{"wordId":20327,"answer":"plainest","form":"최상급","example":"For the job interview, I wore the plainest shirt I could find in my closet.","exampleTranslation":"면접에 내 옷장에서 찾을 수 있는 가장 무늬 없는 셔츠를 입었다.","sense":"무늬 없는"},{"wordId":20328,"answer":"striped","form":"원형","example":"The cafe has striped umbrellas on its patio that you can see from the street.","exampleTranslation":"그 카페 테라스에는 길에서도 보이는 줄무늬 파라솔이 있다.","sense":"줄무늬의"},{"wordId":20329,"answer":"checkered","form":"원형","example":"We spread a checkered blanket on the grass and ate sandwiches by the river.","exampleTranslation":"우리는 잔디에 체크무늬 담요를 깔고 강가에서 샌드위치를 먹었다.","sense":"체크무늬의"},{"wordId":20330,"answer":"polka dot","form":"원형","example":"My grandmother still has the polka dot umbrella she bought in Paris.","exampleTranslation":"할머니는 파리에서 산 물방울무늬 우산을 아직도 갖고 계신다.","sense":"물방울무늬"},{"wordId":20331,"answer":"floral","form":"원형","example":"My mom chose floral curtains for the kitchen to make it feel brighter.","exampleTranslation":"엄마는 부엌이 더 화사해 보이도록 꽃무늬 커튼을 고르셨다.","sense":"꽃무늬의"},{"wordId":20332,"answer":"neutral colors","form":"원형","example":"We painted the living room in neutral colors so the furniture would stand out.","exampleTranslation":"가구가 돋보이도록 거실을 차분한 기본 색으로 칠했다.","sense":"무채색"},{"wordId":20333,"answer":"vintage","form":"원형","example":"My husband collects vintage cameras and keeps them on a shelf in his office.","exampleTranslation":"남편은 빈티지 카메라를 모아서 서재 선반에 둔다.","sense":"빈티지의"},{"wordId":20334,"answer":"designer brand","form":"원형","example":"My cousin saved for months to buy a handbag from a designer brand.","exampleTranslation":"사촌은 명품 브랜드 핸드백을 사려고 몇 달 동안 돈을 모았다.","sense":"명품 브랜드"},{"wordId":20335,"answer":"tailors","form":"복수형","example":"The tailors on this street can make a suit for you in three days.","exampleTranslation":"이 거리의 재단사들은 사흘 만에 정장을 만들어 준다.","sense":"재단사"},{"wordId":20336,"answer":"layered","form":"과거형","example":"It was freezing at the stadium last night, so I layered two jackets.","exampleTranslation":"어젯밤 경기장이 너무 추워서 재킷 두 벌을 겹쳐 입었다.","sense":"겹쳐 입다"},{"wordId":20337,"answer":"fashion sense","form":"원형","example":"My grandfather had amazing fashion sense and always wore a hat in town.","exampleTranslation":"할아버지는 패션 감각이 대단하셔서 시내에 나갈 땐 늘 모자를 쓰셨다.","sense":"패션 감각"},{"wordId":20338,"answer":"look good on","form":"원형","example":"The saleswoman said that these round glasses would look good on my face.","exampleTranslation":"여자 점원은 이 동그란 안경이 내 얼굴에 잘 어울릴 거라고 했다.","sense":"잘 어울리다"},{"wordId":20339,"answer":"out of style","form":"원형","example":"My mother keeps her old dresses because she says nothing stays out of style forever.","exampleTranslation":"엄마는 영원히 유행이 지난 것은 없다며 옛날 원피스를 간직하신다.","sense":"유행이 지난"},{"wordId":20340,"answer":"closets","form":"복수형","example":"Our new apartment has two big closets, so we finally have room for coats.","exampleTranslation":"새 아파트에 큰 붙박이장이 두 개 있어서 드디어 외투 둘 공간이 생겼다.","sense":"옷장","alts":["wardrobes"]},{"wordId":20341,"answer":"turtlenecks","form":"복수형","example":"My history teacher wore black turtlenecks every day of the school year.","exampleTranslation":"역사 선생님은 일 년 내내 매일 검은 목폴라를 입으셨다.","sense":"터틀넥"},{"wordId":20342,"answer":"high-waisted","form":"원형","example":"My mom wore high-waisted shorts in the old family photos from the beach.","exampleTranslation":"해변에서 찍은 옛날 가족사진에서 엄마는 허리선이 높은 반바지를 입고 계셨다.","sense":"하이웨이스트의"},{"wordId":20343,"answer":"oversized","form":"원형","example":"My daughter loves sleeping in an oversized T-shirt that belongs to her dad.","exampleTranslation":"딸은 아빠의 넉넉한 티셔츠를 입고 자는 걸 좋아한다.","sense":"넉넉하게 큰"},{"wordId":20344,"answer":"button-downs","form":"복수형","example":"My husband packed five button-downs for his business trip to Chicago.","exampleTranslation":"남편은 시카고 출장에 단추 셔츠 다섯 벌을 챙겼다.","sense":"버튼다운 셔츠"},{"wordId":20345,"answer":"sleeveless","form":"원형","example":"My son wore a sleeveless jersey for his first basketball game.","exampleTranslation":"아들은 첫 농구 경기에서 민소매 유니폼을 입었다.","sense":"소매 없는"},{"wordId":20346,"answer":"long-sleeved","form":"원형","example":"The nurse told me to wear long-sleeved pajamas so the mosquitoes would not bite.","exampleTranslation":"간호사는 모기에 물리지 않게 긴소매 잠옷을 입으라고 했다.","sense":"긴소매의"},{"wordId":20347,"answer":"pair with","form":"원형","example":"The waiter asked which wine we wanted to pair with the steak.","exampleTranslation":"웨이터는 스테이크에 어떤 와인을 곁들일지 물었다.","sense":"곁들이다"},{"wordId":20348,"answer":"accessorized","form":"과거형","example":"For the party last weekend, my sister accessorized her black dress with gold earrings.","exampleTranslation":"지난 주말 파티에서 언니는 검은 원피스에 금 귀걸이를 매치했다.","sense":"장신구를 더하다"},{"wordId":20349,"answer":"sweatpants","form":"원형","example":"My roommate goes to the grocery store in sweatpants and slippers.","exampleTranslation":"룸메이트는 추리닝 바지에 슬리퍼 차림으로 마트에 간다.","sense":"추리닝"},{"wordId":20350,"answer":"denim","form":"원형","example":"The factory in our town has made denim for jeans for over fifty years.","exampleTranslation":"우리 마을 공장은 오십 년 넘게 청바지용 데님 원단을 만들어 왔다.","sense":"데님"},{"wordId":20351,"answer":"dentists","form":"복수형","example":"Most dentists recommend replacing your toothbrush every three months.","exampleTranslation":"대부분의 치과 의사는 석 달마다 칫솔을 바꾸라고 권한다.","sense":"치과 의사"},{"wordId":20352,"answer":"toothaches","form":"복수형","example":"My little brother gets toothaches because he eats candy every single day.","exampleTranslation":"남동생은 매일 사탕을 먹어서 이가 자주 아프다.","sense":"치통"},{"wordId":20353,"answer":"cavities","form":"복수형","example":"My daughter had no cavities at her checkup, so we celebrated with a movie.","exampleTranslation":"딸이 검진에서 충치가 하나도 없어서 우리는 영화를 보며 축하했다.","sense":"충치"},{"wordId":20354,"answer":"root canal","form":"원형","example":"My mother was nervous about her root canal, but it did not hurt much.","exampleTranslation":"엄마는 신경 치료를 걱정하셨지만 별로 아프지 않았다.","sense":"신경 치료"},{"wordId":20355,"answer":"crowns","form":"복수형","example":"My grandfather has three gold crowns that shine when he laughs.","exampleTranslation":"할아버지는 웃으실 때 반짝이는 금 크라운이 세 개 있으시다.","sense":"크라운"},{"wordId":20356,"answer":"braces","form":"원형","example":"My daughter finally got her braces off and smiled in every photo at the party.","exampleTranslation":"딸은 드디어 교정기를 떼고 파티에서 찍은 모든 사진에서 활짝 웃었다.","sense":"교정기"},{"wordId":20357,"answer":"flossed","form":"과거분사","example":"My son has flossed every night since the dentist found a small cavity.","exampleTranslation":"아들은 치과 의사가 작은 충치를 발견한 뒤로 매일 밤 치실질을 했다.","sense":"치실질하다"},{"wordId":20358,"answer":"gums","form":"원형","example":"The new toothpaste made my gums feel much healthier after a few weeks.","exampleTranslation":"새 치약을 몇 주 쓰니 잇몸이 훨씬 건강해진 느낌이었다.","sense":"잇몸"},{"wordId":20359,"answer":"wisdom tooth","form":"원형","example":"My brother ate only soup for three days after his wisdom tooth was pulled.","exampleTranslation":"오빠는 사랑니를 뽑고 사흘 동안 수프만 먹었다.","sense":"사랑니"},{"wordId":20360,"answer":"pull a tooth","form":"원형","example":"Our dentist can pull a tooth in less than five minutes.","exampleTranslation":"우리 치과 의사는 오 분도 안 걸려서 이를 뽑을 수 있다.","sense":"이를 뽑다"},{"wordId":20361,"answer":"sensitive teeth","form":"원형","example":"This toothpaste is made for people with sensitive teeth who love cold drinks.","exampleTranslation":"이 치약은 찬 음료를 좋아하는 시린 이를 가진 사람들을 위해 만들어졌다.","sense":"시린 이"},{"wordId":20362,"answer":"mouthwash","form":"원형","example":"I keep a small bottle of mouthwash in my desk for after lunch.","exampleTranslation":"점심 먹은 뒤 쓰려고 책상에 가글을 작은 병으로 넣어 둔다.","sense":"구강 청결제"},{"wordId":20363,"answer":"x-rays","form":"복수형","example":"The doctor looked at the x-rays and said my wrist was not broken.","exampleTranslation":"의사는 엑스레이 사진을 보더니 손목이 부러지지 않았다고 했다.","sense":"엑스레이"},{"wordId":20364,"answer":"retainers","form":"복수형","example":"The twins keep their retainers in different colored cases so they do not mix them up.","exampleTranslation":"쌍둥이는 헷갈리지 않으려고 유지 장치를 서로 다른 색 케이스에 넣는다.","sense":"유지 장치"},{"wordId":20365,"answer":"tooth decay","form":"원형","example":"The school dentist gave a talk to the kids about how to prevent tooth decay.","exampleTranslation":"학교 치과 의사가 아이들에게 충치 예방법에 대해 강의했다.","sense":"치아 부식"},{"wordId":20366,"answer":"plaque","form":"원형","example":"The hygienist used a small tool to scrape the plaque off my back teeth.","exampleTranslation":"치위생사가 작은 도구로 어금니의 치태를 긁어냈다.","sense":"치태"},{"wordId":20367,"answer":"whitening","form":"원형","example":"The dentist said whitening might make my teeth sensitive for a few days.","exampleTranslation":"치과 의사는 미백을 하면 며칠 동안 이가 시릴 수 있다고 했다.","sense":"미백"},{"wordId":20368,"answer":"eye doctor","form":"원형","example":"The eye doctor told my son to take breaks from video games every hour.","exampleTranslation":"안과 의사는 아들에게 한 시간마다 비디오 게임을 쉬라고 했다.","sense":"안과 의사"},{"wordId":20369,"answer":"optometrists","form":"복수형","example":"The optometrists at the mall offer free eye checks for children every Saturday.","exampleTranslation":"쇼핑몰의 검안사들은 토요일마다 아이들에게 무료 시력 검사를 해 준다.","sense":"검안사"},{"wordId":20370,"answer":"eye exam","form":"원형","example":"My company pays for a yearly eye exam because we work on screens all day.","exampleTranslation":"우리는 하루 종일 화면을 보며 일해서 회사가 매년 시력 검사 비용을 내 준다.","sense":"시력 검사"},{"wordId":20371,"answer":"eyesight","form":"원형","example":"My grandfather still has perfect eyesight and reads the newspaper without glasses.","exampleTranslation":"할아버지는 아직도 시력이 완벽하셔서 안경 없이 신문을 읽으신다.","sense":"시력"},{"wordId":20372,"answer":"nearsighted","form":"원형","example":"My son became nearsighted after spending so much time on his tablet.","exampleTranslation":"아들은 태블릿을 너무 오래 봐서 근시가 되었다.","sense":"근시인"},{"wordId":20373,"answer":"farsighted","form":"원형","example":"Because my mother is farsighted, she asks me to read the small print on medicine bottles.","exampleTranslation":"엄마는 원시라서 약병의 작은 글씨를 나에게 읽어 달라고 하신다.","sense":"원시인"},{"wordId":20374,"answer":"glasses","form":"원형","example":"My son broke his glasses yesterday, so he could not read the board in class.","exampleTranslation":"아들이 어제 안경을 깨뜨려서 수업 시간에 칠판을 읽을 수 없었다.","sense":"안경"},{"wordId":20375,"answer":"contact lenses","form":"원형","example":"My sister switched to contact lenses because her glasses kept fogging up in winter.","exampleTranslation":"언니는 겨울에 안경에 계속 김이 서려서 콘택트렌즈로 바꿨다.","sense":"콘택트렌즈"},{"wordId":20376,"answer":"eye drops","form":"원형","example":"I always pack eye drops for long flights because the air on planes is dry.","exampleTranslation":"비행기 안 공기가 건조해서 장거리 비행에는 항상 안약을 챙긴다.","sense":"안약"},{"wordId":20377,"answer":"blurriest","form":"최상급","example":"My grandmother took the blurriest photos of anyone on our trip to the lake.","exampleTranslation":"호수 여행에서 할머니가 찍은 사진이 누구 것보다도 가장 흐릿했다.","sense":"흐릿한"},{"wordId":20378,"answer":"frames","form":"원형","example":"My daughter picked purple frames for her first pair of glasses.","exampleTranslation":"딸은 첫 안경으로 보라색 안경테를 골랐다.","sense":"안경테"},{"wordId":20379,"answer":"lenses","form":"복수형","example":"The optician said thinner lenses would make my glasses much lighter.","exampleTranslation":"안경사는 더 얇은 안경알을 쓰면 안경이 훨씬 가벼워질 거라고 했다.","sense":"안경알"},{"wordId":20380,"answer":"eye chart","form":"원형","example":"My son tried to memorize the eye chart while he waited for his turn.","exampleTranslation":"아들은 차례를 기다리는 동안 시력 검사표를 외우려고 했다.","sense":"시력 검사표"},{"wordId":20381,"answer":"dry eyes","form":"원형","example":"The heater in our office is so strong that half the team has dry eyes.","exampleTranslation":"사무실 난방기가 너무 세서 팀원 절반이 안구 건조증을 겪는다.","sense":"안구 건조"},{"wordId":20382,"answer":"itchy eyes","form":"원형","example":"My new cat gives my husband itchy eyes, so we bought an air purifier.","exampleTranslation":"새로 들인 고양이 때문에 남편 눈이 가려워서 공기 청정기를 샀다.","sense":"가려운 눈"},{"wordId":20383,"answer":"squints","form":"3인칭 단수형","example":"My grandfather always squints at the television because he refuses to wear glasses.","exampleTranslation":"할아버지는 안경을 안 쓰려고 하셔서 늘 눈을 가늘게 뜨고 텔레비전을 보신다.","sense":"실눈 뜨다"},{"wordId":20384,"answer":"blinked","form":"과거형","example":"The baby blinked in surprise when the camera flashed at the party yesterday.","exampleTranslation":"어제 파티에서 카메라 플래시가 터지자 아기가 놀라 눈을 깜빡였다.","sense":"눈을 깜빡이다"},{"wordId":20385,"answer":"eye strain","form":"원형","example":"Reading on my phone in the dark gives me terrible eye strain.","exampleTranslation":"어두운 데서 휴대폰으로 글을 읽으면 눈이 심하게 피로해진다.","sense":"눈의 피로"},{"wordId":20386,"answer":"reading glasses","form":"원형","example":"My mom keeps a pair of reading glasses in every room of the house.","exampleTranslation":"엄마는 집 안 방마다 돋보기 안경을 하나씩 두신다.","sense":"돋보기 안경"},{"wordId":20387,"answer":"astigmatism","form":"원형","example":"My daughter has astigmatism, so her new glasses have special lenses.","exampleTranslation":"딸은 난시가 있어서 새 안경에 특수한 알을 넣었다.","sense":"난시"},{"wordId":20388,"answer":"laser eye surgery","form":"원형","example":"My coworker took a week off to recover from laser eye surgery.","exampleTranslation":"동료는 레이저 시력 교정술 후 회복하려고 일주일 휴가를 냈다.","sense":"시력 교정술"},{"wordId":20389,"answer":"bitten","form":"과거분사","example":"I have bitten my tongue twice today because I was talking while eating.","exampleTranslation":"먹으면서 말하다가 오늘 혀를 두 번이나 깨물었다.","sense":"깨물다"},{"wordId":20390,"answer":"chewing","form":"-ing형","example":"My puppy keeps chewing my shoes, so I bought him some toys.","exampleTranslation":"강아지가 계속 내 신발을 씹어서 장난감을 몇 개 사 줬다.","sense":"씹다"},{"wordId":20391,"answer":"rinses","form":"3인칭 단수형","example":"My father rinses his coffee cup every morning before he leaves for work.","exampleTranslation":"아빠는 매일 아침 출근하기 전에 커피 잔을 헹구신다.","sense":"헹구다"},{"wordId":20392,"answer":"anesthetics","form":"복수형","example":"The vet explained that modern anesthetics are much safer for older dogs.","exampleTranslation":"수의사는 요즘 마취제가 나이 든 개에게 훨씬 안전하다고 설명했다.","sense":"마취제"},{"wordId":20393,"answer":"gum disease","form":"원형","example":"My uncle lost two teeth because of gum disease he ignored for years.","exampleTranslation":"삼촌은 몇 년 동안 방치한 잇몸병 때문에 이 두 개를 잃었다.","sense":"잇몸병"},{"wordId":20394,"answer":"chipped tooth","form":"원형","example":"My son came home from hockey practice with a chipped tooth and a big smile.","exampleTranslation":"아들은 하키 연습에서 이가 깨진 채로 활짝 웃으며 집에 왔다.","sense":"깨진 치아"},{"wordId":20395,"answer":"molars","form":"복수형","example":"Babies often get fussy when their first molars start coming in.","exampleTranslation":"아기들은 첫 어금니가 나기 시작하면 자주 보챈다.","sense":"어금니"},{"wordId":20396,"answer":"dentures","form":"원형","example":"My grandfather lost his dentures at the beach and had to eat soup for days.","exampleTranslation":"할아버지는 해변에서 틀니를 잃어버리셔서 며칠 동안 수프를 드셔야 했다.","sense":"틀니"},{"wordId":20397,"answer":"dental hygienist","form":"원형","example":"My cousin studied for two years to become a dental hygienist.","exampleTranslation":"사촌은 치위생사가 되려고 이 년 동안 공부했다.","sense":"치위생사"},{"wordId":20398,"answer":"pinkeye","form":"원형","example":"My son stayed home from daycare because he woke up with pinkeye.","exampleTranslation":"아들은 아침에 눈병이 나서 어린이집에 가지 않고 집에 있었다.","sense":"결막염"},{"wordId":20399,"answer":"styes","form":"복수형","example":"My sister gets styes when she forgets to take off her makeup at night.","exampleTranslation":"언니는 밤에 화장을 지우는 걸 잊으면 다래끼가 난다.","sense":"다래끼"},{"wordId":20400,"answer":"double vision","form":"원형","example":"After hitting his head, the player complained of double vision and left the game.","exampleTranslation":"머리를 부딪친 뒤 그 선수는 사물이 겹쳐 보인다며 경기에서 빠졌다.","sense":"겹쳐 보임"},{"wordId":20401,"answer":"shores","form":"복수형","example":"Many small fishing villages line the shores of this beautiful lake.","exampleTranslation":"이 아름다운 호수의 물가를 따라 작은 어촌 마을이 많이 늘어서 있다.","sense":"물가"},{"wordId":20402,"answer":"sand","form":"원형","example":"My kids spent all afternoon building a castle out of wet sand.","exampleTranslation":"아이들은 오후 내내 젖은 모래로 성을 쌓았다.","sense":"모래"},{"wordId":20403,"answer":"waves","form":"복수형","example":"The surfers waited patiently for bigger waves early in the morning.","exampleTranslation":"서퍼들은 이른 아침에 더 큰 파도를 참을성 있게 기다렸다.","sense":"파도"},{"wordId":20404,"answer":"tides","form":"복수형","example":"The fishermen check the tides every morning before they take their boats out.","exampleTranslation":"어부들은 배를 띄우기 전에 매일 아침 물때를 확인한다.","sense":"조수"},{"wordId":20405,"answer":"high tide","form":"원형","example":"The fishing boats can only leave the small harbor at high tide.","exampleTranslation":"작은 항구에서는 만조 때만 어선이 나갈 수 있다.","sense":"만조"},{"wordId":20406,"answer":"low tide","form":"원형","example":"My kids love looking for little crabs in the rock pools during low tide.","exampleTranslation":"아이들은 썰물 때 바위 웅덩이에서 작은 게를 찾는 걸 좋아한다.","sense":"간조"},{"wordId":20407,"answer":"sunscreen","form":"원형","example":"My dermatologist told me to wear sunscreen every day, even in winter.","exampleTranslation":"피부과 의사는 겨울에도 매일 자외선 차단제를 바르라고 했다.","sense":"자외선 차단제"},{"wordId":20408,"answer":"sunburns","form":"복수형","example":"The nurse at the resort treats dozens of sunburns every summer weekend.","exampleTranslation":"리조트 간호사는 여름 주말마다 일광 화상 환자를 수십 명씩 치료한다.","sense":"일광 화상"},{"wordId":20409,"answer":"tan","form":"원형","example":"My brother got a farmer's tan from working in the garden all summer.","exampleTranslation":"오빠는 여름 내내 정원 일을 하다가 팔과 목만 햇볕에 그을렸다.","sense":"그을린 피부"},{"wordId":20410,"answer":"lifeguards","form":"복수형","example":"The lifeguards blew their whistles when the storm clouds started moving in.","exampleTranslation":"먹구름이 몰려오기 시작하자 안전 요원들이 호루라기를 불었다.","sense":"안전 요원"},{"wordId":20411,"answer":"swimsuits","form":"복수형","example":"The department store puts all its swimsuits on sale at the end of August.","exampleTranslation":"그 백화점은 팔월 말에 모든 수영복을 할인한다.","sense":"수영복"},{"wordId":20412,"answer":"swim trunks","form":"원형","example":"My husband packed his swim trunks, but he forgot his sunglasses at home.","exampleTranslation":"남편은 수영 반바지는 챙겼지만 선글라스는 집에 두고 왔다.","sense":"수영 반바지"},{"wordId":20413,"answer":"beach towel","form":"원형","example":"My daughter wrapped herself in a big beach towel after swimming in the cold lake.","exampleTranslation":"딸은 차가운 호수에서 수영한 뒤 큰 비치 타월로 몸을 감쌌다.","sense":"비치 타월"},{"wordId":20414,"answer":"beach umbrella","form":"원형","example":"A strong wind blew our beach umbrella all the way down the sand.","exampleTranslation":"강한 바람에 파라솔이 모래사장 끝까지 날아갔다.","sense":"파라솔"},{"wordId":20415,"answer":"lounge chair","form":"원형","example":"My grandmother fell asleep on a lounge chair on the cruise ship deck.","exampleTranslation":"할머니는 유람선 갑판의 선베드에서 잠이 드셨다.","sense":"선베드"},{"wordId":20416,"answer":"flip-flops","form":"원형","example":"My son lost one of his flip-flops in the river while we were tubing.","exampleTranslation":"우리가 튜브를 타는 동안 아들이 강에서 슬리퍼 한 짝을 잃어버렸다.","sense":"조리"},{"wordId":20417,"answer":"seashells","form":"복수형","example":"My grandmother keeps a jar of seashells from every beach she has visited.","exampleTranslation":"할머니는 다녀온 해변마다 주워 온 조개껍데기를 병에 모아 두신다.","sense":"조개껍데기"},{"wordId":20418,"answer":"sandcastles","form":"복수형","example":"Families competed to build the best sandcastles at the summer festival on the beach.","exampleTranslation":"가족들은 해변 여름 축제에서 가장 멋진 모래성을 쌓으려고 겨뤘다.","sense":"모래성"},{"wordId":20419,"answer":"snorkels","form":"복수형","example":"The tour boat provides masks and snorkels, so you do not need your own.","exampleTranslation":"투어 보트에서 마스크와 스노클을 주니 따로 챙겨 올 필요가 없다.","sense":"스노클"},{"wordId":20420,"answer":"goggles","form":"원형","example":"The swim coach told my son to buy goggles that fit his small face.","exampleTranslation":"수영 코치는 아들에게 작은 얼굴에 맞는 물안경을 사라고 했다.","sense":"물안경"},{"wordId":20421,"answer":"floated","form":"과거분사","example":"We have floated down this lazy river three times already this afternoon.","exampleTranslation":"우리는 오늘 오후에 벌써 세 번이나 이 유수풀을 따라 떠내려갔다.","sense":"뜨다"},{"wordId":20422,"answer":"inflatable","form":"원형","example":"For her birthday party, we rented an inflatable castle for the backyard.","exampleTranslation":"딸의 생일 파티를 위해 뒷마당에 놓을 바람을 넣는 성을 빌렸다.","sense":"부풀리는"},{"wordId":20423,"answer":"deep end","form":"원형","example":"The swim instructor waited in the deep end while each kid jumped in.","exampleTranslation":"수영 강사는 아이들이 한 명씩 뛰어들 때 깊은 쪽에서 기다렸다.","sense":"깊은 쪽"},{"wordId":20424,"answer":"shallow end","form":"원형","example":"My grandmother likes to walk back and forth in the shallow end for exercise.","exampleTranslation":"할머니는 운동 삼아 얕은 쪽에서 왔다 갔다 걷는 걸 좋아하신다.","sense":"얕은 쪽"},{"wordId":20425,"answer":"diving board","form":"원형","example":"The hotel removed the diving board from its pool for safety reasons.","exampleTranslation":"그 호텔은 안전상의 이유로 수영장에서 다이빙대를 없앴다.","sense":"다이빙대"},{"wordId":20426,"answer":"laps","form":"복수형","example":"My father swims thirty laps every morning before he goes to the office.","exampleTranslation":"아빠는 매일 아침 출근 전에 수영장을 서른 바퀴 도신다.","sense":"한 바퀴"},{"wordId":20427,"answer":"backstroke","form":"원형","example":"My daughter won a medal in the backstroke at her first swim meet.","exampleTranslation":"딸은 첫 수영 대회에서 배영으로 메달을 땄다.","sense":"배영"},{"wordId":20428,"answer":"breaststroke","form":"원형","example":"The coach spent the whole lesson teaching us the leg kick for the breaststroke.","exampleTranslation":"코치는 수업 내내 평영 발차기를 가르쳤다.","sense":"평영"},{"wordId":20429,"answer":"freestyle","form":"원형","example":"My sister switched from swimming freestyle to running after she hurt her shoulder.","exampleTranslation":"언니는 어깨를 다친 뒤 자유형 수영에서 달리기로 바꿨다.","sense":"자유형"},{"wordId":20430,"answer":"dog paddle","form":"원형","example":"Our puppy did the dog paddle the first time he jumped into the lake.","exampleTranslation":"우리 강아지는 처음 호수에 뛰어들었을 때 개헤엄을 쳤다.","sense":"개헤엄"},{"wordId":20431,"answer":"tread water","form":"원형","example":"The instructor taught the kids how to tread water if they ever fell off a boat.","exampleTranslation":"강사는 아이들에게 배에서 떨어졌을 때 제자리에서 떠 있는 법을 가르쳤다.","sense":"제자리 헤엄치다"},{"wordId":20432,"answer":"cannonballs","form":"복수형","example":"The teenagers took turns doing cannonballs off the dock at the lake house.","exampleTranslation":"십 대들은 호숫가 집 선착장에서 번갈아 가며 무릎을 껴안고 뛰어들었다.","sense":"웅크린 다이빙"},{"wordId":20433,"answer":"splashed","form":"과거분사","example":"The kids have just splashed water all over the bathroom floor.","exampleTranslation":"아이들이 방금 욕실 바닥 여기저기에 물을 튀겨 놓았다.","sense":"튀기다"},{"wordId":20434,"answer":"wading","form":"-ing형","example":"The farmer was wading across the stream to rescue a lost calf.","exampleTranslation":"농부는 길 잃은 송아지를 구하려고 개울을 걸어서 건너고 있었다.","sense":"걸어 들어가다"},{"wordId":20435,"answer":"currents","form":"복수형","example":"Strong ocean currents carried the plastic bottles all the way to the island.","exampleTranslation":"강한 해류가 플라스틱병을 섬까지 실어 갔다.","sense":"해류"},{"wordId":20436,"answer":"riptides","form":"복수형","example":"The warning sign at the beach explains how to escape from riptides safely.","exampleTranslation":"해변의 경고 표지판은 이안류에서 안전하게 빠져나오는 법을 알려 준다.","sense":"이안류"},{"wordId":20437,"answer":"jellyfish","form":"원형","example":"My son screamed when a jellyfish touched his leg near the boat.","exampleTranslation":"배 근처에서 해파리가 다리에 닿자 아들이 소리를 질렀다.","sense":"해파리"},{"wordId":20438,"answer":"seagulls","form":"복수형","example":"Hungry seagulls followed the ferry all the way across the bay.","exampleTranslation":"배고픈 갈매기들이 만을 건너는 내내 여객선을 따라왔다.","sense":"갈매기"},{"wordId":20439,"answer":"boardwalks","form":"복수형","example":"Some beach towns have wooden boardwalks that stretch for several miles.","exampleTranslation":"어떤 해변 마을에는 몇 마일씩 이어진 나무 산책로가 있다.","sense":"판자 산책로"},{"wordId":20440,"answer":"piers","form":"복수형","example":"The old wooden piers in this harbor were rebuilt after the hurricane.","exampleTranslation":"이 항구의 낡은 나무 부두들은 허리케인이 지나간 뒤 다시 지어졌다.","sense":"부두","alts":["docks"]},{"wordId":20441,"answer":"surfed","form":"과거분사","example":"My uncle has surfed in California every summer since he was a teenager.","exampleTranslation":"삼촌은 십 대 때부터 매년 여름 캘리포니아에서 서핑을 했다.","sense":"서핑하다"},{"wordId":20442,"answer":"surfboards","form":"복수형","example":"The shop on the corner rents surfboards and wetsuits by the hour.","exampleTranslation":"모퉁이 가게는 서핑 보드와 잠수복을 시간 단위로 빌려준다.","sense":"서핑 보드"},{"wordId":20443,"answer":"sunbathes","form":"3인칭 단수형","example":"Our cat sunbathes on the windowsill every afternoon.","exampleTranslation":"우리 고양이는 매일 오후 창턱에서 일광욕을 한다.","sense":"일광욕하다"},{"wordId":20444,"answer":"shade","form":"원형","example":"The old oak tree in our yard gives us plenty of shade in July.","exampleTranslation":"마당의 오래된 참나무가 칠월에 그늘을 넉넉하게 드리워 준다.","sense":"그늘"},{"wordId":20445,"answer":"soak up the sun","form":"원형","example":"The cats in our neighborhood love to soak up the sun on parked cars.","exampleTranslation":"우리 동네 고양이들은 주차된 차 위에서 햇볕을 쬐는 걸 좋아한다.","sense":"햇볕을 쬐다"},{"wordId":20446,"answer":"locker room","form":"원형","example":"The coach gave the team a short speech in the locker room before the game.","exampleTranslation":"코치는 경기 전에 탈의실에서 선수들에게 짧은 연설을 했다.","sense":"탈의실"},{"wordId":20447,"answer":"swim cap","form":"원형","example":"My swim cap is so tight that it leaves a red line on my forehead.","exampleTranslation":"수영모가 너무 꽉 껴서 이마에 빨간 자국이 남는다.","sense":"수영모"},{"wordId":20448,"answer":"life jacket","form":"원형","example":"My father always wears a life jacket when he goes fishing on the lake.","exampleTranslation":"아빠는 호수로 낚시하러 가실 때 늘 구명조끼를 입으신다.","sense":"구명조끼"},{"wordId":20449,"answer":"kickboards","form":"복수형","example":"The swimming school bought new kickboards for the beginner classes.","exampleTranslation":"수영 학원은 초급반을 위해 새 킥판을 샀다.","sense":"킥판"},{"wordId":20450,"answer":"chlorine","form":"원형","example":"My hair turned slightly green from the chlorine after a week at the hotel pool.","exampleTranslation":"호텔 수영장에서 일주일을 보냈더니 소독약 때문에 머리카락이 살짝 초록빛이 됐다.","sense":"염소"},{"wordId":20451,"answer":"shyest","form":"최상급","example":"My son was the shyest kid in his class, but now he loves performing.","exampleTranslation":"아들은 반에서 가장 수줍음이 많았지만 지금은 공연을 아주 좋아한다.","sense":"수줍음 많은"},{"wordId":20452,"answer":"introverts","form":"복수형","example":"Many introverts prefer working from home because the office feels too noisy.","exampleTranslation":"많은 내향적인 사람들은 사무실이 너무 시끄러워서 재택근무를 더 좋아한다.","sense":"내향적인 사람"},{"wordId":20453,"answer":"extroverts","form":"복수형","example":"Extroverts often feel full of energy after spending time in big groups.","exampleTranslation":"외향적인 사람들은 여럿이 어울린 뒤 흔히 에너지가 넘친다.","sense":"외향적인 사람"},{"wordId":20454,"answer":"more easygoing","form":"비교급","example":"My father became more easygoing after he retired and started fishing.","exampleTranslation":"아빠는 은퇴하고 낚시를 시작한 뒤 더 느긋해지셨다.","sense":"느긋한"},{"wordId":20455,"answer":"most hardworking","form":"최상급","example":"My cousin is the most hardworking student in her whole class this year.","exampleTranslation":"내 사촌은 올해 반 전체에서 가장 성실한 학생이다.","sense":"성실한","alts":["most earnest"]},{"wordId":20456,"answer":"more honest","form":"비교급","example":"I wish my coworkers were more honest about their mistakes at work.","exampleTranslation":"동료들이 직장에서 자기 실수에 대해 좀 더 정직했으면 좋겠다.","sense":"정직한"},{"wordId":20457,"answer":"most stubborn","form":"최상급","example":"Our old cat is the most stubborn animal I have ever met.","exampleTranslation":"우리 늙은 고양이는 내가 만나 본 동물 중 가장 고집이 세다.","sense":"고집 센"},{"wordId":20458,"answer":"more patient","form":"비교급","example":"I need to be more patient with my grandmother when she uses her phone.","exampleTranslation":"할머니가 휴대폰을 쓰실 때 더 참을성 있게 대해 드려야 한다.","sense":"참을성 있는"},{"wordId":20459,"answer":"most impatient","form":"최상급","example":"My little brother is the most impatient person in our family when we wait in line.","exampleTranslation":"남동생은 줄을 서서 기다릴 때 우리 가족 중 가장 참을성이 없다.","sense":"성급한"},{"wordId":20460,"answer":"more curious","form":"비교급","example":"Children often become more curious about nature after a trip to the zoo.","exampleTranslation":"아이들은 동물원에 다녀온 뒤 자연에 더 호기심을 갖게 되곤 한다.","sense":"호기심 많은"},{"wordId":20461,"answer":"most creative","form":"최상급","example":"Our art teacher picked the most creative poster to hang in the hallway.","exampleTranslation":"미술 선생님이 복도에 걸 가장 창의적인 포스터를 골랐다.","sense":"창의적인"},{"wordId":20462,"answer":"more organized","form":"비교급","example":"My new desk drawers help me stay more organized at the office.","exampleTranslation":"새 책상 서랍 덕분에 사무실에서 더 체계적으로 지내게 됐다.","sense":"체계적인"},{"wordId":20463,"answer":"most cheerful","form":"최상급","example":"The waiter at that diner is the most cheerful man in town.","exampleTranslation":"그 식당 웨이터는 동네에서 가장 쾌활한 남자다.","sense":"쾌활한"},{"wordId":20464,"answer":"moodier","form":"비교급","example":"Teenagers can get moodier when they do not get enough sleep.","exampleTranslation":"십 대들은 잠을 충분히 못 자면 더 변덕스러워질 수 있다.","sense":"변덕스러운"},{"wordId":20465,"answer":"most sensitive","form":"최상급","example":"Of all my friends, Jake is the most sensitive about his hair.","exampleTranslation":"내 친구들 중에서 제이크가 자기 머리 모양에 가장 예민하다.","sense":"예민한"},{"wordId":20466,"answer":"more confident","form":"비교급","example":"After the cooking class, I feel more confident making dinner for guests.","exampleTranslation":"요리 수업을 듣고 나니 손님에게 저녁을 차려 주는 데 더 자신감이 생긴다.","sense":"자신감 있는"},{"wordId":20467,"answer":"humblest","form":"최상급","example":"The humblest player on the team never talks about his own goals.","exampleTranslation":"팀에서 가장 겸손한 선수는 자기 골 이야기를 절대 하지 않는다.","sense":"겸손한"},{"wordId":20468,"answer":"more reliable","form":"비교급","example":"This used car is more reliable than the one I had before.","exampleTranslation":"이 중고차는 내가 전에 타던 차보다 더 믿을 만하다.","sense":"믿을 만한"},{"wordId":20469,"answer":"most responsible","form":"최상급","example":"We chose the most responsible kid to feed the class fish.","exampleTranslation":"우리는 반 물고기 먹이 주기를 가장 책임감 있는 아이에게 맡겼다.","sense":"책임감 있는"},{"wordId":20470,"answer":"more ambitious","form":"비교급","example":"This year our team set a more ambitious sales goal than last year.","exampleTranslation":"올해 우리 팀은 작년보다 더 야심 찬 판매 목표를 세웠다.","sense":"야심 찬"},{"wordId":20471,"answer":"calmest","form":"최상급","example":"The calmest person in our office handles all the angry phone calls.","exampleTranslation":"우리 사무실에서 가장 침착한 사람이 화난 전화를 전부 처리한다.","sense":"침착한"},{"wordId":20472,"answer":"more talkative","form":"비교급","example":"My son gets more talkative after school when he has a snack.","exampleTranslation":"우리 아들은 학교가 끝나고 간식을 먹으면 더 수다스러워진다.","sense":"수다스러운"},{"wordId":20473,"answer":"quietest","form":"최상급","example":"The third floor of the library is the quietest place to study.","exampleTranslation":"도서관 삼 층이 공부하기에 가장 조용한 곳이다.","sense":"조용한"},{"wordId":20474,"answer":"friendlier","form":"비교급","example":"The staff at the new gym are friendlier than at my old one.","exampleTranslation":"새 헬스장 직원들이 예전 곳보다 더 친절하다.","sense":"친절한"},{"wordId":20475,"answer":"funniest","form":"최상급","example":"That was the funniest movie I watched on the plane last month.","exampleTranslation":"그건 지난달 비행기에서 본 영화 중 가장 웃긴 영화였다.","sense":"웃긴"},{"wordId":20476,"answer":"more caring","form":"비교급","example":"Our new neighbors are more caring than I expected, and they bring us soup.","exampleTranslation":"새 이웃들은 생각보다 더 다정해서 우리에게 수프를 가져다준다.","sense":"다정한","alts":["friendlier","more affectionate"]},{"wordId":20477,"answer":"most independent","form":"최상급","example":"Of my three kids, my daughter is the most independent one.","exampleTranslation":"우리 세 아이 중에서 딸이 가장 자립심이 강하다.","sense":"독립적인"},{"wordId":20478,"answer":"more open-minded","form":"비교급","example":"Living abroad made me more open-minded about different ways of life.","exampleTranslation":"외국에 살면서 나는 다양한 삶의 방식에 더 열린 마음을 갖게 됐다.","sense":"열린 마음의"},{"wordId":20479,"answer":"pickiest","form":"최상급","example":"My nephew is the pickiest eater I know, and he only likes plain rice.","exampleTranslation":"내 조카는 내가 아는 사람 중 입맛이 가장 까다로워서 맨밥만 좋아한다.","sense":"까다로운"},{"wordId":20480,"answer":"more competitive","form":"비교급","example":"My brother became more competitive after he joined the soccer team.","exampleTranslation":"남동생은 축구팀에 들어간 뒤로 승부욕이 더 강해졌다.","sense":"승부욕 강한"},{"wordId":20481,"answer":"laziest","form":"최상급","example":"Sunday afternoon is always the laziest time of my whole week.","exampleTranslation":"일요일 오후는 언제나 내 일주일 중 가장 게으른 시간이다.","sense":"게으른"},{"wordId":20482,"answer":"optimists","form":"복수형","example":"Optimists usually see a missed train as a chance to grab coffee.","exampleTranslation":"낙관주의자들은 보통 기차를 놓쳐도 커피 한잔할 기회로 여긴다.","sense":"낙관주의자"},{"wordId":20483,"answer":"pessimists","form":"복수형","example":"Pessimists always expect the worst when they check the weather forecast.","exampleTranslation":"비관주의자들은 일기 예보를 볼 때 늘 최악을 예상한다.","sense":"비관주의자"},{"wordId":20484,"answer":"people person","form":"원형","example":"Our new receptionist is a real people person who remembers every visitor.","exampleTranslation":"새 접수원은 방문객을 모두 기억하는 정말 사교적인 사람이다.","sense":"사교적인 사람"},{"wordId":20485,"answer":"morning person","form":"원형","example":"Since I became a morning person, I jog before work every day.","exampleTranslation":"아침형 인간이 된 뒤로 나는 매일 출근 전에 조깅한다.","sense":"아침형 인간"},{"wordId":20486,"answer":"night owl","form":"원형","example":"As a night owl, I do my best writing after midnight.","exampleTranslation":"올빼미형 인간이라서 나는 자정이 지나야 글이 가장 잘 써진다.","sense":"올빼미형 인간"},{"wordId":20487,"answer":"homebodies","form":"복수형","example":"Homebodies often enjoy cooking and gardening more than going out to clubs.","exampleTranslation":"집에 있기 좋아하는 사람들은 클럽에 가는 것보다 요리와 정원 가꾸기를 더 즐긴다.","sense":"집순이"},{"wordId":20488,"answer":"let me introduce myself","form":"원형","example":"Before I show you around the office, let me introduce myself properly.","exampleTranslation":"사무실을 안내해 드리기 전에 제 소개를 제대로 하겠습니다.","sense":"자기소개하다"},{"wordId":20490,"answer":"go by","form":"원형","example":"In this class, you can go by any nickname you like.","exampleTranslation":"이 수업에서는 원하는 어떤 별명으로 불려도 돼요.","sense":"로 불리다"},{"wordId":20491,"answer":"hometowns","form":"복수형","example":"During the holidays, many workers travel back to their hometowns by train.","exampleTranslation":"명절에는 많은 직장인이 기차를 타고 고향으로 돌아간다.","sense":"고향"},{"wordId":20493,"answer":"personalities","form":"복수형","example":"My two dogs have very different personalities, one shy and one loud.","exampleTranslation":"우리 집 개 두 마리는 하나는 수줍고 하나는 시끄러워서 성격이 아주 다르다.","sense":"성격"},{"wordId":20494,"answer":"more down-to-earth","form":"비교급","example":"Our new boss is more down-to-earth than the last one, and she eats with us.","exampleTranslation":"새 상사는 지난번 상사보다 더 소탈해서 우리와 함께 밥을 먹는다.","sense":"소탈한"},{"wordId":20495,"answer":"social butterfly","form":"원형","example":"At the wedding, my aunt was a social butterfly who chatted with every guest.","exampleTranslation":"결혼식에서 이모는 모든 하객과 이야기를 나누는 마당발이었다.","sense":"마당발"},{"wordId":20496,"answer":"perfectionists","form":"복수형","example":"Perfectionists often spend hours fixing tiny details that nobody else notices.","exampleTranslation":"완벽주의자들은 아무도 눈치채지 못하는 작은 부분을 고치느라 몇 시간을 쓰곤 한다.","sense":"완벽주의자"},{"wordId":20497,"answer":"go-getters","form":"복수형","example":"The company hires go-getters who are not afraid to try new ideas.","exampleTranslation":"그 회사는 새로운 아이디어를 두려워하지 않고 시도하는 적극적인 사람들을 뽑는다.","sense":"적극적인 사람"},{"wordId":20498,"answer":"more bubbly","form":"비교급","example":"She seems more bubbly today because her best friend is visiting.","exampleTranslation":"가장 친한 친구가 놀러 와서 그녀는 오늘 더 활기차 보인다.","sense":"활기찬"},{"wordId":20499,"answer":"easy to talk to","form":"원형","example":"I like my new doctor because she is easy to talk to.","exampleTranslation":"새 의사 선생님은 대화하기 편해서 마음에 든다.","sense":"말하기 편한"},{"wordId":20500,"answer":"tell me about yourself","form":"원형","example":"Please tell me about yourself and why you want this job.","exampleTranslation":"당신에 대해, 그리고 이 일을 원하는 이유를 말씀해 주세요.","sense":"자기소개 요청"},{"wordId":20501,"answer":"sit down","form":"원형","example":"You look tired, so why not sit down on this bench for a minute?","exampleTranslation":"피곤해 보이니 이 벤치에 잠깐 앉는 게 어때?","sense":"앉다"},{"wordId":20502,"answer":"get in","form":"원형","example":"The taxi is here, so please get in quickly before the light changes.","exampleTranslation":"택시가 왔으니 신호가 바뀌기 전에 얼른 타세요.","sense":"타다"},{"wordId":20503,"answer":"get out","form":"원형","example":"Please get out of the pool when you hear the whistle.","exampleTranslation":"호루라기 소리가 들리면 수영장에서 나오세요.","sense":"나가다"},{"wordId":20504,"answer":"go ahead","form":"원형","example":"If you are ready to order, please go ahead and tell the waiter.","exampleTranslation":"주문할 준비가 됐으면 어서 웨이터에게 말씀하세요.","sense":"어서 하다"},{"wordId":20505,"answer":"run out","form":"원형","example":"Our printer paper will run out soon, so please order another box.","exampleTranslation":"프린터 용지가 곧 다 떨어질 테니 한 상자 더 주문해 주세요.","sense":"다 떨어지다"},{"wordId":20506,"answer":"get to","form":"원형","example":"How long does it take to get to the airport from your hotel?","exampleTranslation":"호텔에서 공항까지 가는 데 얼마나 걸리나요?","sense":"도착하다"},{"wordId":20507,"answer":"get down","form":"원형","example":"The cat is stuck on the roof and cannot get down by itself.","exampleTranslation":"고양이가 지붕에 갇혀서 혼자 내려오지 못한다.","sense":"내려오다"},{"wordId":20508,"answer":"get on with","form":"원형","example":"After a short coffee break, we should get on with the cleaning.","exampleTranslation":"잠깐 커피를 마시며 쉰 뒤에 청소를 계속해야 한다.","sense":"계속하다"},{"wordId":20509,"answer":"go in","form":"원형","example":"The museum doors open at nine, so we can go in soon.","exampleTranslation":"박물관 문이 아홉 시에 열리니 곧 들어갈 수 있다.","sense":"들어가다"},{"wordId":20510,"answer":"call around","form":"원형","example":"Before buying a new phone, I will call around to compare prices.","exampleTranslation":"새 휴대폰을 사기 전에 여기저기 전화해서 가격을 비교해 볼 거야.","sense":"두루 전화하다"},{"wordId":20511,"answer":"go around","form":"원형","example":"We only have six cookies, so there are not enough to go around.","exampleTranslation":"쿠키가 여섯 개뿐이라 모두에게 돌아가기에는 부족하다.","sense":"돌아가다"},{"wordId":20512,"answer":"come by","form":"원형","example":"The repairman will come by tomorrow morning to fix the heater.","exampleTranslation":"수리 기사가 내일 아침에 난방기를 고치러 들를 것이다.","sense":"들르다"},{"wordId":20513,"answer":"come together","form":"원형","example":"Our neighbors come together every spring to clean up the local park.","exampleTranslation":"우리 이웃들은 매년 봄 동네 공원을 청소하러 모인다.","sense":"모이다"},{"wordId":20514,"answer":"come forward","form":"원형","example":"The school asked any student with information about the lost bag to come forward.","exampleTranslation":"학교는 잃어버린 가방에 대해 아는 학생은 나서 달라고 했다.","sense":"나서다"},{"wordId":20515,"answer":"come apart","form":"원형","example":"Old books can come apart if you open them too roughly.","exampleTranslation":"오래된 책은 너무 거칠게 펼치면 낱장으로 떨어질 수 있다.","sense":"부서지다"},{"wordId":20516,"answer":"come down with","form":"원형","example":"Many kids come down with the flu when the weather turns cold.","exampleTranslation":"날씨가 추워지면 많은 아이들이 독감에 걸린다.","sense":"병에 걸리다"},{"wordId":20517,"answer":"get along with","form":"원형","example":"It is easy to get along with people who share your hobbies.","exampleTranslation":"취미가 같은 사람과는 잘 지내기 쉽다.","sense":"잘 지내다"},{"wordId":20518,"answer":"get across","form":"원형","example":"Simple pictures can help you get across difficult ideas in a presentation.","exampleTranslation":"간단한 그림은 발표에서 어려운 생각을 전달하는 데 도움이 된다.","sense":"전달하다"},{"wordId":20518,"answer":"get across","form":"분리형","gap":"it","example":"The idea is simple, but I can't get it across to him.","exampleTranslation":"아이디어는 간단한데 걔한테 설명이 안 돼.","sense":"(뜻을) 이해시키다"},{"wordId":20519,"answer":"sign in","form":"원형","example":"Visitors must sign in at the front desk before going upstairs.","exampleTranslation":"방문객은 위층에 올라가기 전에 안내 데스크에서 서명하고 입장해야 한다.","sense":"출입 서명하다"},{"wordId":20520,"answer":"sign out","form":"원형","example":"Please sign out of the library computer when you finish your homework.","exampleTranslation":"숙제를 마치면 도서관 컴퓨터에서 로그아웃해 주세요.","sense":"로그아웃하다"},{"wordId":20521,"answer":"put in","form":"원형","example":"We plan to put in a new kitchen sink before the holidays.","exampleTranslation":"우리는 명절 전에 새 주방 싱크대를 설치할 계획이다.","sense":"설치하다"},{"wordId":20521,"answer":"put in","form":"분리형","gap":"it","example":"Here's the new dishwasher. Can you put it in today?","exampleTranslation":"새 식기세척기 왔어요. 오늘 설치해 줄 수 있어요?","sense":"설치하다"},{"wordId":20522,"answer":"put aside","form":"원형","example":"Shall we put aside our argument and enjoy the dinner together?","exampleTranslation":"말다툼은 접어 두고 함께 저녁을 즐길까?","sense":"제쳐 두다"},{"wordId":20522,"answer":"put aside","form":"분리형","gap":"it","example":"That money's for rent, so put it aside.","exampleTranslation":"그 돈은 월세 낼 거니까 따로 빼 둬.","sense":"(돈·시간을) 따로 떼어 두다"},{"wordId":20523,"answer":"take apart","form":"원형","example":"The mechanic had to take apart the engine to find the problem.","exampleTranslation":"정비사는 문제를 찾으려고 엔진을 분해해야 했다.","sense":"분해하다"},{"wordId":20523,"answer":"take apart","form":"분리형","gap":"it","example":"The toy's broken. Let's take it apart and see why.","exampleTranslation":"장난감이 고장 났네. 분해해서 왜 그런지 보자.","sense":"분해하다"},{"wordId":20524,"answer":"keep out","form":"원형","example":"We put up a fence to keep out the neighbor's chickens.","exampleTranslation":"이웃집 닭들이 못 들어오게 울타리를 쳤다.","sense":"못 들어오게 하다"},{"wordId":20524,"answer":"keep out","form":"분리형","gap":"them","example":"The dogs are muddy, so keep them out of the kitchen.","exampleTranslation":"개들이 진흙투성이니까 부엌에 못 들어오게 해.","sense":"못 들어오게 하다"},{"wordId":20525,"answer":"keep off","form":"원형","example":"Please keep off the wet floor until the cleaner says it is dry.","exampleTranslation":"청소하시는 분이 다 말랐다고 할 때까지 젖은 바닥을 밟지 마세요.","sense":"들어가지 않다"},{"wordId":20526,"answer":"keep at","form":"원형","example":"If your guitar practice feels slow, just keep at it every evening.","exampleTranslation":"기타 연습이 더디게 느껴져도 매일 저녁 꾸준히 계속해 봐.","sense":"꾸준히 하다"},{"wordId":20527,"answer":"keep down","form":"원형","example":"We try to keep down our electricity bill by turning off the lights.","exampleTranslation":"우리는 불을 꺼서 전기 요금을 낮추려고 노력한다.","sense":"낮추다"},{"wordId":20527,"answer":"keep down","form":"분리형","gap":"it","example":"The music's too loud. Keep it down!","exampleTranslation":"음악이 너무 커. 좀 줄여!","sense":"(소리·비용을) 낮추다"},{"wordId":20528,"answer":"keep in","form":"원형","example":"It is not healthy to keep in all your anger and sadness.","exampleTranslation":"화와 슬픔을 전부 속에 억누르는 것은 건강에 좋지 않다.","sense":"억누르다"},{"wordId":20528,"answer":"keep in","form":"분리형","gap":"it","example":"Whatever's bugging you, just say it. Don't keep it in.","exampleTranslation":"뭐가 마음에 걸리든 그냥 말해. 속으로 참지 마.","sense":"(감정을) 억누르다"},{"wordId":20529,"answer":"stop by","form":"원형","example":"Can you stop by the pharmacy and pick up my medicine?","exampleTranslation":"약국에 들러서 내 약 좀 받아 올 수 있어?","sense":"잠깐 들르다"},{"wordId":20530,"answer":"step in","form":"원형","example":"When the cashier got busy, the manager had to step in and help.","exampleTranslation":"계산원이 바빠지자 매니저가 나서서 도와야 했다.","sense":"대신 나서다"},{"wordId":20531,"answer":"stand back","form":"원형","example":"Please stand back while I light the candles on the table.","exampleTranslation":"내가 식탁 위 초에 불을 붙이는 동안 물러서 주세요.","sense":"물러서다"},{"wordId":20532,"answer":"start out","form":"원형","example":"Many famous singers start out performing at small cafes downtown.","exampleTranslation":"많은 유명 가수들은 시내의 작은 카페에서 공연하며 시작한다.","sense":"처음 시작하다"},{"wordId":20533,"answer":"start off","form":"원형","example":"I like to start off my day with a short walk and some tea.","exampleTranslation":"나는 짧은 산책과 차 한 잔으로 하루를 시작하는 걸 좋아한다.","sense":"시작하다"},{"wordId":20533,"answer":"start off","form":"분리형","gap":"it","example":"Your speech is first, so start it off with a joke.","exampleTranslation":"네 발표가 첫 순서니까 농담으로 시작해.","sense":"시작하다"},{"wordId":20534,"answer":"start up","form":"원형","example":"My uncle wants to start up a small coffee shop near the beach.","exampleTranslation":"삼촌은 해변 근처에 작은 커피숍을 차리고 싶어 한다.","sense":"창업하다"},{"wordId":20535,"answer":"stay over","form":"원형","example":"My grandparents will stay over at our house during the holidays.","exampleTranslation":"조부모님은 명절 동안 우리 집에서 주무시고 가실 것이다.","sense":"자고 가다"},{"wordId":20536,"answer":"stay on","form":"원형","example":"The coach asked me to stay on for one more season.","exampleTranslation":"코치는 나에게 한 시즌 더 남아 달라고 했다.","sense":"계속 남다"},{"wordId":20537,"answer":"stay behind","form":"원형","example":"I had to stay behind at the office to finish the report.","exampleTranslation":"나는 보고서를 끝내려고 사무실에 남아야 했다.","sense":"남다"},{"wordId":20538,"answer":"look out for","form":"원형","example":"When you hike in the mountains, look out for loose rocks on the trail.","exampleTranslation":"산에서 하이킹할 때는 길에 있는 흔들리는 돌을 조심하세요.","sense":"조심하다"},{"wordId":20539,"answer":"look ahead","form":"원형","example":"Good drivers always look ahead to see what the traffic is doing.","exampleTranslation":"좋은 운전자는 늘 앞을 내다보며 교통 흐름을 살핀다.","sense":"앞을 내다보다"},{"wordId":20540,"answer":"look on","form":"원형","example":"Tourists often look on as the street artists paint in the square.","exampleTranslation":"관광객들은 광장에서 거리 화가들이 그림 그리는 걸 지켜보곤 한다.","sense":"지켜보다"},{"wordId":20541,"answer":"look in on","form":"원형","example":"Could you look in on my grandmother when you pass her house?","exampleTranslation":"할머니 댁을 지나갈 때 잘 계신지 들여다봐 줄래?","sense":"들여다보다"},{"wordId":20542,"answer":"pick up on","form":"원형","example":"Good teachers pick up on small changes in their students' moods.","exampleTranslation":"좋은 선생님은 학생들의 기분에 생긴 작은 변화를 알아차린다.","sense":"알아차리다"},{"wordId":20543,"answer":"hold on to","form":"원형","example":"Please hold on to your ticket until you leave the stadium.","exampleTranslation":"경기장을 나갈 때까지 표를 잘 간직하세요.","sense":"간직하다"},{"wordId":20544,"answer":"lock up","form":"원형","example":"The last person to leave the gym should lock up and turn off the lights.","exampleTranslation":"체육관을 마지막으로 나가는 사람은 문단속하고 불을 꺼야 한다.","sense":"문단속하다"},{"wordId":20544,"answer":"lock up","form":"분리형","gap":"it","example":"That bike's expensive, so make sure you lock it up.","exampleTranslation":"그 자전거 비싸니까 꼭 잠가 둬.","sense":"잠가 두다"},{"wordId":20545,"answer":"lock out","form":"원형","example":"The new system can lock out users who forget to update their passwords.","exampleTranslation":"새 시스템은 비밀번호 변경을 잊은 사용자의 접속을 막을 수 있다.","sense":"접속을 막다"},{"wordId":20545,"answer":"lock out","form":"분리형","gap":"you","example":"Type the wrong password again and it'll lock you out.","exampleTranslation":"비밀번호를 또 틀리면 계정이 잠겨 버려.","sense":"(계정·사람을) 잠가서 못 들어가게 하다"},{"wordId":20546,"answer":"pull up","form":"원형","example":"The driver will pull up in front of the hotel at seven.","exampleTranslation":"운전기사가 일곱 시에 호텔 앞에 차를 세울 것이다.","sense":"차를 세우다"},{"wordId":20546,"answer":"pull up","form":"분리형","gap":"it","example":"Do you have the report? Can you pull it up?","exampleTranslation":"보고서 있어? 화면에 좀 띄워 줄래?","sense":"(자료를) 띄우다"},{"wordId":20547,"answer":"pull away","form":"원형","example":"Wave goodbye before the train starts to pull away from the platform.","exampleTranslation":"기차가 승강장을 떠나기 전에 작별 인사로 손을 흔들어.","sense":"떠나다"},{"wordId":20548,"answer":"pull back","form":"원형","example":"The dog would pull back whenever we tried to give him a bath.","exampleTranslation":"우리가 목욕을 시키려 할 때마다 개는 뒤로 물러서곤 했다.","sense":"물러서다"},{"wordId":20549,"answer":"pull in","form":"원형","example":"Free concerts in the park pull in big crowds every summer.","exampleTranslation":"공원의 무료 콘서트는 매년 여름 많은 사람을 끌어모은다.","sense":"끌어모으다"},{"wordId":20549,"answer":"pull in","form":"분리형","gap":"them","example":"Customers love free samples, so put some out. That'll pull them in.","exampleTranslation":"손님들은 무료 샘플을 좋아하니까 좀 내놔. 그럼 손님들 확 끌어모을 거야.","sense":"(사람·돈을) 끌어모으다"},{"wordId":20550,"answer":"pull down","form":"원형","example":"The city plans to pull down the old factory and build a park.","exampleTranslation":"시는 오래된 공장을 허물고 공원을 지을 계획이다.","sense":"허물다"},{"wordId":20550,"answer":"pull down","form":"분리형","gap":"them","example":"The blinds are open and the sun's glaring. Can you pull them down?","exampleTranslation":"블라인드가 열려서 햇빛이 눈부셔. 좀 내려 줄래?","sense":"(블라인드 등을) 내리다"},{"wordId":20551,"answer":"pull apart","form":"원형","example":"The kids had to pull apart the sticky pages of the old album.","exampleTranslation":"아이들은 오래된 앨범의 달라붙은 페이지를 떼어 내야 했다.","sense":"떼어 놓다"},{"wordId":20551,"answer":"pull apart","form":"분리형","gap":"it","example":"The pork's so tender, you can pull it apart with a fork.","exampleTranslation":"돼지고기가 너무 부드러워서 포크로 쭉 찢어져.","sense":"잡아 뜯다"},{"wordId":20552,"answer":"reach out to","form":"원형","example":"If you feel lonely, you can always reach out to your old friends.","exampleTranslation":"외로우면 언제든 옛 친구들에게 연락하면 돼.","sense":"연락하다"},{"wordId":20553,"answer":"reach for","form":"원형","example":"Babies often reach for anything shiny, like keys or spoons.","exampleTranslation":"아기들은 열쇠나 숟가락처럼 반짝이는 건 뭐든 손을 뻗어 잡으려 한다.","sense":"손을 뻗다"},{"wordId":20554,"answer":"read out","form":"원형","example":"The teacher will read out the test scores at the end of class.","exampleTranslation":"선생님이 수업이 끝날 때 시험 점수를 소리 내어 읽어 주실 것이다.","sense":"소리 내어 읽다"},{"wordId":20554,"answer":"read out","form":"분리형","gap":"it","example":"I can't see the board. Can you read it out for me?","exampleTranslation":"칠판이 안 보여. 나 대신 소리 내어 읽어 줄래?","sense":"소리 내어 읽다"},{"wordId":20555,"answer":"read through","form":"원형","example":"I always read through my emails twice before I send them to my boss.","exampleTranslation":"나는 상사에게 이메일을 보내기 전에 항상 두 번 꼼꼼히 읽는다.","sense":"꼼꼼히 읽다"},{"wordId":20555,"answer":"read through","form":"분리형","gap":"it","example":"It's a long contract, so read it through carefully.","exampleTranslation":"긴 계약서니까 꼼꼼히 끝까지 읽어 봐.","sense":"꼼꼼히 끝까지 읽다"},{"wordId":20556,"answer":"run down","form":"원형","example":"Leaving the car lights on all night can run down the battery.","exampleTranslation":"밤새 차 전조등을 켜 두면 배터리가 닳을 수 있다.","sense":"닳게 하다"},{"wordId":20557,"answer":"run off","form":"원형","example":"The kids run off to the playground as soon as school ends.","exampleTranslation":"아이들은 학교가 끝나자마자 놀이터로 달려간다.","sense":"급히 떠나다"},{"wordId":20558,"answer":"run around","form":"원형","example":"On Saturdays I usually run around town paying bills and buying groceries.","exampleTranslation":"토요일이면 나는 보통 공과금을 내고 장을 보느라 시내를 바쁘게 돌아다닌다.","sense":"바삐 돌아다니다"},{"wordId":20559,"answer":"run across","form":"원형","example":"Sometimes I run across old photos when I clean my closet.","exampleTranslation":"옷장을 정리하다 보면 가끔 옛날 사진을 우연히 발견한다.","sense":"우연히 발견하다"},{"wordId":20560,"answer":"run up against","form":"원형","example":"New drivers often run up against parking problems in big cities.","exampleTranslation":"초보 운전자들은 대도시에서 주차 문제에 자주 부딪힌다.","sense":"부딪히다"},{"wordId":20561,"answer":"mark down","form":"원형","example":"The bakery will mark down its bread by half after six.","exampleTranslation":"그 빵집은 여섯 시 이후에 빵값을 반으로 내릴 것이다.","sense":"가격을 내리다"},{"wordId":20561,"answer":"mark down","form":"분리형","gap":"it","example":"The coat's too pricey, so I'll wait till they mark it down.","exampleTranslation":"코트가 너무 비싸서 값 내릴 때까지 기다릴래.","sense":"가격을 내리다"},{"wordId":20562,"answer":"piece together","form":"원형","example":"After the trip, we tried to piece together our route from old receipts.","exampleTranslation":"여행이 끝난 뒤 우리는 옛 영수증으로 이동 경로를 짜 맞춰 보려 했다.","sense":"짜 맞추다"},{"wordId":20562,"answer":"piece together","form":"분리형","gap":"it","example":"Nobody told me what happened, so I'm trying to piece it together.","exampleTranslation":"아무도 무슨 일인지 안 알려 줘서 내가 짜 맞춰 보는 중이야.","sense":"(정보를) 짜 맞추다"},{"wordId":20563,"answer":"play along","form":"원형","example":"When my nephew pretends to be a doctor, I always play along.","exampleTranslation":"조카가 의사 놀이를 할 때면 나는 늘 장단을 맞춰 준다.","sense":"장단 맞추다"},{"wordId":20564,"answer":"pop in","form":"원형","example":"Feel free to pop in anytime you are near our office.","exampleTranslation":"우리 사무실 근처에 오면 언제든 편하게 들러.","sense":"잠깐 들르다"},{"wordId":20565,"answer":"pop over","form":"원형","example":"My neighbor likes to pop over with fresh cookies on Sunday mornings.","exampleTranslation":"이웃은 일요일 아침마다 갓 구운 쿠키를 들고 잠깐 들르길 좋아한다.","sense":"잠깐 건너가다"},{"wordId":20566,"answer":"think ahead","form":"원형","example":"Smart travelers think ahead and book their hotels months early.","exampleTranslation":"현명한 여행자들은 미리 생각해서 몇 달 전에 호텔을 예약한다.","sense":"미리 생각하다"},{"wordId":20567,"answer":"think up","form":"원형","example":"My kids always think up funny games on rainy afternoons.","exampleTranslation":"우리 아이들은 비 오는 오후마다 재미있는 놀이를 생각해 낸다.","sense":"생각해 내다"},{"wordId":20568,"answer":"think back on","form":"원형","example":"My grandfather loves to think back on his years as a bus driver.","exampleTranslation":"할아버지는 버스 기사로 일하던 시절을 돌이켜 보기를 좋아하신다.","sense":"돌이켜 보다"},{"wordId":20569,"answer":"plan ahead","form":"원형","example":"We need to plan ahead for the wedding because the venue fills up fast.","exampleTranslation":"식장이 빨리 차니까 결혼식을 미리 계획해야 한다.","sense":"미리 계획하다"},{"wordId":20570,"answer":"check back","form":"원형","example":"The doctor is busy now, so please check back in an hour.","exampleTranslation":"의사 선생님이 지금 바쁘시니 한 시간 뒤에 다시 확인해 주세요.","sense":"다시 확인하다"},{"wordId":20571,"answer":"carry around","form":"원형","example":"My grandmother likes to carry around a small notebook for her shopping lists.","exampleTranslation":"할머니는 장보기 목록을 적는 작은 수첩을 들고 다니길 좋아하신다.","sense":"들고 다니다"},{"wordId":20571,"answer":"carry around","form":"분리형","gap":"it","example":"Your bag's heavy, so don't carry it around all day.","exampleTranslation":"가방 무거운데 하루 종일 들고 다니지 마.","sense":"들고 다니다"},{"wordId":20572,"answer":"wait up","form":"원형","example":"My mom will wait up until I get home from the concert.","exampleTranslation":"엄마는 내가 콘서트에서 집에 올 때까지 안 주무시고 기다리실 것이다.","sense":"안 자고 기다리다"},{"wordId":20573,"answer":"wait on","form":"원형","example":"At our family restaurant, my cousins wait on tables every weekend.","exampleTranslation":"우리 가족 식당에서 사촌들이 주말마다 서빙을 한다.","sense":"서빙하다"},{"wordId":20574,"answer":"walk out","form":"원형","example":"Workers might walk out if the company cuts their lunch breaks again.","exampleTranslation":"회사가 점심시간을 또 줄이면 직원들이 항의하며 나가 버릴 수도 있다.","sense":"나가 버리다"},{"wordId":20575,"answer":"walk through","form":"원형","example":"The trainer will walk through the safety rules with every new worker.","exampleTranslation":"트레이너가 모든 신입 직원과 안전 수칙을 차근차근 짚어 볼 것이다.","sense":"차근차근 짚다"},{"wordId":20576,"answer":"walk around","form":"원형","example":"Tourists love to walk around the old market and taste the snacks.","exampleTranslation":"관광객들은 옛 시장을 돌아다니며 간식 맛보기를 좋아한다.","sense":"걸어 다니다"},{"wordId":20577,"answer":"walk in on","form":"원형","example":"I did not mean to walk in on your phone call, and I am sorry.","exampleTranslation":"통화 중에 불쑥 들어가려던 건 아니었어, 미안해.","sense":"불쑥 들어가다"},{"wordId":20578,"answer":"wind up","form":"원형","example":"If you skip breakfast, you might wind up eating junk food later.","exampleTranslation":"아침을 거르면 나중에 결국 정크푸드를 먹게 될지도 몰라.","sense":"결국 하게 되다"},{"wordId":20579,"answer":"write up","form":"원형","example":"The nurse will write up a short report after each visit.","exampleTranslation":"간호사는 방문할 때마다 짧은 보고서를 작성할 것이다.","sense":"작성하다"},{"wordId":20579,"answer":"write up","form":"분리형","gap":"it","example":"The experiment's done, so I'll write it up tonight.","exampleTranslation":"실험은 끝났으니까 오늘 밤에 보고서로 쓸게.","sense":"(보고서 등을) 작성하다"},{"wordId":20580,"answer":"write out","form":"원형","example":"Please write out the recipe so I can make it at home.","exampleTranslation":"집에서 만들 수 있게 그 요리법을 전부 적어 줘.","sense":"전부 적다"},{"wordId":20580,"answer":"write out","form":"분리형","gap":"it","example":"The recipe's complicated, so write it out for me.","exampleTranslation":"레시피가 복잡하니까 전부 적어 줘.","sense":"(전부) 적다"},{"wordId":20581,"answer":"blow out","form":"원형","example":"The strong wind may blow out the candles on our picnic table.","exampleTranslation":"강한 바람이 소풍 테이블 위 초를 꺼 버릴지도 모른다.","sense":"불어 끄다"},{"wordId":20581,"answer":"blow out","form":"분리형","gap":"them","example":"Light the candles, make a wish, and blow them out.","exampleTranslation":"초에 불 붙이고 소원 빈 다음 불어서 꺼.","sense":"(불을) 불어서 끄다"},{"wordId":20582,"answer":"boot up","form":"원형","example":"I boot up my laptop first thing when I get to the office.","exampleTranslation":"나는 사무실에 도착하자마자 노트북부터 켠다.","sense":"부팅하다"},{"wordId":20582,"answer":"boot up","form":"분리형","gap":"it","example":"The laptop's off, so give me a sec to boot it up.","exampleTranslation":"노트북이 꺼져 있어서 잠깐만, 켜 볼게.","sense":"(컴퓨터를) 켜다"},{"wordId":20583,"answer":"call ahead","form":"원형","example":"Please call ahead if you plan to bring more than six people.","exampleTranslation":"여섯 명이 넘게 오실 계획이면 미리 전화해 주세요.","sense":"미리 전화하다"},{"wordId":20584,"answer":"clean out","form":"원형","example":"We need to clean out the fridge before we go on vacation.","exampleTranslation":"휴가 가기 전에 냉장고를 깨끗이 비워야 한다.","sense":"깨끗이 비우다"},{"wordId":20584,"answer":"clean out","form":"분리형","gap":"it","example":"The garage is a mess. Let's clean it out this weekend.","exampleTranslation":"차고가 엉망이야. 이번 주말에 싹 치우자.","sense":"(속을) 깨끗이 치우다"},{"wordId":20585,"answer":"clean off","form":"원형","example":"Use a soft cloth to clean off the dust from your glasses.","exampleTranslation":"부드러운 천으로 안경의 먼지를 닦아 내세요.","sense":"닦아 내다"},{"wordId":20585,"answer":"clean off","form":"분리형","gap":"it","example":"The table's sticky. Can you clean it off?","exampleTranslation":"테이블이 끈적거려. 좀 닦아 줄래?","sense":"(표면을) 닦아 내다"},{"wordId":20586,"answer":"clock out","form":"원형","example":"Most nurses here clock out at seven after a long shift.","exampleTranslation":"이곳 간호사들은 대부분 긴 근무를 마치고 일곱 시에 퇴근 기록을 한다.","sense":"퇴근 기록하다"},{"wordId":20587,"answer":"count down","form":"원형","example":"The whole crowd will count down the last seconds before midnight.","exampleTranslation":"모든 군중이 자정 전 마지막 몇 초를 카운트다운할 것이다.","sense":"카운트다운하다"},{"wordId":20588,"answer":"crank up","form":"원형","example":"On hot days we crank up the air conditioner in the living room.","exampleTranslation":"더운 날이면 우리는 거실 에어컨을 세게 튼다.","sense":"확 높이다"},{"wordId":20588,"answer":"crank up","form":"분리형","gap":"it","example":"I love this song. Crank it up!","exampleTranslation":"이 노래 너무 좋아. 볼륨 확 올려!","sense":"(소리 등을) 확 높이다"},{"wordId":20589,"answer":"cut up","form":"원형","example":"Please cut up the apples into small pieces for the baby.","exampleTranslation":"아기가 먹게 사과를 작게 잘라 주세요.","sense":"잘게 자르다"},{"wordId":20589,"answer":"cut up","form":"분리형","gap":"them","example":"The carrots are too big, so cut them up.","exampleTranslation":"당근이 너무 크니까 잘게 잘라.","sense":"잘게 자르다"},{"wordId":20590,"answer":"dig in","form":"원형","example":"When the pizza arrived, my hungry teammates could not wait to dig in.","exampleTranslation":"피자가 도착하자 배고픈 팀원들은 빨리 먹고 싶어 안달이었다.","sense":"먹기 시작하다"},{"wordId":20591,"answer":"dish out","form":"원형","example":"My uncle loves to dish out advice about money at every family party.","exampleTranslation":"삼촌은 가족 모임마다 돈에 대한 조언을 늘어놓길 좋아한다.","sense":"늘어놓다"},{"wordId":20591,"answer":"dish out","form":"분리형","gap":"it","example":"The stew's ready, so let me dish it out.","exampleTranslation":"스튜 다 됐으니까 내가 퍼 줄게.","sense":"(음식을) 나눠 주다"},{"wordId":20592,"answer":"ease up","form":"원형","example":"The coach told us to ease up a little before the big game.","exampleTranslation":"코치는 큰 경기 전에 강도를 조금 늦추라고 했다.","sense":"강도를 늦추다"},{"wordId":20593,"answer":"ease off","form":"원형","example":"The traffic should ease off after the morning rush hour.","exampleTranslation":"아침 출근 시간이 지나면 교통량이 줄어들 것이다.","sense":"약해지다"},{"wordId":20594,"answer":"fire away","form":"원형","example":"You said you had some questions about the trip, so fire away.","exampleTranslation":"여행에 대해 질문이 있다고 했지, 어서 물어봐.","sense":"어서 하세요"},{"wordId":20595,"answer":"fold up","form":"원형","example":"After the picnic, we fold up the blanket and put it in the car.","exampleTranslation":"소풍이 끝나면 우리는 담요를 개서 차에 넣는다.","sense":"개다"},{"wordId":20595,"answer":"fold up","form":"분리형","gap":"them","example":"The towels are dry, so let's fold them up.","exampleTranslation":"수건 다 말랐으니까 개자.","sense":"개다"},{"wordId":20596,"answer":"freeze up","form":"원형","example":"My old laptop tends to freeze up when I open too many tabs.","exampleTranslation":"내 낡은 노트북은 탭을 너무 많이 열면 멈추곤 한다.","sense":"멈추다"},{"wordId":20597,"answer":"give way","form":"원형","example":"The old bridge might give way if too many trucks cross it.","exampleTranslation":"트럭이 너무 많이 지나가면 낡은 다리가 무너질 수도 있다.","sense":"무너지다"},{"wordId":20598,"answer":"give off","form":"원형","example":"Old fridges can give off a strange smell if you do not clean them.","exampleTranslation":"오래된 냉장고는 청소하지 않으면 이상한 냄새를 낼 수 있다.","sense":"냄새를 내다"},{"wordId":20599,"answer":"go about","form":"원형","example":"I am not sure how to go about asking my boss for a raise.","exampleTranslation":"상사에게 월급 인상을 어떻게 요청해야 할지 모르겠다.","sense":"처리하다"},{"wordId":20600,"answer":"go without","form":"원형","example":"During the camping trip, we had to go without hot showers for three days.","exampleTranslation":"캠핑 여행 동안 우리는 사흘간 뜨거운 샤워 없이 지내야 했다.","sense":"없이 지내다"},{"wordId":20601,"answer":"grow on","form":"원형","example":"The small town may feel boring at first, but it will grow on you.","exampleTranslation":"작은 마을이 처음엔 지루하게 느껴질지 몰라도 점점 좋아질 거야.","sense":"점점 좋아지다"},{"wordId":20602,"answer":"grow out of","form":"원형","example":"My son will grow out of his fear of the dark someday.","exampleTranslation":"우리 아들도 언젠가 커서 어둠을 무서워하지 않게 될 것이다.","sense":"커서 그만두다"},{"wordId":20603,"answer":"jump in","form":"원형","example":"Feel free to jump in if you have an idea during the meeting.","exampleTranslation":"회의 중에 아이디어가 있으면 편하게 끼어들어.","sense":"끼어들다"},{"wordId":20604,"answer":"jump at","form":"원형","example":"Most students would jump at a free trip to the science museum.","exampleTranslation":"대부분의 학생들은 과학관 무료 견학 기회를 덥석 잡을 것이다.","sense":"덥석 잡다"},{"wordId":20605,"answer":"lag behind","form":"원형","example":"Small towns often lag behind big cities in internet speed.","exampleTranslation":"작은 마을은 인터넷 속도에서 대도시보다 뒤처지는 경우가 많다.","sense":"뒤처지다"},{"wordId":20606,"answer":"laugh off","form":"원형","example":"My dad tried to laugh off his bad haircut at dinner.","exampleTranslation":"아빠는 저녁 식사 때 엉망이 된 머리를 웃어넘기려 했다.","sense":"웃어넘기다"},{"wordId":20606,"answer":"laugh off","form":"분리형","gap":"it","example":"He was rude, but just laugh it off.","exampleTranslation":"걔가 무례했지만 그냥 웃어넘겨.","sense":"웃어넘기다"},{"wordId":20607,"answer":"let off","form":"원형","example":"The young driver was let off with a warning this time.","exampleTranslation":"그 젊은 운전자는 이번에는 경고만 받고 풀려났다.","sense":"봐주다"},{"wordId":20607,"answer":"let off","form":"분리형","gap":"you","example":"I'll drive you to the mall and let you off at the door.","exampleTranslation":"쇼핑몰까지 태워 주고 입구에서 내려 줄게.","sense":"(차에서) 내려 주다"},{"wordId":20608,"answer":"let out","form":"원형","example":"The baby will let out a loud cry if you take away her toy.","exampleTranslation":"장난감을 빼앗으면 아기가 크게 울음소리를 낼 것이다.","sense":"소리를 내다"},{"wordId":20608,"answer":"let out","form":"분리형","gap":"it","example":"You've been holding in that laugh all class. Just let it out.","exampleTranslation":"수업 내내 웃음 참고 있었잖아. 그냥 소리 내서 웃어.","sense":"(소리를) 내다"},{"wordId":20609,"answer":"let go of","form":"원형","example":"Please do not let go of the dog's leash on the busy street.","exampleTranslation":"복잡한 길에서는 개 목줄을 놓지 마세요.","sense":"손을 놓다"},{"wordId":20610,"answer":"lighten up","form":"원형","example":"My brother told me to lighten up after I yelled at the video game.","exampleTranslation":"비디오 게임에 소리를 지르자 형이 나한테 너무 심각하게 굴지 말라고 했다.","sense":"기분을 풀다"},{"wordId":20611,"answer":"listen in","form":"원형","example":"My little sister likes to listen in when I talk on the phone.","exampleTranslation":"여동생은 내가 전화 통화할 때 엿듣기를 좋아한다.","sense":"엿듣다"},{"wordId":20612,"answer":"listen up","form":"원형","example":"The coach blew his whistle and shouted, \\"Listen up, team!\\"","exampleTranslation":"코치가 호루라기를 불며 \\"다들 잘 들어!\\"라고 외쳤다.","sense":"잘 들어"},{"wordId":20613,"answer":"live up to","form":"원형","example":"I hope the sequel will live up to the first movie.","exampleTranslation":"속편이 첫 번째 영화만큼 기대에 부응하면 좋겠다.","sense":"부응하다"},{"wordId":20614,"answer":"loosen up","form":"원형","example":"Before every game, the players jog slowly to loosen up their legs.","exampleTranslation":"모든 경기 전에 선수들은 다리를 풀려고 천천히 달린다.","sense":"몸을 풀다"},{"wordId":20614,"answer":"loosen up","form":"분리형","gap":"them","example":"Your shoulders are tight. Let me loosen them up.","exampleTranslation":"어깨가 많이 뭉쳤네. 내가 풀어 줄게.","sense":"몸을 풀다"},{"wordId":20615,"answer":"measure up","form":"원형","example":"The new phone does not measure up to the old model in battery life.","exampleTranslation":"새 휴대폰은 배터리 수명에서 예전 모델에 미치지 못한다.","sense":"기준에 미치다"},{"wordId":20616,"answer":"move around","form":"원형","example":"My job makes me move around a lot, so I rent small apartments.","exampleTranslation":"일 때문에 이사를 자주 다녀서 나는 작은 아파트를 빌린다.","sense":"이리저리 옮겨 다니다"},{"wordId":20616,"answer":"move around","form":"분리형","gap":"it","example":"The sofa looks odd there, so let's move it around.","exampleTranslation":"소파가 거기 있으면 이상하니까 위치를 옮겨 보자.","sense":"이리저리 옮기다"},{"wordId":20617,"answer":"move along","form":"원형","example":"The tour guide asked us to move along to the next room.","exampleTranslation":"관광 안내원이 다음 방으로 이동해 달라고 했다.","sense":"앞으로 가다"},{"wordId":20618,"answer":"move over","form":"원형","example":"Please move over so the little girl can see the parade too.","exampleTranslation":"그 꼬마도 퍼레이드를 볼 수 있게 조금 비켜 주세요.","sense":"비켜 주다"},{"wordId":20619,"answer":"note down","form":"원형","example":"Please note down the time of your doctor appointment on the calendar.","exampleTranslation":"달력에 병원 예약 시간을 적어 두세요.","sense":"적어 두다"},{"wordId":20619,"answer":"note down","form":"분리형","gap":"it","example":"That's a great idea. Let me note it down.","exampleTranslation":"좋은 생각이네. 적어 둘게.","sense":"적어 두다"},{"wordId":20620,"answer":"pack away","form":"원형","example":"After the holidays, we pack away the decorations in the basement.","exampleTranslation":"명절이 끝나면 우리는 장식품을 지하실에 넣어 치운다.","sense":"넣어 치우다"},{"wordId":20620,"answer":"pack away","form":"분리형","gap":"them","example":"Your summer clothes take up space, so pack them away.","exampleTranslation":"여름옷이 자리 차지하니까 넣어 둬.","sense":"(짐을) 넣어 치우다"},{"wordId":20621,"answer":"pay up","form":"원형","example":"My roommate still owes me fifty dollars, and he promised to pay up by Friday.","exampleTranslation":"룸메이트는 아직 나한테 오십 달러를 빚졌는데 금요일까지 갚겠다고 약속했다.","sense":"갚다"},{"wordId":20622,"answer":"play up","form":"원형","example":"Travel ads always play up the sunny beaches and hide the crowds.","exampleTranslation":"여행 광고는 늘 화창한 해변을 부각하고 붐비는 인파는 숨긴다.","sense":"부각하다"},{"wordId":20622,"answer":"play up","form":"분리형","gap":"it","example":"Your teaching experience is a plus, so play it up in the interview.","exampleTranslation":"가르친 경험이 강점이니까 면접에서 부각해.","sense":"강조하다"},{"wordId":20623,"answer":"polish off","form":"원형","example":"My grandfather can polish off a big bowl of noodles in minutes.","exampleTranslation":"할아버지는 큰 국수 한 그릇을 몇 분 만에 싹 비우신다.","sense":"먹어 치우다"},{"wordId":20623,"answer":"polish off","form":"분리형","gap":"it","example":"You made a huge pizza, but we'll polish it off.","exampleTranslation":"피자를 엄청 크게 만들었지만 우리가 싹 먹어 치울 거야.","sense":"(음식을) 싹 먹어 치우다"},{"wordId":20624,"answer":"print off","form":"원형","example":"I will print off our boarding passes before we leave for the airport.","exampleTranslation":"공항으로 출발하기 전에 탑승권을 출력해 둘게.","sense":"출력하다"},{"wordId":20624,"answer":"print off","form":"분리형","gap":"them","example":"The handouts are ready, so go ahead and print them off.","exampleTranslation":"자료 준비됐으니까 바로 출력해.","sense":"(여러 장) 출력하다"},{"wordId":20625,"answer":"pump up","form":"원형","example":"The coach played loud music to pump up the team before the game.","exampleTranslation":"코치는 경기 전에 팀의 기운을 북돋우려고 큰 음악을 틀었다.","sense":"기운을 북돋우다"},{"wordId":20625,"answer":"pump up","form":"분리형","gap":"it","example":"The bike tire's low. Can you pump it up?","exampleTranslation":"자전거 타이어 바람이 빠졌어. 좀 넣어 줄래?","sense":"(공기를) 넣다"},{"wordId":20626,"answer":"rattle off","form":"원형","example":"The waiter can rattle off all the daily specials without a note.","exampleTranslation":"그 웨이터는 메모 없이 오늘의 특선 요리를 전부 줄줄 읊는다.","sense":"줄줄 읊다"},{"wordId":20626,"answer":"rattle off","form":"분리형","gap":"it","example":"He knows the menu by heart and can rattle it off.","exampleTranslation":"걔는 메뉴를 다 외워서 줄줄 읊을 수 있어.","sense":"줄줄 읊다"},{"wordId":20627,"answer":"rip off","form":"원형","example":"Some online shops rip off customers with hidden delivery fees.","exampleTranslation":"어떤 온라인 상점은 숨겨진 배송비로 손님들에게 바가지를 씌운다.","sense":"바가지 씌우다"},{"wordId":20627,"answer":"rip off","form":"분리형","gap":"you","example":"Always check the price, or they'll rip you off.","exampleTranslation":"항상 가격을 확인해. 안 그러면 바가지 써.","sense":"바가지 씌우다"},{"wordId":20628,"answer":"rip up","form":"원형","example":"My little sister likes to rip up old magazines for her art projects.","exampleTranslation":"내 여동생은 미술 작품을 만들려고 낡은 잡지를 찢는 걸 좋아한다.","sense":"찢다"},{"wordId":20628,"answer":"rip up","form":"분리형","gap":"it","example":"That letter's from my ex. I'm going to rip it up.","exampleTranslation":"그 편지 전 애인이 보낸 거야. 찢어 버릴 거야.","sense":"갈기갈기 찢다"},{"wordId":20629,"answer":"roll up","form":"원형","example":"Please roll up the yoga mats and put them back on the shelf.","exampleTranslation":"요가 매트를 말아서 선반에 다시 올려 두세요.","sense":"말다"},{"wordId":20629,"answer":"roll up","form":"분리형","gap":"them","example":"Your sleeves are getting wet, so roll them up.","exampleTranslation":"소매 젖고 있어. 걷어 올려.","sense":"(소매 등을) 걷어 올리다"}]`);export{e as default};